# 15  MEMORY USAGE & PER-TAB RAM
# ====================================================================================================

def trim_memory(deep=True):
    """Collect garbage and hand freed heap pages back to the OS (Python's allocator otherwise keeps them).
    deep=False is for when the person is using the browser: a full collection and especially the Windows working-set trim
    make the next clicks stall while pages fault back in, so only the young generations are collected then."""
    if not deep:
        gc.collect(1)
        return
    gc.collect()
    try:
        if sys.platform.startswith("linux"):
            import ctypes
            ctypes.CDLL("libc.so.6").malloc_trim(0)
        elif sys.platform == "win32":
            import ctypes
            k = ctypes.windll.kernel32
            k.GetCurrentProcess.restype = ctypes.c_void_p
            k.SetProcessWorkingSetSize.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_size_t]
            k.SetProcessWorkingSetSize(k.GetCurrentProcess(), ctypes.c_size_t(-1), ctypes.c_size_t(-1))
    except Exception:
        pass


_PSUTIL = [None]     # None = not tried yet, False = not installed
_PS_PROCS = {}
_WIN_PMC = []


def _psutil():
    if _PSUTIL[0] is None:
        try:
            import psutil
            _PSUTIL[0] = psutil
        except ImportError:
            _PSUTIL[0] = False
    return _PSUTIL[0]


def process_rss_mb(pid):
    """Resident memory of a process in MB (None if it can't be read). Works with or without psutil."""
    if not pid or pid <= 0:
        return None
    try:
        ps_mod = _psutil()
        if ps_mod:
            try:
                pr = _PS_PROCS.get(pid)
                if pr is None:
                    if len(_PS_PROCS) > 64:
                        _PS_PROCS.clear()
                    pr = _PS_PROCS[pid] = ps_mod.Process(pid)
                return pr.memory_info().rss / 1048576.0
            except Exception:
                _PS_PROCS.pop(pid, None)
                return None
        if sys.platform.startswith("linux"):
            with open("/proc/%d/statm" % pid) as f:
                return int(f.read().split()[1]) * os.sysconf("SC_PAGE_SIZE") / 1048576.0
        if sys.platform == "win32":
            import ctypes
            from ctypes import wintypes

            if not _WIN_PMC:
                class PMC(ctypes.Structure):
                    _fields_ = [("cb", wintypes.DWORD), ("PageFaultCount", wintypes.DWORD),
                                ("PeakWorkingSetSize", ctypes.c_size_t), ("WorkingSetSize", ctypes.c_size_t),
                                ("QuotaPeakPagedPoolUsage", ctypes.c_size_t), ("QuotaPagedPoolUsage", ctypes.c_size_t),
                                ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t), ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                                ("PagefileUsage", ctypes.c_size_t), ("PeakPagefileUsage", ctypes.c_size_t)]
                _WIN_PMC.append(PMC)
            PMC = _WIN_PMC[0]
            k, ps = ctypes.windll.kernel32, ctypes.windll.psapi
            k.OpenProcess.restype = wintypes.HANDLE
            h = k.OpenProcess(0x1000 | 0x0010, False, pid)
            if not h:
                return None
            try:
                pmc = PMC()
                pmc.cb = ctypes.sizeof(PMC)
                ps.GetProcessMemoryInfo.argtypes = [wintypes.HANDLE, ctypes.POINTER(PMC), wintypes.DWORD]
                if ps.GetProcessMemoryInfo(h, ctypes.byref(pmc), pmc.cb):
                    return pmc.WorkingSetSize / 1048576.0
            finally:
                k.CloseHandle(h)
            return None
        import subprocess
        out = subprocess.run(["ps", "-o", "rss=", "-p", str(pid)], capture_output=True, text=True, timeout=2).stdout.strip()
        return int(out) / 1024.0 if out else None
    except Exception:
        return None


def fmt_mem(mb):
    return "%.1f GB" % (mb / 1024.0) if mb >= 1000 else "%d MB" % round(mb)


NORD_HEAT = [
    (0, (100, 150, 235)),
    (100, (110, 180, 255)),
    (200, (120, 225, 245)),
    (400, (150, 230, 130)),
    (600, (255, 225, 100)),
    (800, (255, 150, 90)),
    (1000, (255, 95, 110)),
]


RAM_HEAT = {
    "default": NORD_HEAT,
    "mac": [(0, (10, 132, 255)), (100, (64, 156, 255)), (200, (90, 200, 250)), (400, (48, 209, 88)),
            (600, (255, 214, 10)), (800, (255, 159, 10)), (1000, (255, 69, 58))],
    "windows": [(0, (76, 160, 255)), (100, (96, 205, 255)), (200, (88, 214, 214)), (400, (108, 203, 95)),
                (600, (252, 225, 0)), (800, (255, 140, 0)), (1000, (255, 99, 97))],
}


def heat_color(mb, alpha=255):
    """Gradient from a cool blue (light tab) to red (heavy tab), in the palette of the current interface style."""
    stops = RAM_HEAT.get(UI["mode"], NORD_HEAT)
    if mb <= stops[0][0]:
        rgb = stops[0][1]
    elif mb >= stops[-1][0]:
        rgb = stops[-1][1]
    else:
        rgb = stops[-1][1]
        for (m0, c0), (m1, c1) in zip(stops, stops[1:]):
            if m0 <= mb <= m1:
                f = (mb - m0) / (m1 - m0)
                rgb = tuple(int(c0[k] + (c1[k] - c0[k]) * f) for k in range(3))
                break
    return QColor(rgb[0], rgb[1], rgb[2], alpha)


