class SwitchToggle(QAbstractButton):
    """A small on/off switch."""

    def __init__(self, on=False):
        super().__init__()
        self.animated = False
        self._t = 1.0 if on else 0.0
        self._tanim = None
        self.setCheckable(True)
        self.setChecked(on)
        self.setFixedSize(42, 24)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.toggled.connect(self._on_toggled)

    def _on_toggled(self, on):
        target = 1.0 if on else 0.0
        if self._tanim is not None:
            self._tanim.stop()
        if not self.animated or not self.isVisible():
            self._t = target
            self.update()
            return
        a = QVariantAnimation(self)
        a.setStartValue(float(self._t))
        a.setEndValue(target)
        a.setDuration(170)
        a.setEasingCurve(QEasingCurve.Type.OutCubic)

        def step(v):
            self._t = float(v)
            self.update()
        a.valueChanged.connect(step)
        self._tanim = a
        a.start()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        on, win, ena = self.isChecked(), UI["mode"] == "windows", self.isEnabled()
        t = self._t if self.animated else (1.0 if on else 0.0)
        acc = QColor(ACCENT["main"])
        off = QColor(themed("#3f5163"))
        if not ena:
            acc.setAlpha(90)
            off.setAlpha(120)
        rad = r.height() / 2 if UI["mode"] != "windows" else r.height() / 2
        if win and not on:
            p.setPen(QPen(QColor(themed("#8ea3b4")) if ena else off, 1.3))
            p.setBrush(Qt.BrushStyle.NoBrush)
        else:
            p.setPen(Qt.PenStyle.NoPen)
            if self.animated and not win:
                track = QColor(int(off.red() + (acc.red() - off.red()) * t), int(off.green() + (acc.green() - off.green()) * t),
                               int(off.blue() + (acc.blue() - off.blue()) * t), int(off.alpha() + (acc.alpha() - off.alpha()) * t))
                p.setBrush(track)
            else:
                p.setBrush(acc if on else off)
        p.drawRoundedRect(r, rad, rad)
        d = r.height() - (8 if win else 6)
        x_off, x_on = r.left() + (4 if win else 3), r.right() - d - 4
        x = x_off + (x_on - x_off) * t
        if win:
            knob = QColor("#0b141d") if on else QColor(themed("#8ea3b4"))
        else:
            knob = QColor("#ffffff" if ena else "#9aa8b4")
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(knob)
        p.drawEllipse(QRectF(x, r.top() + (r.height() - d) / 2, d, d))
        p.end()


def glass_base_window(widget):
    """The window a popup floats over (skipping parent menus), or None if there isn't a sensible one."""
    w = widget.parentWidget()
    while w is not None and isinstance(w, _QMenu):
        w = w.parentWidget()
    base = w.window() if w is not None else QApplication.activeWindow()
    if base is None or base is widget or isinstance(base, _QMenu) or base.windowType() == Qt.WindowType.Popup:
        return None
    return base


def _usable_grab(img):
    if img is None or img.isNull() or img.width() < 4 or img.height() < 4:
        return False
    samples = {img.pixel(img.width() * i // 5, img.height() * j // 5) for i in range(1, 5) for j in range(1, 5)}
    return not (len(samples) == 1 and (next(iter(samples)) & 0xFFFFFF) == 0)


def glass_backdrop(widget, base):
    """A blurred copy of whatever sits behind a popup, for the macOS glass to frost. The popup has not been drawn yet when this
    runs, so the pixels under it are read straight from the screen (that includes the GPU-drawn web page); if that fails the
    parent window is grabbed instead. None when neither works, in which case the glass is simply more solid."""
    img = None
    try:
        scr = widget.screen()
        if scr is not None:
            g, gp = scr.geometry(), widget.pos()
            pm = scr.grabWindow(0, gp.x() - g.x(), gp.y() - g.y(), widget.width(), widget.height())
            if not pm.isNull() and _usable_grab(pm.toImage()):
                img = pm.toImage()
    except Exception:
        img = None
    if img is None and base is not None:
        try:
            rect = QRect(base.mapFromGlobal(widget.pos()), widget.size())
            part = rect.intersected(base.rect())
            if rect.width() >= 8 and rect.height() >= 8 and part.width() >= 4 and part.height() >= 4:
                got = base.grab(part).toImage()
                if _usable_grab(got):
                    if part != rect:
                        k = got.width() / float(part.width())
                        canvas = QImage(max(1, int(rect.width() * k)), max(1, int(rect.height() * k)), QImage.Format.Format_ARGB32_Premultiplied)
                        canvas.fill(QColor(themed("#101b26")))
                        cp = QPainter(canvas)
                        cp.drawImage(int((part.x() - rect.x()) * k), int((part.y() - rect.y()) * k), got)
                        cp.end()
                        got = canvas
                    img = got
        except Exception:
            log_error("glass backdrop")
            img = None
    if img is None:
        return None
    try:
        img = img.convertToFormat(QImage.Format.Format_RGB32)
        sm, ar = Qt.TransformationMode.SmoothTransformation, Qt.AspectRatioMode.IgnoreAspectRatio
        tiny = img.scaled(max(1, img.width() // 9), max(1, img.height() // 9), ar, sm)
        mid = tiny.scaled(max(1, img.width() // 3), max(1, img.height() // 3), ar, sm)
        return QPixmap.fromImage(mid.scaled(img.size(), ar, sm))
    except Exception:
        log_error("glass backdrop blur")
        return None


class BlurScrim(QWidget):
    """Blurs and softly darkens the whole browser window while a popup is open, so the popup stands out and the page behind it
    recedes. It is a picture of the window taken just before the popup appears (read from the screen, which includes the
    GPU-drawn web page; the window's own grab is the fallback), blurred, and faded in. If neither grab works it is a plain dim."""
    def __init__(self, base):
        super().__init__(base)
        self.setObjectName("blurscrim")
        self.setGeometry(base.rect())
        self.pm = self._grab(base)
        self.raise_()
        self.show()
        fade_widget(self, 0.0, 1.0, 220)

    @staticmethod
    def _grab(base):
        try:
            scr = base.screen()
            if scr is not None:
                g, tl = scr.geometry(), base.mapToGlobal(QPoint(0, 0))
                pm = scr.grabWindow(0, tl.x() - g.x(), tl.y() - g.y(), base.width(), base.height())
                if not pm.isNull() and _usable_grab(pm.toImage()):
                    return blur_pixmap(pm)
        except Exception:
            pass
        try:
            pm = base.grab()
            if _usable_grab(pm.toImage()):
                return blur_pixmap(pm)
        except Exception:
            log_error("blur scrim")
        return None

    def paintEvent(self, e):
        p = QPainter(self)
        try:
            if self.pm is not None:
                p.drawPixmap(self.rect(), self.pm)
            else:
                p.fillRect(self.rect(), QColor(themed("#0b141d")))
            if term_on():
                p.fillRect(self.rect(), QColor(0, 10, 3, 150))
            else:
                p.fillRect(self.rect(), QColor(6, 12, 18, 120 if self.pm is not None else 210))
        finally:
            p.end()

    def dismiss(self):
        try:
            fade_widget(self, 1.0, 0.0, 160, done=self._gone)
        except RuntimeError:
            self._gone()

    def _gone(self):
        try:
            self.hide()
            self.deleteLater()
        except RuntimeError:
            pass


def paint_glass_panel(p, rect, radius, blur, base="#172431"):
    """One frosted-glass panel: blurred backdrop, a tint that follows Settings > Glass transparency, then the toolbar's glass edge.
    Used by every popup in the macOS style so they all match."""
    r = QRectF(rect)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    rad = max(0.0, min(rr(radius), r.width() / 2.0, r.height() / 2.0))
    path = QPainterPath()
    path.addRoundedRect(r.adjusted(0.5, 0.5, -0.5, -0.5), rad, rad)
    p.save()
    p.setClipPath(path)
    if blur is not None:
        p.drawPixmap(r.toRect(), blur)
    tint = QColor(themed(base))
    a = 215 - 1.5 * UI["transp"]
    tint.setAlpha(int(max(70, min(235, a)) if blur is not None else max(205, min(240, a + 75))))
    p.fillPath(path, tint)
    p.restore()
    paint_glass(p, r, radius, 1.0)

TERM_BG, TERM_EDGE, TERM_BRIGHT, TERM_TEXT, TERM_DIM, TERM_WARN = "#030704", "#12b84a", "#2bff6a", "#8dffb0", "#12b84a", "#ffd24a"


def paint_term_panel(p, rect, radius=2.0, alpha=250):
    """A terminal pane: near-black fill, green hairline border and faint scanlines. Used by the popups and the command palette
    in private windows with Terminal style on."""
    r = QRectF(rect).adjusted(0.5, 0.5, -0.5, -0.5)
    bg = QColor(TERM_BG)
    bg.setAlpha(alpha)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    path.addRoundedRect(r, radius, radius)
    p.fillPath(path, bg)
    p.setClipPath(path)
    p.setPen(QPen(QColor(43, 255, 106, 11), 1))
    for yy in range(1, int(r.height()), 3):
        p.drawLine(QPointF(r.left(), r.top() + yy), QPointF(r.right(), r.top() + yy))
    p.setClipping(False)
    p.setPen(QPen(QColor(TERM_EDGE), 1))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.drawPath(path)
    p.restore()


def drawer_skin():
    """Which look the Scratchpad drawer wear: 'term' (private window with Terminal style on), otherwise the interface
    style: 'mac' (frosted glass), 'windows' (flat Fluent) or 'default'."""
    return "term" if term_on() else UI["mode"]


def _glass_blur(img):
    """Soften a grabbed image into frosted-glass backdrop (same blur as glass_backdrop)."""
    if img is None:
        return None
    try:
        img = img.convertToFormat(QImage.Format.Format_RGB32)
        sm, ar = Qt.TransformationMode.SmoothTransformation, Qt.AspectRatioMode.IgnoreAspectRatio
        tiny = img.scaled(max(1, img.width() // 9), max(1, img.height() // 9), ar, sm)
        mid = tiny.scaled(max(1, img.width() // 3), max(1, img.height() // 3), ar, sm)
        return QPixmap.fromImage(mid.scaled(img.size(), ar, sm))
    except Exception:
        log_error("drawer glass blur")
        return None


def glass_backdrop_rect(widget, root, rect):
    """Blurred copy of what sits behind `rect` (in `root` coordinates), for a docked drawer that is not shown yet. Reads the
    screen first (that includes the GPU-drawn page) and falls back to grabbing the parent widget."""
    img = None
    try:
        scr = widget.screen()
        if scr is not None and rect.width() >= 8 and rect.height() >= 8:
            g, gp = scr.geometry(), root.mapToGlobal(rect.topLeft())
            pm = scr.grabWindow(0, gp.x() - g.x(), gp.y() - g.y(), rect.width(), rect.height())
            if not pm.isNull() and _usable_grab(pm.toImage()):
                img = pm.toImage()
    except Exception:
        img = None
    if img is None:
        try:
            part = rect.intersected(root.rect())
            if part.width() >= 4 and part.height() >= 4:
                got = root.grab(part).toImage()
                if _usable_grab(got):
                    img = got
        except Exception:
            log_error("drawer glass grab")
            img = None
    return _glass_blur(img)


class DrawerSkin:
    """Mixin for the docked Scratchpad drawer: paints each interface style's own look behind the widgets
    (macOS: frosted glass like the privacy popup; Terminal: black with faint scanlines). Windows and Default are pure QSS."""
    _skin_blur = None
    _skin_geo = None

    def skin_remember(self, x, y, w, h):
        self._skin_geo = (x, y, w, h)

    def skin_capture(self):
        """Call right before the drawer is shown (so it is not in its own capture)."""
        if drawer_skin() != "mac" or self._skin_geo is None or self.parentWidget() is None:
            self._skin_blur = None
            return
        x, y, w, h = self._skin_geo
        try:
            self._skin_blur = glass_backdrop_rect(self, self.parentWidget(), QRect(x, y, w, h))
        except Exception:
            log_error("drawer glass backdrop")
            self._skin_blur = None

    def skin_paint(self):
        sk = drawer_skin()
        if sk not in ("mac", "term") or self.width() < 2:
            return
        p = QPainter(self)
        try:
            full = QRect(0, 0, max(self.width(), getattr(self, "full", self.width())), self.height())
            p.setClipRect(self.rect())
            if sk == "mac":
                paint_glass_panel(p, full, 20, self._skin_blur, "#101b26")
            else:
                p.setPen(QPen(QColor(43, 255, 106, 11), 1))
                for yy in range(1, full.height(), 3):
                    p.drawLine(0, yy, full.width(), yy)
        except Exception:
            log_error("drawer skin paint")
        finally:
            p.end()


_GHOSTS = set()   # fading menu snapshots, kept alive until their animation ends


class QMenu(_QMenu):
    """Fjord's menu. In the macOS style it is a see-through window painted as frosted glass (same look as the privacy popup);
    in the other styles it is Qt's normal menu. Every menu in the app (the ⋯ menu, right-click menus...) is one of these."""

    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self._glass = UI["mode"] == "mac"
        self._blur = None
        self._intro_run = False
        if self._glass:
            self.setProperty("glass", True)
            self.setWindowFlag(Qt.WindowType.FramelessWindowHint, True)
            self.setWindowFlag(Qt.WindowType.NoDropShadowWindowHint, True)
            self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)

    def showEvent(self, e):
        if self._glass:
            self._blur = glass_backdrop(self, glass_base_window(self))
        super().showEvent(e)
        if self._intro_run:
            return
        self._intro_run = True
        sub = isinstance(self.parentWidget(), _QMenu)
        self.setWindowOpacity(0.0)

        def go():
            try:
                if not self.isVisible():
                    self.setWindowOpacity(1.0)
                    return
                from PyQt6.QtCore import QParallelAnimationGroup
                end = self.pos()
                if sub:   # a submenu glides out sideways from the edge of its parent
                    par = self.parentWidget().geometry()
                    dx, dy = (-14 if self.x() >= par.center().x() else 14), 0
                else:     # a main menu drops from the button (or rises, if it opened upwards)
                    dx, dy = 0, (14 if self.geometry().bottom() <= QCursor.pos().y() + 2 else -14)
                grp = QParallelAnimationGroup(self)
                fade = QPropertyAnimation(self, b"windowOpacity", self)
                fade.setDuration(150 if sub else 190)
                fade.setStartValue(0.0)
                fade.setEndValue(1.0)
                grp.addAnimation(fade)
                slide = QPropertyAnimation(self, b"pos", self)
                slide.setDuration(220 if sub else 300)
                slide.setStartValue(end + QPoint(dx, dy))
                slide.setEndValue(end)
                slide.setEasingCurve(mac_curve(spring=True, overshoot=0.7) if UI["mode"] == "mac" else ui_ease())
                grp.addAnimation(slide)
                self.move(end + QPoint(dx, dy))
                self._intro_grp = grp
                grp.start()
            except RuntimeError:
                pass
        QTimer.singleShot(0, go)

    def hideEvent(self, e):
        self._intro_run = False
        super().hideEvent(e)

    def setVisible(self, vis):
        if not vis and self.isVisible():
            try:
                self._ghost_out()
            except Exception:
                log_error("menu close animation")
        super().setVisible(vis)

    def _ghost_out(self):
        """Qt hides a menu the instant an item is picked. To fade it out anyway, a see-through snapshot of the menu is left behind
        in the same spot (ignoring the mouse) that slides up a little and fades away."""
        if self.windowOpacity() < 0.3 or self.width() < 8 or self.height() < 8:
            return
        pm = self.grab()
        ghost = QLabel(None, Qt.WindowType.Tool | Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint
                       | Qt.WindowType.WindowTransparentForInput | Qt.WindowType.NoDropShadowWindowHint)
        ghost.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        ghost.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        ghost.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        ghost.setStyleSheet("QLabel{background:transparent;border:none;padding:0;margin:0}")
        ghost.setPixmap(pm)
        geo = self.geometry()
        ghost.setGeometry(geo)
        sub = isinstance(self.parentWidget(), _QMenu)
        from PyQt6.QtCore import QParallelAnimationGroup
        _GHOSTS.add(ghost)
        ghost.show()
        grp = QParallelAnimationGroup(ghost)
        fade = QPropertyAnimation(ghost, b"windowOpacity", ghost)
        fade.setDuration(130 if sub else 160)
        fade.setStartValue(1.0)
        fade.setEndValue(0.0)
        fade.setEasingCurve(QEasingCurve.Type.InCubic)
        grp.addAnimation(fade)
        if not sub:
            slide = QPropertyAnimation(ghost, b"pos", ghost)
            slide.setDuration(160)
            slide.setStartValue(geo.topLeft())
            slide.setEndValue(geo.topLeft() + QPoint(0, -10))
            slide.setEasingCurve(QEasingCurve.Type.InCubic)
            grp.addAnimation(slide)

        def gone():
            _GHOSTS.discard(ghost)
            try:
                ghost.hide()
                ghost.deleteLater()
            except RuntimeError:
                pass
        grp.finished.connect(gone)
        grp.start()

    def paintEvent(self, e):
        if self._glass:
            p = QPainter(self)
            paint_glass_panel(p, self.rect(), 14, self._blur, "#132029")
            p.end()
        super().paintEvent(e)


class GlassListView(QListView):
    """The address bar's suggestion list. In the macOS style it is painted as the same frosted glass as the menus."""

    def __init__(self, base_window=None):
        super().__init__()
        self._base = base_window
        self._blur = None
        self._glass = False
        self.sync_mode()

    def sync_mode(self):
        """Called whenever the style changes: only the macOS style needs a see-through window."""
        self._glass = UI["mode"] == "mac"
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, self._glass)

    def _grab(self):
        self._blur = glass_backdrop(self, self._base if self._base is not None else QApplication.activeWindow()) if self._glass else None

    def showEvent(self, e):
        self._grab()
        super().showEvent(e)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if self._glass and self.isVisible():
            self._grab()

    def paintEvent(self, e):
        if self._glass:
            p = QPainter(self.viewport())
            paint_glass_panel(p, self.viewport().rect(), 14, self._blur, "#132029")
            p.end()
        super().paintEvent(e)


def style_completer_popup(pop):
    pop.setStyleSheet(themed(popup_qss()))
    if isinstance(pop, GlassListView):
        pop.sync_mode()


# ====================================================================================================
# 21b  BORDERLESS DIALOGS (every dialog draws its own frame, title and close button in the current look)
# ====================================================================================================

def dialog_qss():
    """Stylesheet for the inside of a Fjord dialog, per look: Terminal, macOS, Windows or Default."""
    acc = ACCENT["main"]
    base = "QDialog#fjorddlg, QWidget#dlgbody { background: transparent; }"
    if term_on():
        return base + (
            "QLabel { color:#8dffb0; background:transparent; } QLabel#dlgsub { color:#12b84a; }"
            "QLineEdit, QKeySequenceEdit { background:#000000; color:#8dffb0; border:1px solid #12b84a; border-radius:2px;"
            " padding:6px 8px; selection-background-color:#12b84a; selection-color:#030704; }"
            "QLineEdit:focus, QKeySequenceEdit:focus { border:1px solid #2bff6a; }"
            "QPushButton { background:transparent; color:#2bff6a; border:1px solid #12b84a; border-radius:2px; padding:6px 16px; min-width:64px; }"
            "QPushButton:hover { background:#2bff6a; color:#030704; }"
            "QPushButton:disabled { color:#0d7a31; border:1px solid #0d4d22; background:transparent; }"
            "QPushButton[primary=\"true\"] { border:1px solid #2bff6a; }"
            "QAbstractItemView { background:#000000; color:#8dffb0; border:1px solid #12b84a; border-radius:2px; outline:none; }"
            "QAbstractItemView::item:selected { background:#12b84a; color:#030704; }"
            "QHeaderView::section { background:#030704; color:#12b84a; border:none; padding:4px 6px; }"
            "QComboBox { background:#000000; color:#8dffb0; border:1px solid #12b84a; border-radius:2px; padding:4px 8px; }"
            "QComboBox QAbstractItemView { background:#030704; selection-background-color:#12b84a; selection-color:#030704; }"
            "QToolButton { background:transparent; color:#2bff6a; border:1px solid transparent; border-radius:2px; }"
            "QToolButton:hover { border:1px solid #12b84a; }"
            "QSpinBox, QTextEdit { background:#000000; color:#8dffb0; border:1px solid #12b84a; border-radius:2px; }")
    mode = UI["mode"]
    if mode == "mac":
        edit = ("QLineEdit, QKeySequenceEdit { background:rgba(255,255,255,0.07); color:#e4edf3; border:1px solid rgba(255,255,255,0.12);"
                " border-radius:14px; padding:7px 14px; selection-background-color:%s; selection-color:#0b141d; }"
                "QLineEdit:focus, QKeySequenceEdit:focus { background:rgba(255,255,255,0.10); border:1px solid %s; }" % (acc, acc))
        prim = ("QPushButton[primary=\"true\"] { background:rgba(79,176,232,0.38); color:#ffffff; border:1px solid rgba(255,255,255,0.22); }"
                "QPushButton[primary=\"true\"]:hover { background:rgba(79,176,232,0.52); }")
        rad = "10px"
    elif mode == "windows":
        edit = ("QLineEdit, QKeySequenceEdit { background:rgba(255,255,255,0.06); color:#e4edf3; border:1px solid rgba(255,255,255,0.08);"
                " border-bottom:1px solid rgba(255,255,255,0.35); border-radius:5px; padding:6px 10px;"
                " selection-background-color:%s; selection-color:#0b141d; }"
                "QLineEdit:focus, QKeySequenceEdit:focus { background:#1c2b3a; border:1px solid rgba(255,255,255,0.08);"
                " border-bottom:2px solid %s; }" % (acc, acc))
        prim = ("QPushButton[primary=\"true\"] { background:#4fb0e8; color:#0b141d; border:none; font-weight:600; }"
                "QPushButton[primary=\"true\"]:hover { background:rgba(79,176,232,0.86); }")
        rad = "5px"
    else:
        edit = ("QLineEdit, QKeySequenceEdit { background:#1c2b3a; color:#e4edf3; border:1px solid #2b3f54; border-radius:10px; padding:7px 12px;"
                " selection-background-color:%s; selection-color:#0b141d; }"
                "QLineEdit:focus, QKeySequenceEdit:focus { border:1px solid %s; }" % (acc, acc))
        prim = ("QPushButton[primary=\"true\"] { background:#4fb0e8; color:#0b141d; border:none; font-weight:600; }"
                "QPushButton[primary=\"true\"]:hover { background:rgba(79,176,232,0.86); }")
        rad = "10px"
    views = ("QAbstractItemView { background:rgba(255,255,255,0.04); color:#e4edf3; border:1px solid rgba(255,255,255,0.08);"
             " border-radius:%s; outline:none; }"
             "QAbstractItemView::item { padding:3px 4px; }"
             "QAbstractItemView::item:selected { background:rgba(79,176,232,0.28); color:#ffffff; }"
             "QHeaderView::section { background:transparent; color:#8ea3b4; border:none; padding:4px 6px; }"
             "QComboBox { background:#1c2b3a; color:#e4edf3; border:1px solid #2b3f54; border-radius:%s; padding:4px 10px; }"
             "QComboBox QAbstractItemView { background:#132029; selection-background-color:rgba(79,176,232,0.3); }"
             "QSpinBox { background:#1c2b3a; color:#e4edf3; border:1px solid #2b3f54; border-radius:%s; padding:3px 6px; }"
             % (rad, rad, rad))
    return (base + "QLabel { color:#e4edf3; background:transparent; } QLabel#dlgsub { color:#8ea3b4; }"
            + edit + prim + views)


def paint_dialog_panel(p, rect, blur, base="#101b26"):
    """The body of a Fjord dialog: terminal pane, macOS frosted glass, or the flat panel of the Windows / Default look."""
    if term_on():
        paint_term_panel(p, rect)
        return
    mode = UI["mode"]
    if mode == "mac":
        try:
            paint_glass_panel(p, rect, 20, blur, base)
            return
        except Exception:
            log_error("dialog glass paint")
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    win = mode == "windows"
    rad = rr(8 if win else 16)
    path = QPainterPath()
    path.addRoundedRect(QRectF(rect).adjusted(0.5, 0.5, -0.5, -0.5), rad, rad)
    p.setPen(QPen(QColor(255, 255, 255, 28) if win else QColor(themed("#2b3f54")), 1))
    p.setBrush(QColor(themed(base)))
    p.drawPath(path)


class DlgCloseButton(QAbstractButton):
    """The dialog's own close button, drawn in the current look: red traffic light (macOS), caption X (Windows),
    [x] (Terminal) or a round X (Default)."""
    def __init__(self, bar):
        super().__init__(bar)
        self.bar = bar
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip("Close")
        self.apply_look()

    def apply_look(self):
        k = style_key()
        self.setFixedSize(*{"mac": (22, 22), "windows": (46, 32), "term": (34, 22)}.get(k, (28, 28)))

    def enterEvent(self, e):
        super().enterEvent(e)
        self.update()

    def leaveEvent(self, e):
        super().leaveEvent(e)
        self.update()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        k = style_key()
        r = QRectF(self.rect())
        c = r.center()
        hov, down = self.underMouse(), self.isDown()
        x, y = c.x(), c.y()
        if k == "mac":
            lit = self.window().isActiveWindow() or hov
            base = QColor(255, 95, 87) if lit else QColor(96, 104, 112)
            if down:
                base = base.darker(135)
            p.setPen(QPen(QColor(0, 0, 0, 55), 0.8))
            p.setBrush(base)
            p.drawEllipse(QRectF(x - 6.5, y - 6.5, 13, 13))
            if hov:
                p.setPen(QPen(QColor(0, 0, 0, 150), 1.3, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.drawLine(QPointF(x - 2.6, y - 2.6), QPointF(x + 2.6, y + 2.6))
                p.drawLine(QPointF(x - 2.6, y + 2.6), QPointF(x + 2.6, y - 2.6))
        elif k == "term":
            if hov or down:
                p.fillRect(r.adjusted(1, 1, -1, -1), QColor(TERM_BRIGHT))
            p.setPen(QColor(TERM_BG) if (hov or down) else QColor(TERM_BRIGHT))
            f = QFont(self.font())
            f.setBold(True)
            p.setFont(f)
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), "[x]")
        elif k == "windows":
            if hov or down:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(196, 43, 28) if down else QColor(232, 17, 35))
                rad = rr(8)
                # square on every corner but the dialog's top-right one, which follows the panel's rounding
                path = QPainterPath()
                path.moveTo(r.left(), r.top())
                path.lineTo(r.right() - rad, r.top())
                path.quadTo(r.right(), r.top(), r.right(), r.top() + rad)
                path.lineTo(r.right(), r.bottom())
                path.lineTo(r.left(), r.bottom())
                path.closeSubpath()
                p.drawPath(path)
            p.setPen(QPen(QColor("#ffffff") if hov else QColor(themed("#b5c6d4")), 1.3, Qt.PenStyle.SolidLine,
                          Qt.PenCapStyle.RoundCap))
            s = 4.8
            p.drawLine(QPointF(x - s, y - s), QPointF(x + s, y + s))
            p.drawLine(QPointF(x - s, y + s), QPointF(x + s, y - s))
        else:
            if hov or down:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(255, 255, 255, 38 if down else 22))
                p.drawEllipse(r.adjusted(2, 2, -2, -2))
            p.setPen(QPen(QColor("#ffffff") if hov else QColor(themed("#8ea3b4")), 1.4, Qt.PenStyle.SolidLine,
                          Qt.PenCapStyle.RoundCap))
            s = 4.4
            p.drawLine(QPointF(x - s, y - s), QPointF(x + s, y + s))
            p.drawLine(QPointF(x - s, y + s), QPointF(x + s, y - s))
        p.end()


class DlgTitleBar(QWidget):
    """The strip along the top of a Fjord dialog: its title, the close button, and drag-to-move."""
    def __init__(self, dlg):
        super().__init__(dlg)
        self.dlg = dlg
        self.close_btn = DlgCloseButton(self)
        self.close_btn.clicked.connect(dlg.reject)
        self._drag = None
        self.apply_look()

    def apply_look(self):
        self.setFixedHeight({"mac": 40, "windows": 32, "term": 30}.get(style_key(), 42))
        self.close_btn.apply_look()
        self._place()

    def _place(self):
        k, b = style_key(), self.close_btn
        if k == "mac":
            b.move(12, (self.height() - b.height()) // 2)
        elif k == "windows":
            b.move(self.width() - b.width(), 0)
        elif k == "term":
            b.move(self.width() - b.width() - 6, (self.height() - b.height()) // 2)
        else:
            b.move(self.width() - b.width() - 10, (self.height() - b.height()) // 2)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._place()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.TextAntialiasing)
        k = style_key()
        title = self.dlg.windowTitle()
        f = QFont(self.font())
        f.setBold(True)
        f.setPixelSize(12 if k in ("windows", "term") else 13)
        p.setFont(f)
        r = QRectF(self.rect())
        if k == "mac":
            p.setPen(QColor(228, 237, 243, 190))
            p.drawText(r.adjusted(40, 0, -40, 0), int(Qt.AlignmentFlag.AlignCenter), title)
        elif k == "term":
            p.setPen(QColor(TERM_BRIGHT))
            slug = "~/" + (title.strip().lower().replace(" ", "-") or "dialog")
            p.drawText(r.adjusted(12, 0, -44, 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), slug)
            p.setPen(QPen(QColor(18, 184, 74, 120), 1))
            p.drawLine(QPointF(r.left() + 1, r.bottom() - 0.5), QPointF(r.right() - 1, r.bottom() - 0.5))
        elif k == "windows":
            p.setPen(QColor(themed("#e4edf3")))
            p.drawText(r.adjusted(14, 0, -50, 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), title)
        else:
            p.setPen(QColor(themed("#e4edf3")))
            p.drawText(r.adjusted(20, 0, -46, 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), title)
        p.end()

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            h = self.dlg.windowHandle()
            try:
                if h is not None and h.startSystemMove():
                    e.accept()
                    return
            except Exception:
                pass
            self._drag = e.globalPosition().toPoint() - self.dlg.frameGeometry().topLeft()
            e.accept()
            return
        super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        if self._drag is not None and e.buttons() & Qt.MouseButton.LeftButton:
            self.dlg.move(e.globalPosition().toPoint() - self._drag)
            e.accept()
            return
        super().mouseMoveEvent(e)

    def mouseReleaseEvent(self, e):
        self._drag = None
        super().mouseReleaseEvent(e)


class FjordDialog(QDialog):
    """Base for every Fjord dialog: no system frame. It draws its own panel, title and close button in the current look
    (macOS glass + traffic light, Windows flat panel + caption X, Terminal pane + [x], or the Default rounded panel), can be
    dragged by its title, and closes on Esc or its close button. Put content in `self.body_lay`."""
    def __init__(self, parent=None, title=""):
        super().__init__(parent, Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setObjectName("fjorddlg")
        self.setModal(True)
        self._blur = None
        self._anim = None
        self._shown_once = False
        self._closing = False
        self.setWindowOpacity(0.0)
        outer = QVBoxLayout(self)
        outer.setContentsMargins(1, 1, 1, 1)
        outer.setSpacing(0)
        self.bar = DlgTitleBar(self)
        outer.addWidget(self.bar)
        self.body = QWidget()
        self.body.setObjectName("dlgbody")
        self.body_lay = QVBoxLayout(self.body)
        self.body_lay.setContentsMargins(22, 4, 22, 20)
        self.body_lay.setSpacing(10)
        outer.addWidget(self.body, 1)
        self.setStyleSheet(themed(dialog_qss()))
        if title:
            self.setWindowTitle(title)

    def setWindowTitle(self, t):
        super().setWindowTitle(t)
        self.bar.update()

    def paintEvent(self, e):
        p = QPainter(self)
        try:
            paint_dialog_panel(p, self.rect(), self._blur)
        finally:
            p.end()

    def showEvent(self, e):
        super().showEvent(e)
        if UI["mode"] == "mac" and not term_on() and self._blur is None:
            self._blur = glass_backdrop(self, self.parentWidget())
            self.update()
        self._anim_in()

    def _anim_in(self):
        """Fade (and, outside the glass look, a short rise) when a dialog opens."""
        if self._shown_once:
            return
        self._shown_once = True
        from PyQt6.QtCore import QParallelAnimationGroup
        grp = QParallelAnimationGroup(self)
        fade = QPropertyAnimation(self, b"windowOpacity", self)
        fade.setDuration(190)
        fade.setStartValue(0.0)
        fade.setEndValue(1.0)
        fade.setEasingCurve(QEasingCurve.Type.OutCubic)
        grp.addAnimation(fade)
        if UI["mode"] != "mac":
            end = self.pos()
            rise = QPropertyAnimation(self, b"pos", self)
            rise.setDuration(240)
            rise.setStartValue(QPoint(end.x(), end.y() + 14))
            rise.setEndValue(end)
            rise.setEasingCurve(QEasingCurve.Type.OutCubic)
            grp.addAnimation(rise)
            self.move(end.x(), end.y() + 14)
        self._anim = grp
        grp.start()

    def done(self, r):
        """Fade out before closing; the dialog's exec() returns once the fade has finished."""
        if self._closing:
            return
        if not self.isVisible() or not self._shown_once:
            QDialog.done(self, r)
            return
        self._closing = True
        if self._anim is not None:
            self._anim.stop()
        from PyQt6.QtCore import QParallelAnimationGroup
        grp = QParallelAnimationGroup(self)
        fade = QPropertyAnimation(self, b"windowOpacity", self)
        fade.setDuration(150)
        fade.setStartValue(self.windowOpacity())
        fade.setEndValue(0.0)
        fade.setEasingCurve(QEasingCurve.Type.InCubic)
        grp.addAnimation(fade)
        self._rest_pos = self.pos()
        if UI["mode"] != "mac":
            slide = QPropertyAnimation(self, b"pos", self)
            slide.setDuration(170)
            slide.setStartValue(self._rest_pos)
            slide.setEndValue(self._rest_pos + QPoint(0, 12))
            slide.setEasingCurve(QEasingCurve.Type.InCubic)
            grp.addAnimation(slide)
        grp.finished.connect(lambda: self._finish_close(r))
        self._anim = grp
        grp.start()

    def _finish_close(self, r):
        rest = getattr(self, "_rest_pos", None)
        if rest is not None:
            self.move(rest)
        QDialog.done(self, r)
        self._closing = False
        self._shown_once = False
        self.setWindowOpacity(0.0)

    BLUR_BEHIND = False   # set True on a dialog subclass to blur the browser window behind it while it is open

    def exec(self):
        scrim = None
        if self.BLUR_BEHIND:
            try:
                base = glass_base_window(self)
                if base is not None:
                    scrim = BlurScrim(base)
            except Exception:
                log_error("dialog blur")
                scrim = None
        try:
            return super().exec()
        finally:
            if scrim is not None:
                scrim.dismiss()

    def shake(self):
        """A quick side-to-side wiggle, for a wrong password and the like."""
        if self._closing:
            return
        if self._anim is not None:
            self._anim.stop()
        x0 = self.pos()
        a = QPropertyAnimation(self, b"pos", self)
        a.setDuration(340)
        for t, dx in ((0.0, 0), (0.15, -10), (0.35, 10), (0.55, -7), (0.75, 4), (1.0, 0)):
            a.setKeyValueAt(t, QPoint(x0.x() + dx, x0.y()))
        self._anim = a
        a.start()

    def changeEvent(self, e):
        if e.type() == QEvent.Type.ActivationChange:
            self.bar.close_btn.update()
        super().changeEvent(e)

    def button_row(self, *buttons):
        """A right-aligned row of buttons (first = leftmost). Returns the layout."""
        row = QHBoxLayout()
        row.setSpacing(8)
        row.addStretch()
        for b in buttons:
            row.addWidget(b)
        return row

    @staticmethod
    def make_button(text, primary=False, slot=None):
        b = QPushButton(text)
        b.setAutoDefault(False)
        b.setCursor(Qt.CursorShape.PointingHandCursor)
        if primary:
            b.setProperty("primary", True)
        if slot is not None:
            b.clicked.connect(slot)
        return b


_SB = _QMessageBox.StandardButton
_SB_TEXT = {_SB.Yes: "Yes", _SB.No: "No", _SB.Ok: "OK", _SB.Open: "Open", _SB.Save: "Save", _SB.Discard: "Discard",
            _SB.Apply: "Apply", _SB.Close: "Close", _SB.Cancel: "Cancel"}
_SB_ORDER = (_SB.Cancel, _SB.No, _SB.Discard, _SB.Close, _SB.Apply, _SB.Ok, _SB.Open, _SB.Save, _SB.Yes)
_SB_YES = (_SB.Yes, _SB.Ok, _SB.Open, _SB.Save, _SB.Apply)


class DlgIcon(QWidget):
    """The little question / warning / info / error badge on a message box, in the current look."""
    def __init__(self, kind):
        super().__init__()
        self.kind = kind
        self.setFixedSize(38, 38)

    def paintEvent(self, e):
        I = _QMessageBox.Icon
        glyph, col = {I.Question: ("?", ACCENT["main"]), I.Warning: ("!", "#f5b84a"), I.Information: ("i", ACCENT["main"]),
                      I.Critical: ("\u00d7", "#ff6b6b")}.get(self.kind, ("", ACCENT["main"]))
        if not glyph:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(3, 3, -3, -3)
        f = QFont(self.font())
        f.setBold(True)
        if term_on():
            col = {"?": TERM_BRIGHT, "!": TERM_WARN, "i": TERM_BRIGHT, "\u00d7": "#ff6b6b"}[glyph]
            f.setPixelSize(20)
            p.setFont(f)
            p.setPen(QColor(col))
            p.drawText(self.rect(), int(Qt.AlignmentFlag.AlignCenter), "[%s]" % glyph)
        else:
            c = QColor(col)
            p.setPen(QPen(c, 1.6))
            fill = QColor(c)
            fill.setAlpha(46)
            p.setBrush(fill)
            p.drawEllipse(r)
            f.setPixelSize(20)
            p.setFont(f)
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), glyph)
        p.end()


class FjordMessageBox(FjordDialog):
    """Drop-in for QMessageBox: same static helpers (question / warning / information / critical) and the same
    setText / setInformativeText / setStandardButtons / exec() calls, but borderless and themed."""
    StandardButton = _QMessageBox.StandardButton
    Icon = _QMessageBox.Icon

    def __init__(self, parent=None, title="", text="", icon=None, buttons=None, default=None):
        super().__init__(parent, title)
        self._icon = icon if icon is not None else _QMessageBox.Icon.NoIcon
        self._text, self._info = text, ""
        self._buttons = buttons if buttons is not None else _SB.Ok
        self._default = default if default is not None else _SB.NoButton
        self._flags = None
        self._clicked = None
        self._btns = {}

    def setIcon(self, icon):
        self._icon = icon

    def setText(self, text):
        self._text = text

    def setInformativeText(self, text):
        self._info = text

    def setStandardButtons(self, buttons):
        self._buttons = buttons

    def setDefaultButton(self, button):
        self._default = button

    def setTextInteractionFlags(self, flags):
        self._flags = flags

    def _present(self):
        return [sb for sb in _SB_ORDER if self._buttons & sb]

    def _escape(self):
        have = self._present()
        for sb in (_SB.Cancel, _SB.No):
            if sb in have:
                return sb
        return have[0] if len(have) == 1 else _SB.NoButton

    def _build(self):
        row = QHBoxLayout()
        row.setSpacing(14)
        if self._icon != _QMessageBox.Icon.NoIcon:
            ic = DlgIcon(self._icon)
            row.addWidget(ic, 0, Qt.AlignmentFlag.AlignTop)
        col = QVBoxLayout()
        col.setSpacing(6)
        for txt, sub in ((self._text, False), (self._info, True)):
            if not txt:
                continue
            lab = QLabel(txt)
            lab.setWordWrap(True)
            lab.setTextFormat(Qt.TextFormat.PlainText)
            if sub:
                lab.setObjectName("dlgsub")
            if self._flags is not None:
                lab.setTextInteractionFlags(self._flags)
            col.addWidget(lab)
        row.addLayout(col, 1)
        self.body_lay.addLayout(row)
        have = self._present()
        default = self._default if self._default in have else next((s for s in _SB_YES if s in have), None)
        if default is None and have:
            default = have[-1]
        order = list(reversed(have)) if style_key() == "windows" else have
        btns = []
        for sb in order:
            b = self.make_button(_SB_TEXT[sb], primary=(sb == default), slot=lambda _c=False, s=sb: self._pick(s))
            if sb == default:
                b.setAutoDefault(True)
                b.setDefault(True)
            self._btns[sb] = b
            btns.append(b)
        self.body_lay.addSpacing(6)
        self.body_lay.addLayout(self.button_row(*btns))
        n = len((self._text or "") + (self._info or ""))
        self.setFixedWidth(500 if n > 180 else 420)
        if default in self._btns:
            self._btns[default].setFocus()

    def _pick(self, sb):
        self._clicked = sb
        self.accept()

    def reject(self):
        if self._clicked is None:
            self._clicked = self._escape()
        super().reject()

    def exec(self):
        self._build()
        super().exec()
        return self._clicked if self._clicked is not None else self._escape()

    @staticmethod
    def _run(parent, title, text, icon, buttons, default):
        box = FjordMessageBox(parent, title, text, icon, buttons, default)
        return box.exec()

    @staticmethod
    def question(parent, title, text, buttons=_SB.Yes | _SB.No, defaultButton=_SB.NoButton):
        return FjordMessageBox._run(parent, title, text, _QMessageBox.Icon.Question, buttons, defaultButton)

    @staticmethod
    def warning(parent, title, text, buttons=_SB.Ok, defaultButton=_SB.NoButton):
        return FjordMessageBox._run(parent, title, text, _QMessageBox.Icon.Warning, buttons, defaultButton)

    @staticmethod
    def information(parent, title, text, buttons=_SB.Ok, defaultButton=_SB.NoButton):
        return FjordMessageBox._run(parent, title, text, _QMessageBox.Icon.Information, buttons, defaultButton)

    @staticmethod
    def critical(parent, title, text, buttons=_SB.Ok, defaultButton=_SB.NoButton):
        return FjordMessageBox._run(parent, title, text, _QMessageBox.Icon.Critical, buttons, defaultButton)


def style_password_edit(edit):
    """Round, evenly spaced mask dots in a password box. The app font (Palatino plus extra letter spacing) has no proper round
    bullet, so Qt drew squashed ovals. This gives the box the system UI font, no letter spacing and a clean round dot."""
    f = QFontDatabase.systemFont(QFontDatabase.SystemFont.GeneralFont)
    base = QApplication.font().pointSizeF()
    if base > 0:
        f.setPointSizeF(base)
    f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 0)
    edit.setFont(f)
    edit.setStyleSheet("lineedit-password-character: 9679;")


class FjordInputDialog(FjordDialog):
    """A one-line text prompt (name a group, choose a master password...) in the current look."""
    def __init__(self, parent, title, label, echo, text):
        super().__init__(parent, title)
        self.setFixedWidth(400)
        lab = QLabel(label)
        lab.setWordWrap(True)
        lab.setTextFormat(Qt.TextFormat.PlainText)
        self.body_lay.addWidget(lab)
        self.edit = QLineEdit(text)
        self.edit.setEchoMode(echo)
        if echo == QLineEdit.EchoMode.Password:
            style_password_edit(self.edit)
        self.edit.returnPressed.connect(self.accept)
        self.body_lay.addWidget(self.edit)
        self.body_lay.addSpacing(6)
        self.body_lay.addLayout(self.button_row(*(
            [self.make_button("OK", True, self.accept), self.make_button("Cancel", False, self.reject)]
            if style_key() == "windows" else
            [self.make_button("Cancel", False, self.reject), self.make_button("OK", True, self.accept)])))
        self.edit.setFocus()
        self.edit.selectAll()

    @staticmethod
    def getText(parent, title, label, echo=QLineEdit.EchoMode.Normal, text="", *_a, **_k):
        d = FjordInputDialog(parent, title, label, echo, text)
        ok = d.exec() == QDialog.DialogCode.Accepted
        return (d.edit.text() if ok else ""), ok


def _embed_dialog(parent, inner, title, size):
    """Wrap a Qt dialog (file picker, colour picker) in a FjordDialog so it gets the same borderless themed frame."""
    host = FjordDialog(parent, title)
    host.body_lay.setContentsMargins(12, 2, 12, 12)
    inner.setWindowFlags(Qt.WindowType.Widget)
    inner.setSizeGripEnabled(False)
    host.body_lay.addWidget(inner)
    inner.accepted.connect(host.accept)
    inner.rejected.connect(host.reject)
    host.resize(*size)
    return host


