class PrivacyDashboard(GlassPopup):
    """Popup under the toolbar's shield button: VPN status, ads and trackers blocked on this page, and a per-site ad-block switch."""

    GUARD = "_privdash_closed"

    def __init__(self, win):
        super().__init__(win)
        self.setObjectName("privdash")
        self.setFixedWidth(330)
        self.setStyleSheet(themed(self._qss()))
        self._counts = {}
        lay = QVBoxLayout(self)
        lay.setContentsMargins(16, 14, 16, 14)
        lay.setSpacing(10)

        head = QHBoxLayout()
        head.setSpacing(10)
        self.icon = QLabel()
        self.icon.setFixedSize(30, 30)
        head.addWidget(self.icon)
        col = QVBoxLayout()
        col.setSpacing(0)
        t = QLabel("~/privacy" if term_on() else "Privacy")
        t.setObjectName("hd")
        self.site = QLabel("")
        self.site.setObjectName("sub")
        col.addWidget(t)
        col.addWidget(self.site)
        head.addLayout(col, 1)
        lay.addLayout(head)

        stats = QHBoxLayout()
        stats.setSpacing(10)
        self.ads_n, self.trk_n = QLabel("0"), QLabel("0")
        for num, cap in ((self.ads_n, "Ads blocked"), (self.trk_n, "Trackers blocked")):
            card = QFrame()
            card.setObjectName("card")
            cl = QVBoxLayout(card)
            cl.setContentsMargins(12, 9, 12, 9)
            cl.setSpacing(0)
            num.setObjectName("big")
            c = QLabel(cap)
            c.setObjectName("sub")
            cl.addWidget(num)
            cl.addWidget(c)
            stats.addWidget(card, 1)
        lay.addLayout(stats)
        self.total = QLabel("")
        self.total.setObjectName("sub")
        lay.addWidget(self.total)

        sep = QFrame()
        sep.setObjectName("sep")
        lay.addWidget(sep)

        vrow = QHBoxLayout()
        vcol = QVBoxLayout()
        vcol.setSpacing(0)
        vt = QLabel("VPN / Proxy")
        self.vpn_state = QLabel("")
        self.vpn_state.setObjectName("sub")
        vcol.addWidget(vt)
        vcol.addWidget(self.vpn_state)
        vrow.addLayout(vcol, 1)
        self.vpn_btn = QPushButton("")
        self.vpn_btn.setObjectName("pbtn")
        self.vpn_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.vpn_btn.clicked.connect(self._vpn)
        vrow.addWidget(self.vpn_btn)
        lay.addLayout(vrow)

        sep2 = QFrame()
        sep2.setObjectName("sep")
        lay.addWidget(sep2)

        arow = QHBoxLayout()
        acol = QVBoxLayout()
        acol.setSpacing(0)
        self.ab_title = QLabel("Ad blocking on this site")
        self.ab_sub = QLabel("")
        self.ab_sub.setObjectName("sub")
        self.ab_sub.setWordWrap(True)
        acol.addWidget(self.ab_title)
        acol.addWidget(self.ab_sub)
        arow.addLayout(acol, 1)
        self.sw = SwitchToggle()
        self.sw.animated = True
        self.sw.clicked.connect(self._site_toggled)
        arow.addWidget(self.sw)
        lay.addLayout(arow)

        sep3 = QFrame()
        sep3.setObjectName("sep")
        lay.addWidget(sep3)

        nrow = QHBoxLayout()
        ncol = QVBoxLayout()
        ncol.setSpacing(0)
        self.hn_title = QLabel("History randomiser")
        self.hn_sub = QLabel("")
        self.hn_sub.setObjectName("sub")
        self.hn_sub.setWordWrap(True)
        ncol.addWidget(self.hn_title)
        ncol.addWidget(self.hn_sub)
        nrow.addLayout(ncol, 1)
        self.hn_sw = SwitchToggle()
        self.hn_sw.animated = True
        self.hn_sw.clicked.connect(self._noise_toggled)
        nrow.addWidget(self.hn_sw)
        lay.addLayout(nrow)

        self._timer = QTimer(self)
        self._timer.timeout.connect(self.refresh)
        self._timer.start(1000)
        self.refresh()

    def _after_intro(self):
        self._replay_counts()

    def _count_to(self, label, n):
        """Show a number on a label, counting up to it (from 0 the first time, from the old value afterwards)."""
        old = self._counts.get(label)
        if old is not None and old[1] == n:
            return
        shown = old[0] if old else 0
        self._counts[label] = (shown, n)
        if not self._intro_done or shown == n:
            self._counts[label] = (n, n)
            label.setText(str(n))
            return
        a = getattr(label, "_count_anim", None)
        if a is not None:
            a.stop()
        a = QVariantAnimation(label)
        a.setStartValue(int(shown))
        a.setEndValue(int(n))
        a.setDuration(min(900, 350 + 12 * abs(n - shown)))
        a.setEasingCurve(QEasingCurve.Type.OutCubic)

        def step(v, lb=label, target=n):
            lb.setText(str(int(v)))
            self._counts[lb] = (int(v), target)
        a.valueChanged.connect(step)
        label._count_anim = a
        a.start()

    def _replay_counts(self):
        """Once the popup is on screen, restart the count-up from zero for whatever the numbers are now."""
        for lb, (_cur, target) in list(self._counts.items()):
            self._counts[lb] = (0, -1)
            self._count_to(lb, target)

    @staticmethod
    def _qss():
        """Same palette as the rest of Fjord (so it follows the accent colour) plus macOS / Windows touches."""
        if term_on():
            return ("QFrame#privdash{background:transparent;border:none;}"
                    "QLabel{color:#8dffb0;background:transparent;}"
                    "QLabel#sub{color:#12b84a;font-size:11px;}"
                    "QLabel#big{color:#2bff6a;font-size:26px;font-weight:700;}"
                    "QLabel#hd{color:#2bff6a;font-size:15px;font-weight:700;}"
                    "QFrame#card{background:rgba(43,255,106,0.05);border:1px solid rgba(43,255,106,0.30);border-radius:2px;}"
                    "QFrame#sep{background:rgba(43,255,106,0.30);max-height:1px;min-height:1px;border:none;}"
                    "QPushButton#pbtn{background:transparent;color:#2bff6a;border:1px solid #12b84a;border-radius:2px;padding:5px 12px;}"
                    "QPushButton#pbtn:hover{background:#2bff6a;color:#030704;}")
        mode = UI["mode"]
        panel_r, card_r, btn_r = {"mac": (20, 14, 14), "windows": (8, 6, 5)}.get(mode, (14, 10, 8))
        card_bg = "rgba(255,255,255,0.06)" if mode == "mac" else "#1c2b3a"
        card_bd = "rgba(255,255,255,0.09)" if mode == "mac" else ("rgba(255,255,255,0.05)" if mode == "windows" else "#2b3f54")
        sep = "rgba(255,255,255,0.10)" if mode == "mac" else "#2b3f54"
        if mode == "windows":
            btn = ("QPushButton#pbtn{background:#4fb0e8;color:#0b141d;border:none;border-radius:%dpx;padding:6px 14px;}"
                   "QPushButton#pbtn:hover{background:rgba(79,176,232,0.86);}" % btn_r)
        elif mode == "mac":
            btn = ("QPushButton#pbtn{background:rgba(255,255,255,0.07);color:#e4edf3;border:1px solid rgba(255,255,255,0.10);"
                   "border-radius:%dpx;padding:6px 14px;}QPushButton#pbtn:hover{background:rgba(255,255,255,0.12);}" % btn_r)
        else:
            btn = ("QPushButton#pbtn{background:#243546;color:#e4edf3;border:1px solid #2b3f54;border-radius:%dpx;padding:5px 12px;}"
                   "QPushButton#pbtn:hover{background:#2c4156;}" % btn_r)
        panel = "background:transparent;border:none;"
        return (
            "QFrame#privdash{%s}"
            "QLabel{color:#e4edf3;background:transparent;}"
            "QLabel#sub{color:#8ea3b4;font-size:11px;}"
            "QLabel#big{color:#4fb0e8;font-size:26px;font-weight:700;}"
            "QLabel#hd{font-size:15px;font-weight:700;}"
            "QFrame#card{background:%s;border:1px solid %s;border-radius:%dpx;}"
            "QFrame#sep{background:%s;max-height:1px;min-height:1px;border:none;}"
            % (panel, card_bg, card_bd, card_r, sep)) + btn

    def _tab_site(self):
        t = self.win.cur()
        if t is None or self.win.is_internal(t.url()):
            return ""
        return self.win.host_of(t.url())

    def refresh(self):
        w, ab = self.win, self.win.adblock
        site = self._tab_site()
        pm = QPixmap(60, 60)
        pm.fill(Qt.GlobalColor.transparent)
        pp = QPainter(pm)
        pp.setRenderHint(QPainter.RenderHint.Antialiasing)
        paused = bool(site) and ab.is_paused(site)
        good = ab.enabled and not paused
        draw_glyph(pp, "shield_on" if good else "shield", QRectF(8, 8, 44, 44), QColor(ACCENT["main"]) if good else QColor(themed("#8ea3b4")), 3.4)
        pp.end()
        pm.setDevicePixelRatio(2.0)
        self.icon.setPixmap(pm)

        ads, trk = ab.site_counts(site) if site else (0, 0)
        self.site.setText(site or "This page isn't a website")
        self._count_to(self.ads_n, ads)
        self._count_to(self.trk_n, trk)
        self.total.setText("%s blocked in total this session" % format(ab.blocked, ","))

        st = w.settings
        if st.get("vpn"):
            self.vpn_state.setText("On · %s %s:%s" % (str(st.get("proxy_type", "socks5")).upper(), st.get("proxy_host", ""), st.get("proxy_port", "")))
            self.vpn_btn.setText("Turn off")
        elif st.get("proxy_host") and st.get("proxy_port"):
            self.vpn_state.setText("Off · your traffic is not routed through the proxy")
            self.vpn_btn.setText("Turn on")
        else:
            self.vpn_state.setText("Not set up yet")
            self.vpn_btn.setText("Set up")

        if not site:
            self.sw.setChecked(False)
            self.sw.setEnabled(False)
            self.ab_sub.setText("Open a website to manage its ad blocking")
        elif not ab.enabled:
            self.sw.setChecked(False)
            self.sw.setEnabled(False)
            self.ab_sub.setText("Ad blocking is off everywhere (Menu > Privacy & performance)")
        else:
            self.sw.setEnabled(True)
            self.sw.setChecked(not paused)
            self.ab_sub.setText("Blocking ads and trackers" if not paused else "Paused: ads are allowed here")

        if PRIVATE:
            self.hn_sw.setChecked(False)
            self.hn_sw.setEnabled(False)
            self.hn_sub.setText("Not available in a private window")
        else:
            noise_on = bool(st.get("history_noise"))
            self.hn_sw.setChecked(noise_on)
            self.hn_sub.setText("Adding everyday searches and sites to your history" if noise_on
                                else "Adds ordinary searches and sites to your history")

    def _site_toggled(self):
        site = self._tab_site()
        if site:
            self.win.pause_site(site, not self.sw.isChecked())
        QTimer.singleShot(250, self.refresh)

    def _noise_toggled(self):
        self.win.set_history_noise(self.hn_sw.isChecked())
        QTimer.singleShot(250, self.refresh)

    def _vpn(self):
        win = self.win
        self.close()
        QTimer.singleShot(0, win.toggle_vpn)

    def _before_close(self):
        self._timer.stop()


class SiteSettings(GlassPopup):
    """Popup under the toolbar's site-settings button: everything Fjord remembers for the website you are on."""

    GUARD = "_sitepop_closed"

    def __init__(self, win):
        super().__init__(win)
        self.setObjectName("privdash")
        self.setFixedWidth(340)
        self.setStyleSheet(themed(PrivacyDashboard._qss()))
        self.host = ""
        self.rows = {}
        lay = QVBoxLayout(self)
        lay.setContentsMargins(16, 14, 16, 14)
        lay.setSpacing(10)
        t = QLabel("~/site" if term_on() else "Site settings")
        t.setObjectName("hd")
        self.site = QLabel("")
        self.site.setObjectName("sub")
        lay.addWidget(t)
        lay.addWidget(self.site)

        def separator():
            sep = QFrame()
            sep.setObjectName("sep")
            lay.addWidget(sep)

        def text_col(title):
            col = QVBoxLayout()
            col.setSpacing(0)
            lab = QLabel(title)
            sub = QLabel("")
            sub.setObjectName("sub")
            sub.setWordWrap(True)
            col.addWidget(lab)
            col.addWidget(sub)
            return col, sub

        def switch_row(key, title):
            separator()
            row = QHBoxLayout()
            col, sub = text_col(title)
            row.addLayout(col, 1)
            sw = SwitchToggle()
            sw.animated = True
            sw.clicked.connect(lambda _c=False, k=key: self._flip(k))
            row.addWidget(sw)
            lay.addLayout(row)
            self.rows[key] = (sw, sub)

        def button(text, slot, width=None):
            b = QPushButton(text)
            b.setObjectName("pbtn")
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _c=False: slot())
            if width:
                b.setFixedWidth(width)
            return b

        switch_row("js", "JavaScript")
        switch_row("images", "Images")
        switch_row("ads", "Ad blocking")

        separator()
        zrow = QHBoxLayout()
        zcol, self.zoom_sub = text_col("Zoom")
        zrow.addLayout(zcol, 1)
        zrow.addWidget(button("\u2212", lambda: self._zoom(-0.1), 34))
        self.zoom_btn = button("100%", lambda: self._zoom(0), 62)
        zrow.addWidget(self.zoom_btn)
        zrow.addWidget(button("+", lambda: self._zoom(0.1), 34))
        lay.addLayout(zrow)

        separator()
        prow = QHBoxLayout()
        pcol, self.perm_sub = text_col("Camera & microphone")
        prow.addLayout(pcol, 1)
        self.perm_btn = button("Reset", self._perm_reset)
        prow.addWidget(self.perm_btn)
        lay.addLayout(prow)

        lay.addSpacing(2)
        self.reset_btn = button("Reset this site", self._reset)
        lay.addWidget(self.reset_btn)
        self.refresh()

    def _tab_url(self):
        t = self.win.cur()
        return t.url() if t is not None else QUrl()

    def refresh(self):
        w = self.win
        host = self.host = w.site_host(self._tab_url())
        cfg = w.site_cfg(host)
        self.site.setText(host or "This page isn't a website")

        def put(key, on, sub, enabled=True):
            sw, lab = self.rows[key]
            sw.setChecked(bool(on))
            sw.setEnabled(bool(enabled))
            lab.setText(sub)

        has = bool(host)
        none = "Open a website to change this"
        js = cfg.get("js", True)
        put("js", js, ("Scripts run normally" if js else "Scripts are blocked on this site") if has else none, has)
        im = cfg.get("images", True)
        put("images", im, ("Pictures load normally" if im else "Pictures are not loaded on this site") if has else none, has)
        ab = w.adblock
        if not has:
            put("ads", False, none, False)
        elif not ab.enabled:
            put("ads", False, "Ad blocking is off everywhere (Menu > Privacy & performance)", False)
        else:
            paused = ab.is_paused(host)
            put("ads", not paused, "Paused: ads are allowed here" if paused else "Blocking ads and trackers", True)

        t = w.cur()
        z = t.zoomFactor() if (t is not None and has) else 1.0
        self.zoom_btn.setText("%d%%" % round(z * 100))
        self.zoom_btn.setEnabled(has)
        self.zoom_sub.setText(("Remembered for this site" if "zoom" in cfg else "Not changed here") if has else none)
        ents = w.site_perm_entries(host) if has else []
        word = {"allow": "allowed", "deny": "blocked"}
        self.perm_sub.setText(" \u00b7 ".join("%s %s" % (PERM_WHAT.get(p, p).capitalize(), word.get(v, v)) for _k, p, v in ents)
                              if ents else ("Asks each time" if has else none))
        self.perm_btn.setEnabled(bool(ents))
        self.reset_btn.setEnabled(has and (bool(cfg) or bool(ents) or ab.is_paused(host)))

    def _flip(self, key):
        w, host = self.win, self.host
        on = self.rows[key][0].isChecked()
        if False:
            pass
        elif host:
            if key == "ads":
                w.pause_site(host, not on)
            else:
                w.set_site_flag(host, key, on)
        QTimer.singleShot(250, self.refresh)

    def _zoom(self, d):
        if self.host:
            self.win.zoom(d) if d else self.win.zoom_reset()
        self.refresh()

    def _perm_reset(self):
        if self.host:
            self.win.site_perm_reset(self.host)
            self.win.toast("Camera and microphone answers forgotten for %s" % self.host, 3000)
        self.refresh()

    def _reset(self):
        host = self.host
        self.close()
        QTimer.singleShot(0, lambda: self.win.site_reset(host))


