PERM_KINDS = {"MediaAudioCapture": "mic", "MediaVideoCapture": "camera", "MediaAudioVideoCapture": "camera+mic",
              "Geolocation": "geo", "Notifications": "notif", "ClipboardReadWrite": "clip",
              "MouseLock": "lock", "LocalFontsAccess": "fonts"}
PERM_WHAT = {"mic": "microphone", "camera": "camera", "camera+mic": "camera and microphone",
             "geo": "location", "notif": "notifications", "clip": "clipboard", "lock": "pointer lock", "fonts": "local fonts"}
PERM_PARTS = {"mic": ("mic",), "camera": ("camera",), "camera+mic": ("camera", "mic"), "geo": ("geo",),
              "notif": ("notif",), "clip": ("clip",), "lock": ("lock",), "fonts": ("fonts",)}
PERM_ASK = {"mic": "use your microphone", "camera": "use your camera", "camera+mic": "use your camera and microphone",
            "geo": "know your location", "notif": "show notifications", "clip": "read what you copy",
            "lock": "lock your pointer", "fonts": "see the fonts installed on this device"}


class Page(QWebEnginePage):
    def __init__(self, profile, tab):
        super().__init__(profile, tab)
        self.tab = tab
        self.link_hover = ""
        self.linkHovered.connect(self._set_link_hover)
        if QWebEnginePermission is not None and hasattr(self, "permissionRequested"):
            self.permissionRequested.connect(self._on_permission)
        else:
            self.featurePermissionRequested.connect(self._on_feature)
        self.loadStarted.connect(lambda: self.tab.browser.perm_drop(self))
        tab.browser.adblock.install(self)

    def chooseFiles(self, mode, old_files, accepted_mimetypes):
        """Route <input type=file> pickers through Fjord's own themed dialog instead of the native OS one."""
        FM = QWebEnginePage.FileSelectionMode
        parent = self.tab.browser
        start = next((f for f in old_files if f), "")
        if start and not os.path.isdir(start):
            start = os.path.dirname(start)
        if not start or not os.path.isdir(start):
            start = str(Path.home() / "Downloads")
        if mode == FM.FileSelectUploadFolder:
            folder = QFileDialog.getExistingDirectory(parent, "Choose a folder to upload", start)
            if not folder:
                return []
            return [str(p) for p in Path(folder).rglob("*") if p.is_file()]
        flt = ""
        if accepted_mimetypes:
            exts = []
            for m in accepted_mimetypes:
                if m.startswith("."):
                    exts.append("*" + m)
                else:
                    exts += ["*" + e for e in mimetypes.guess_all_extensions(m)]
            if exts:
                flt = "Accepted files (%s);;All Files (*)" % " ".join(sorted(set(exts)))
        if mode == FM.FileSelectOpenMultiple:
            files, _ = QFileDialog.getOpenFileNames(parent, "Choose files", start, flt)
            return list(files)
        path, _ = QFileDialog.getOpenFileName(parent, "Choose a file", start, flt)
        return [path] if path else []

    def _on_permission(self, perm):
        kind = PERM_KINDS.get(getattr(perm.permissionType(), "name", ""))
        if kind is None:
            return
        self.tab.browser.ask_permission(self, kind, perm.origin(), perm.grant, perm.deny)

    def _on_feature(self, origin, feature):
        kind = PERM_KINDS.get(getattr(feature, "name", ""))
        if kind is None:
            return
        pol = QWebEnginePage.PermissionPolicy
        self.tab.browser.ask_permission(
            self, kind, origin,
            lambda: self.setFeaturePermission(origin, feature, pol.PermissionGrantedByUser),
            lambda: self.setFeaturePermission(origin, feature, pol.PermissionDeniedByUser))

    def _set_link_hover(self, url):
        self.link_hover = url

    def acceptNavigationRequest(self, url, nav_type, is_main):
        if is_main and url.scheme() == "fjord" and not self._internal_origin(nav_type):
            return False
        if is_main and url.scheme() == "fjord" and url.host() in ("clear-history", "remove-bookmark", "search", "set", "ess-remove", "ess-add", "vpn", "adblock-update", "allow-remove", "top-add", "top-remove", "bg",
                                                                "ext-open", "ext-add", "ext-url", "ext-toggle", "ext-remove", "ext-popup", "ext-options",
                                                                "import-open", "import-run", "import-file", "import-pwfile",
                                                                "pw-create", "pw-unlock", "pw-lock", "pw-change", "pw-add", "pw-delete", "pw-copy", "pw-reveal", "pw-open", "pw-generate", "pw-never-remove", "pw-never-clear",
                                                                "budget-add", "budget-set", "budget-remove", "usage-open", "usage-clear", "shortcuts", "open-settings", "whatsnew"):
            QTimer.singleShot(0, lambda: self.tab.browser.internal_action(url))
            return False
        if is_main and url.scheme() in ("http", "https"):
            self.tab.browser.adblock.update_site(self, url.host())
        if is_main:
            self.tab.browser.apply_site_settings(self, url)
        return super().acceptNavigationRequest(url, nav_type, is_main)

    def _internal_origin(self, nav_type):
        """True only when a navigation comes from one of Fjord's own pages or from an address typed by the user."""
        if nav_type == QWebEnginePage.NavigationType.NavigationTypeTyped:
            return True
        cur = self.url()
        return cur.scheme() == "fjord"

    def javaScriptConsoleMessage(self, level, message, line, source):
        if message == NOTES_GET:
            self.tab.browser.send_notes(self)
            return
        if message.startswith(NOTES_MSG):
            self.tab.browser.save_notes(self.url().host(), message[len(NOTES_MSG):])
            return
        if message.startswith(PEEK_MSG):
            link, tab = message[len(PEEK_MSG):], self.tab
            QTimer.singleShot(0, lambda: tab.browser.peek_link(link, tab))
            return
        if message.startswith(PW_SAVE_MSG):
            real = self.url()
            if real.scheme() in ("http", "https") and real.host():
                self.tab.browser.offer_save_password(message[len(PW_SAVE_MSG):], real.host())
            return
        if message.startswith(PW_FOCUS_MSG):
            self.tab.browser._af_log("focus: login field message received on %s" % self.url().host())
            real = self.url()
            if real.scheme() in ("http", "https") and real.host():
                self.tab.browser.offer_fill_password(self.tab, real.host())
            return
        if message.startswith(PW_GEN_MSG):
            self.tab.browser._af_log("gen: password-box message received on %s" % self.url().host())
            real = self.url()
            if real.scheme() in ("http", "https") and real.host():
                try:
                    data = json.loads(message[len(PW_GEN_MSG):])
                    user = str(data.get("u", "")) if isinstance(data, dict) else ""
                except ValueError:
                    user = ""
                self.tab.browser.offer_generate_password(self.tab, real.host(), user)
            return
        if message.startswith(PW_TYPE_MSG):
            self.tab.browser.dismiss_fill_prompt(self.tab)
            return
        super().javaScriptConsoleMessage(level, message, line, source)


def menu_glyph_icon(kind, color="#b5c6d4"):
    """Thin monochrome line icon for a menu entry, drawn with the same glyphs as the toolbar."""
    pm = QPixmap(36, 36)
    pm.fill(Qt.GlobalColor.transparent)
    pp = QPainter(pm)
    draw_glyph(pp, kind, QRectF(4, 4, 28, 28), QColor(color), 2.2)
    pp.end()
    pm.setDevicePixelRatio(2.0)
    return QIcon(pm)


class Tab(QWebEngineView):
    def __init__(self, profile, browser):
        super().__init__()
        self.browser = browser
        self.loading = False
        self.closing = False
        self.group = None
        self.prog = 0
        self.row = None
        self.last_active = time.time()
        self.pending = None
        self.ess = None        # host of the Essential this tab is pinned as (None = ordinary tab)
        self.thumb = None
        self.thumb_t = 0.0
        self.volume = 1.0
        self.setPage(Page(profile, self))

    def contextMenuEvent(self, e):
        """Right-click menu: Qt's standard one, but Back / Forward / Reload / Stop get Fjord's own thin line icons
        (the stock Reload icon was a mismatched blue system glyph)."""
        mk = getattr(self, "createStandardContextMenu", None) or getattr(self.page(), "createStandardContextMenu", None)
        m = None
        if mk is not None:
            try:
                m = mk()
            except Exception:
                log_error("standard context menu")
        if m is None:
            super().contextMenuEvent(e)
            return
        wa = QWebEnginePage.WebAction
        for web, kind, name in ((wa.Back, "back", "Back"), (wa.Forward, "forward", "Forward"),
                                (wa.Reload, "reload", "Reload"), (wa.Stop, "stop", "Stop")):
            pa = self.pageAction(web)
            for a in m.actions():
                if a == pa or a.text().replace("&", "") == name:
                    a.setIcon(menu_glyph_icon(kind))
        m.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        m.popup(e.globalPos())

    def reapply_volume(self):
        """A fresh page starts at the site's own volume, so put the slider's level back on it."""
        if self.volume < 0.999:
            try:
                self.page().runJavaScript(volume_js(self.volume))
            except RuntimeError:
                pass

    def createWindow(self, wtype):
        # window.open() with a size (sign in with Google / Apple / Facebook...) is a WebDialog: show it as a borderless
        # Fjord dialog instead of a tab. Plain target=_blank links and window.open() without features stay tabs.
        if wtype == QWebEnginePage.WebWindowType.WebDialog:
            return self.browser.open_web_popup()
        # Shift+click on a link: peek at it in a floating preview window instead of opening a tab
        if self.browser.preview_wanted(wtype):
            return self.browser.open_link_preview(opener=self)
        return self.browser.new_tab(blank=True, opener=self)

    def snap(self, force=True):
        """Remember what the page looks like for the tab hover preview. Only possible while it is on screen.
        Grabbing a web view reads the whole frame back from the GPU, so it is skipped when previews are off, and with
        force=False (the tab-switch path) when a thumbnail from the last couple of seconds already exists."""
        try:
            if self.pending is not None or not self.isVisible() or self.width() < 60 or self.height() < 60:
                return
            if not self.browser.settings.get("tab_preview", True):
                return
            now = time.monotonic()
            if not force and self.thumb is not None and now - self.thumb_t < 2.5:
                return
            pm = self.grab()
            if pm.isNull():
                return
            pm = pm.scaledToWidth(480, Qt.TransformationMode.SmoothTransformation)
            self.thumb = pm.copy(0, 0, pm.width(), min(pm.height(), 420))
            self.thumb_t = now
        except RuntimeError:
            pass


class PopupView(Tab):
    """The web view inside a WebPopupDialog. It is a Tab so every page helper works on it, but it is never put in the tab list."""
    def createWindow(self, wtype):
        if wtype == QWebEnginePage.WebWindowType.WebDialog:
            return self.browser.open_web_popup()
        return self.browser.new_tab(blank=True)


class WebPopupDialog(FjordDialog):
    """A website's pop-up window (the 'Sign in with Google' window and the like) in a borderless Fjord dialog: same frame, title
    bar and close button as the other dialogs. The page keeps its opener, so the sign-in still hands its result back to the
    site, and it closes itself when the site calls window.close()."""
    VIEW = PopupView

    def __init__(self, browser):
        super().__init__(browser, "Sign in")
        self._presented = False
        self.body_lay.setContentsMargins(8, 0, 8, 8)
        self.body_lay.setSpacing(0)
        self.view = self.VIEW(browser.profile, browser)
        self.body_lay.addWidget(self.view)
        self._fit(480, 640)
        pg = self.view.page()
        pg.windowCloseRequested.connect(self.reject)
        pg.geometryChangeRequested.connect(lambda r: (self._fit(r.width(), r.height()), self.present()))
        self.view.titleChanged.connect(lambda _t: self._retitle())
        self.view.urlChanged.connect(lambda _u: self._retitle())
        self.finished.connect(lambda _r: self.deleteLater())
        QTimer.singleShot(80, self.present)      # if the site never asks for a size, show it anyway

    def _retitle(self):
        self.setWindowTitle(self.view.title() or self.view.url().host() or "Sign in")

    def _fit(self, w, h):
        """Size the dialog so the page gets the width x height the site asked for (within the screen), centred on the window."""
        scr = (self.parentWidget().screen() if self.parentWidget() is not None else QApplication.primaryScreen()).availableGeometry()
        w = max(320, min(int(w or 480), scr.width() - 80))
        h = max(360, min(int(h or 640), scr.height() - 120))
        self.resize(w + 16, h + self.bar.height() + 10)
        par = self.parentWidget()
        c = par.frameGeometry().center() if par is not None else scr.center()
        self.move(c.x() - self.width() // 2, c.y() - self.height() // 2)

    def present(self):
        if not self._presented:
            self._presented = True
            self.show()
            self.raise_()
            self.activateWindow()


class PreviewView(PopupView):
    """The web view inside a link preview. Anything in it that asks for a new tab (target=_blank, window.open) gets
    one, and the preview steps aside so it does not float over the page that was just opened."""
    def createWindow(self, wtype):
        if wtype == QWebEnginePage.WebWindowType.WebDialog:
            return self.browser.open_web_popup()
        dlg = getattr(self, "dlg", None)
        tab = self.browser.new_tab(blank=True, opener=getattr(dlg, "src_tab", None))
        if dlg is not None:
            QTimer.singleShot(0, dlg.reject)
        return tab


PEEK_MSG = "__FJORD_PEEK__"
PEEK_SCRIPT = "fjord-shift-peek"
# Shift+click on any link, on any page: swallow the click before the site's own handlers can use it and tell Fjord
# which address to preview. Works for ordinary links, target=_blank links, links a site handles with JavaScript,
# links inside shadow DOM and SVG links.
PEEK_JS = r"""(function(){
if(window.__fjPeek)return;window.__fjPeek=1;
var log=console.log.bind(console);
function lnk(e){
 try{
  var p=e.composedPath?e.composedPath():[e.target];
  for(var i=0;i<p.length;i++){
   var n=p[i];
   if(n&&n.tagName&&/^(A|AREA)$/i.test(n.tagName)){
    var h=n.href;if(h&&typeof h!=='string')h=h.baseVal;
    if(!h)return null;
    h=new URL(h,document.baseURI).href;
    return /^https?:/i.test(h)?h:null;
   }
  }
 }catch(x){}
 return null;
}
function plain(e){return e.shiftKey&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&e.button===0;}
addEventListener('mousedown',function(e){if(plain(e)&&lnk(e))e.preventDefault();},true);
addEventListener('click',function(e){
 if(!plain(e))return;
 var u=lnk(e);if(!u)return;
 e.preventDefault();e.stopImmediatePropagation();
 try{log("__FJORD_PEEK__"+u);}catch(x){}
},true);
})();"""


def blur_pixmap(pm, div=22):
    """A cheap, smooth blur: shrink the picture a long way and stretch it back up in steps."""
    if pm.isNull():
        return pm
    dpr = pm.devicePixelRatio()
    img = pm.toImage()
    w, h = img.width(), img.height()
    ar, sm = Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation
    img = img.scaled(max(1, w // 4), max(1, h // 4), ar, sm)
    img = img.scaled(max(1, w // div), max(1, h // div), ar, sm)
    for k in (8, 4, 1):
        img = img.scaled(max(1, w // k), max(1, h // k), ar, sm)
    out = QPixmap.fromImage(img)
    out.setDevicePixelRatio(dpr)
    return out


class GlanceButton(QAbstractButton):
    """A small round button in the column beside a link preview (close / open as tab)."""
    def __init__(self, kind, tip, parent=None):
        super().__init__(parent)
        self.kind = kind
        self.setToolTip(tip)
        self.setFixedSize(36, 36)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)

    def enterEvent(self, e):
        super().enterEvent(e)
        self.update()

    def leaveEvent(self, e):
        super().leaveEvent(e)
        self.update()

    def paintEvent(self, e):
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(78, 78, 86, 238) if self.isDown() else QColor(60, 60, 68, 238) if self.underMouse()
                       else QColor(38, 38, 44, 226))
            p.drawEllipse(QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5))
            pen = QPen(QColor(244, 246, 250, 235), 1.7)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
            p.setPen(pen)
            c = QRectF(self.rect()).center()
            if self.kind == "close":
                p.drawLine(QPointF(c.x() - 4.5, c.y() - 4.5), QPointF(c.x() + 4.5, c.y() + 4.5))
                p.drawLine(QPointF(c.x() - 4.5, c.y() + 4.5), QPointF(c.x() + 4.5, c.y() - 4.5))
            else:                            # diagonal arrow: open as a full tab
                p.drawLine(QPointF(c.x() - 4.5, c.y() + 4.5), QPointF(c.x() + 4.5, c.y() - 4.5))
                p.drawPolyline(QPolygonF([QPointF(c.x() - 0.5, c.y() - 4.5), QPointF(c.x() + 4.5, c.y() - 4.5),
                                          QPointF(c.x() + 4.5, c.y() + 0.5)]))
        finally:
            p.end()


class GlanceBackdrop(QWidget):
    """The browser window, blurred and dimmed, drawn over the browser behind a link preview. It is its own window (a
    web view can't be painted over by an ordinary child widget), it holds the round buttons beside the card, paints the
    card's soft shadow, and a click anywhere on it dismisses the preview."""
    RAD = 16

    def __init__(self, dlg, browser):
        super().__init__(browser, Qt.WindowType.Tool | Qt.WindowType.FramelessWindowHint)
        self.dlg = dlg
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        self.setWindowOpacity(0.0)
        self._fade = None
        self.card = QRectF()
        try:
            self.bg = blur_pixmap(browser.grab())      # what the browser looks like right now, blurred
        except Exception:
            self.bg = QPixmap()
        self.close_btn = GlanceButton("close", "Close (Esc)", self)
        self.close_btn.clicked.connect(dlg.reject)
        self.open_btn = GlanceButton("open", "Open as tab", self)
        self.open_btn.clicked.connect(dlg.promote)

    def cover(self):
        br = self.parentWidget()
        self.setGeometry(QRect(br.mapToGlobal(QPoint(0, 0)), br.size()))

    def sync(self, g):
        """g is the card's rectangle in screen coordinates."""
        tl = g.topLeft() - self.geometry().topLeft()
        self.card = QRectF(tl.x(), tl.y(), g.width(), g.height())
        x = min(int(self.card.right()) + 12, self.width() - 44)
        self.close_btn.move(x, int(self.card.top()) + 14)
        self.open_btn.move(x, int(self.card.top()) + 58)
        self.update()

    def fade(self, to, ms):
        if self._fade is not None:
            self._fade.stop()
        a = QPropertyAnimation(self, b"windowOpacity", self)
        a.setDuration(ms)
        a.setStartValue(self.windowOpacity())
        a.setEndValue(to)
        a.setEasingCurve(QEasingCurve.Type.OutCubic if to > 0.5 else QEasingCurve.Type.InCubic)
        self._fade = a
        a.start()

    def pop_buttons(self):
        """The round buttons slide out from behind the card, one after the other, with a little spring."""
        from PyQt6.QtCore import QParallelAnimationGroup
        self._pops = []
        for i, b in enumerate((self.close_btn, self.open_btn)):
            end = b.pos()
            start = QPoint(end.x() - 26, end.y())
            eff = QGraphicsOpacityEffect(b)
            eff.setOpacity(0.0)
            b.setGraphicsEffect(eff)
            b.move(start)
            grp = QParallelAnimationGroup(self)
            mv = QPropertyAnimation(b, b"pos", b)
            mv.setDuration(360)
            mv.setStartValue(start)
            mv.setEndValue(end)
            ec = QEasingCurve(QEasingCurve.Type.OutBack)
            ec.setOvershoot(1.4)
            mv.setEasingCurve(ec)
            op = QPropertyAnimation(eff, b"opacity", eff)
            op.setDuration(240)
            op.setStartValue(0.0)
            op.setEndValue(1.0)
            op.setEasingCurve(QEasingCurve.Type.OutCubic)
            grp.addAnimation(mv)
            grp.addAnimation(op)
            grp.finished.connect(lambda b=b: b.setGraphicsEffect(None))   # drop the effect once it has faded in
            self._pops.append(grp)

            def go(g=grp):
                try:
                    g.start()
                except RuntimeError:
                    pass
            QTimer.singleShot(170 + i * 80, go)

    def paintEvent(self, e):
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            if not self.bg.isNull():
                p.drawPixmap(self.rect(), self.bg)
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceAtop)
            p.fillRect(self.rect(), QColor(0, 0, 0, 110) if not self.bg.isNull() else QColor(0, 0, 0, 150))
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
            if not self.card.isEmpty():
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(0, 0, 0, 9))
                for i in range(28, 0, -3):
                    p.drawRoundedRect(self.card.adjusted(-i, -i, i, i).translated(0, 8), self.RAD + i, self.RAD + i)
        finally:
            p.end()

    def mousePressEvent(self, e):
        self.dlg.reject()

    def keyPressEvent(self, e):
        if e.key() == Qt.Key.Key_Escape:
            self.dlg.reject()
        else:
            super().keyPressEvent(e)


class LinkPreviewDialog(WebPopupDialog):
    """Shift+click on a link: the page opens in a floating preview over the current tab instead of in a new tab, in the
    style of Zen's Glance. A borderless card with rounded corners and no title bar, the browser blurred and dimmed behind
    it, and round buttons beside it. Esc, the close button, or a click anywhere outside the card dismisses it; the arrow
    button ('Open as tab') keeps the page."""
    VIEW = PreviewView
    RAD = 16

    def __init__(self, browser, src_tab=None):
        super().__init__(browser)
        self.br = browser
        self.src_tab = src_tab
        self._hooked = False
        self.url_lbl = None
        self.view.dlg = self
        self.setModal(False)                 # the browser behind stays visible; a click on it dismisses the preview
        self.setWindowTitle("Preview")
        self.bar.hide()                      # no title bar, no frame: just the page
        self.layout().setContentsMargins(0, 0, 0, 0)
        self.body.setStyleSheet("#dlgbody{background:transparent;border:none}")
        self.body_lay.setContentsMargins(0, 0, 0, 0)
        self.body_lay.setSpacing(0)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)   # rounded by a window mask instead
        self.backdrop = GlanceBackdrop(self, browser)
        # owned by the backdrop, so the card always stays above the blurred browser
        self.setParent(self.backdrop, Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self._fit(0, 0)
        self.finished.connect(lambda _r: self._unhook())

    def _round_window(self):
        path = QPainterPath()
        path.addRoundedRect(QRectF(self.rect()), self.RAD, self.RAD)
        self.setMask(QRegion(path.toFillPolygon().toPolygon()))

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._round_window()

    def paintEvent(self, e):
        p = QPainter(self)
        p.fillRect(self.rect(), QColor(themed("#101b26")))
        p.end()

    def showEvent(self, e):
        QDialog.showEvent(self, e)           # skip the usual glass backdrop: this card draws its own look
        self._round_window()
        self._anim_in()

    def _anim_in(self):
        """The card fades in while it springs up from below and settles, like Zen's Glance."""
        if self._shown_once:
            return
        self._shown_once = True
        from PyQt6.QtCore import QParallelAnimationGroup
        grp = QParallelAnimationGroup(self)
        fade = QPropertyAnimation(self, b"windowOpacity", self)
        fade.setDuration(220)
        fade.setStartValue(0.0)
        fade.setEndValue(1.0)
        fade.setEasingCurve(QEasingCurve.Type.OutCubic)
        grp.addAnimation(fade)
        end = self.pos()
        start = QPoint(end.x(), end.y() + 56)
        rise = QPropertyAnimation(self, b"pos", self)
        rise.setDuration(420)
        rise.setStartValue(start)
        rise.setEndValue(end)
        ec = QEasingCurve(QEasingCurve.Type.OutBack)
        ec.setOvershoot(0.9)
        rise.setEasingCurve(ec)
        grp.addAnimation(rise)
        self.move(start)
        self._anim = grp
        grp.start()

    def _fit(self, w, h):
        """Always the same generous card size, centred on the browser window; whatever size the site asks for is ignored."""
        if self._presented:
            return
        br = getattr(self, "br", None) or self.parentWidget()
        scr = (br.screen() if br is not None else QApplication.primaryScreen()).availableGeometry()
        if br is not None:
            tl, sz = br.mapToGlobal(QPoint(0, 0)), br.size()
            base = QRect(tl, sz)
        else:
            base = scr
        W = max(480, min(int(base.width() * 0.72), scr.width() - 120))
        H = max(420, min(int(base.height() * 0.86), scr.height() - 60))
        self.resize(W, H)
        c = base.center()
        self.move(c.x() - W // 2, c.y() - H // 2)

    def _retitle(self):
        u = self.view.url()
        self.setWindowTitle(self.view.title() or u.host() or "Preview")

    def promote(self, *_):
        """Keep the page: open it as a normal tab (next to the page it came from) and close the preview."""
        u = self.view.url()
        br, src = self.br, self.src_tab
        self.reject()
        if u.isValid() and not u.isEmpty() and u.scheme() != "about":
            QTimer.singleShot(0, lambda: br.new_tab(u, opener=src))

    def present(self):
        first = not self._presented
        bd = getattr(self, "backdrop", None)
        if first and bd is not None:
            self._fit(0, 0)
            bd.cover()
            bd.sync(self.geometry())
            bd.show()
            bd.fade(1.0, 280)
            bd.pop_buttons()
        super().present()
        if first and not self._hooked:
            self._hooked = True
            QApplication.instance().installEventFilter(self)

    def done(self, r):
        bd = getattr(self, "backdrop", None)
        if not self._closing and self.isVisible() and self._shown_once:
            if self._anim is not None:
                self._anim.stop()
            sink = QPropertyAnimation(self, b"pos", self)
            sink.setDuration(170)
            sink.setStartValue(self.pos())
            sink.setEndValue(QPoint(self.x(), self.y() + 24))
            sink.setEasingCurve(QEasingCurve.Type.InCubic)
            self._sink = sink
            sink.start()
            if bd is not None:
                try:
                    bd.fade(0.0, 170)
                except RuntimeError:
                    pass
        super().done(r)

    def _unhook(self):
        if self._hooked:
            self._hooked = False
            try:
                QApplication.instance().removeEventFilter(self)
            except RuntimeError:
                pass
        bd, self.backdrop = getattr(self, "backdrop", None), None
        if bd is not None:
            try:
                bd.hide()
                bd.deleteLater()
            except RuntimeError:
                pass

    def eventFilter(self, obj, ev):
        try:
            if not self._closing:
                t = ev.type()
                if t == QEvent.Type.MouseButtonPress and isinstance(obj, QWidget) and obj.window() is self.br:
                    self.reject()            # a click on the browser behind: dismiss, and don't let it act on the page
                    return True
                bd = getattr(self, "backdrop", None)
                if (t == QEvent.Type.KeyPress and ev.key() == Qt.Key.Key_Escape
                        and ev.modifiers() == Qt.KeyboardModifier.NoModifier
                        and (self.isActiveWindow() or (bd is not None and bd.isActiveWindow()))):
                    self.reject()
                    return True
        except RuntimeError:
            pass
        return False


class AddressBar(QLineEdit):
    """The address field. macOS style centres the text while idle (like Safari) and rings it with a soft glow on focus;
    Windows style grows an accent underline from the middle on focus (like a Windows 11 text box)."""
    def __init__(self):
        super().__init__()
        self._glow = 0.0
        self._glow_anim = QVariantAnimation(self)
        self._glow_anim.setDuration(340)
        self._glow_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._glow_anim.valueChanged.connect(self._set_glow)

    def _set_glow(self, v):
        self._glow = float(v)
        self.update()

    def _go_glow(self, to):
        self._glow_anim.stop()
        self._glow_anim.setStartValue(self._glow)
        self._glow_anim.setEndValue(to)
        self._glow_anim.start()

    def refresh_style(self, focused=None):
        if focused is None:
            focused = self.hasFocus()
        centred = UI["mode"] == "mac" and not focused and not term_on()
        h = Qt.AlignmentFlag.AlignHCenter if centred else Qt.AlignmentFlag.AlignLeft
        self.setAlignment(h | Qt.AlignmentFlag.AlignVCenter)

    def focusInEvent(self, e):
        super().focusInEvent(e)
        self.refresh_style(True)
        self._go_glow(1.0)

    def focusOutEvent(self, e):
        super().focusOutEvent(e)
        self.refresh_style(False)
        self._go_glow(0.0)

    def mousePressEvent(self, e):
        had = self.hasFocus()
        super().mousePressEvent(e)
        if not had:
            self.selectAll()

    def paintEvent(self, e):
        super().paintEvent(e)
        mode = UI["mode"]
        if mode == "default":
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect())
        if mode == "mac":
            rad = max(3.0, rr(r.height() / 2.0))
            hi = QLinearGradient(r.topLeft(), r.topRight())
            hi.setColorAt(0.0, QColor(255, 255, 255, 0))
            hi.setColorAt(0.5, QColor(255, 255, 255, 46))
            hi.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setPen(QPen(QBrush(hi), 1.0))
            p.drawLine(QPointF(r.left() + rad * 0.6, r.top() + 0.5), QPointF(r.right() - rad * 0.6, r.top() + 0.5))
            if self._glow > 0.01:
                a = self._glow
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(accent_color(int(28 * a)), 3.0))
                p.drawRoundedRect(r.adjusted(2, 2, -2, -2), rad - 2, rad - 2)
                p.setPen(QPen(accent_color(int(150 * a)), 1.2))
                p.drawRoundedRect(r.adjusted(0.7, 0.7, -0.7, -0.7), rad - 0.7, rad - 0.7)
        elif self._glow > 0.01:
            clip = QPainterPath()
            clip.addRoundedRect(r, 5, 5)
            p.setClipPath(clip)
            w = r.width() * self._glow
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(accent_color())
            p.drawRect(QRectF(r.center().x() - w / 2, r.bottom() - 2, w, 2))
        p.end()


class FadeButton(QToolButton):
    """Tool button with a smooth hover highlight. macOS style adds a glass hover and a ripple on press."""
    RIPPLE = True

    def __init__(self, radius=10):
        super().__init__()
        self._h = 0.0
        self.radius = radius
        self._rip, self._rip_pt = 1.0, QPointF()
        self._anim = QVariantAnimation(self)
        self._anim.setDuration(170)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._anim.valueChanged.connect(self._set_h)
        self._rip_anim = QVariantAnimation(self)
        self._rip_anim.setDuration(520)
        self._rip_anim.setStartValue(0.0)
        self._rip_anim.setEndValue(1.0)
        self._rip_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._rip_anim.valueChanged.connect(self._set_rip)

    def _set_h(self, v):
        self._h = float(v)
        self.update()

    def _set_rip(self, v):
        self._rip = float(v)
        self.update()

    def _go(self, to):
        self._anim.stop()
        self._anim.setStartValue(self._h)
        self._anim.setEndValue(to)
        self._anim.start()

    def enterEvent(self, e):
        self._go(1.0)
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._go(0.0)
        super().leaveEvent(e)

    def mousePressEvent(self, e):
        if self.RIPPLE and UI["mode"] == "mac" and self.isEnabled() and e.button() == Qt.MouseButton.LeftButton:
            self._rip_pt = QPointF(e.position())
            self._rip_anim.stop()
            self._rip_anim.start()
        super().mousePressEvent(e)

    def paintEvent(self, e):
        super().paintEvent(e)
        mode = UI["mode"]
        rip = mode == "mac" and self._rip < 1.0
        if not ((self._h > 0.01 or rip) and self.isEnabled()):
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        r = QRectF(self.rect())
        rad = shape_radius(self.radius, r)
        if self._h > 0.01:
            if mode == "mac":
                g = QLinearGradient(r.topLeft(), r.bottomLeft())
                g.setColorAt(0.0, glass_rgba(30 * self._h))
                g.setColorAt(1.0, glass_rgba(10 * self._h))
                p.setBrush(QBrush(g))
                p.drawRoundedRect(r, rad, rad)
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(glass_rgba(24 * self._h), 1))
                p.drawRoundedRect(r.adjusted(0.5, 0.5, -0.5, -0.5), rad, rad)
                p.setPen(Qt.PenStyle.NoPen)
            else:
                p.setBrush(glass_rgba((20 if mode == "windows" else 24) * self._h))
                p.drawRoundedRect(r, rad, rad)
        if rip:
            clip = QPainterPath()
            clip.addRoundedRect(r, rad, rad)
            p.setClipPath(clip)
            k = max(r.width(), r.height()) * (0.35 + 0.9 * self._rip)
            p.setBrush(QColor(255, 255, 255, int(44 * (1.0 - self._rip))))
            p.drawEllipse(self._rip_pt, k, k)
        p.end()


class NewGroupButton(FadeButton):
    """The "+ Group" button. Its dashed outline is painted here with antialiasing, because Qt's own dashed
    stylesheet border with rounded corners comes out jagged and broken at the corners.
    In the compact sidebar it becomes a plain icon button the same size as Focus and Search."""
    icon_only = False

    def paintEvent(self, e):
        super().paintEvent(e)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        if self.icon_only:
            col = _mix(QColor(themed("#b5c6d4")), QColor("#ffffff"), self._h)
            draw_glyph(p, "group", QRectF((self.width() - 18) / 2, (self.height() - 18) / 2, 18, 18), col, ToolIcon.STROKE)
            p.end()
            return
        key, h = style_key(), self._h
        r = QRectF(self.rect()).adjusted(0.8, 0.8, -0.8, -0.8)
        if key == "mac":
            g = QLinearGradient(r.topLeft(), r.bottomLeft())
            g.setColorAt(0.0, QColor(255, 255, 255, int(26 + 22 * h)))
            g.setColorAt(1.0, QColor(255, 255, 255, int(8 + 12 * h)))
            p.setPen(QPen(QColor(255, 255, 255, int(52 + 44 * h)), 1.0))
            p.setBrush(QBrush(g))
            p.drawRoundedRect(r, r.height() / 2, r.height() / 2)
        elif key == "windows":
            p.setPen(QPen(QColor(255, 255, 255, int(28 + 26 * h)), 1.0))
            p.setBrush(QColor(255, 255, 255, int(10 + 16 * h)))
            p.drawRoundedRect(r, 4, 4)
        elif key == "term":
            p.setPen(QPen(QColor(TERM_EDGE), 1.0))
            p.setBrush(QColor(QColor(TERM_BRIGHT).red(), QColor(TERM_BRIGHT).green(), QColor(TERM_BRIGHT).blue(), int(36 * h)))
            p.drawRoundedRect(r, 2, 2)
        else:
            pen = QPen(QColor(255, 255, 255, 64 if self._h > 0.5 else 46), 1.2)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            pen.setDashPattern([3.0, 3.0])
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(r, rr(self.radius), rr(self.radius))
        p.end()


TAB_MIME = "application/x-fjord-tab"
GAP = 8


ROLE_EXTRA = 257
ROLE_ANIM = 258
HTAB_MAX_W = 180
HTAB_MIN_W = 40
HTAB_TIGHT_W = 104
HTAB_ICON_W = 60
ROLE_GROUPED = 259


class DropTarget:
    """Mixin: besides whatever the widget already accepts, let it take anything that isn't one of Fjord's own
    tab / scratchpad drags and hand it to the Scratchpad. `scratch` is the ScratchDrawer, set once the UI exists."""
    scratch = None

    def _sp_ok(self, e):
        return DropTarget.scratch is not None and DropTarget.scratch.accepts(e.mimeData())

    def dragEnterEvent(self, e):
        if self._sp_ok(e):
            DropTarget.scratch.drop_hint(True)
            e.acceptProposedAction()
        else:
            super().dragEnterEvent(e)

    def dragMoveEvent(self, e):
        if self._sp_ok(e):
            e.acceptProposedAction()
        else:
            super().dragMoveEvent(e)

    def dragLeaveEvent(self, e):
        if DropTarget.scratch is not None:
            DropTarget.scratch.drop_hint(False)
        super().dragLeaveEvent(e)

    def dropEvent(self, e):
        if self._sp_ok(e):
            DropTarget.scratch.drop_hint(False)
            DropTarget.scratch.ingest(e.mimeData())
            e.acceptProposedAction()
        else:
            super().dropEvent(e)


class GroupChip(DropTarget, QWidget):
    """Island header: a coloured name pill with a chevron.
    Click = slide the island's tabs out / back in, right-click = menu, drop a tab on it = add."""
    clicked = pyqtSignal()

    def __init__(self, gid, on_drop):
        super().__init__()
        self.gid, self.on_drop = gid, on_drop
        self.name, self.color, self.count = "", "#4fb0e8", 0
        self.compact = self.horiz = False
        self.open_p = 1.0
        self.active = self.hover = self.drop = self._press = False
        self.setAcceptDrops(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self._hp = self._pp = 0.0
        self._intro = 1.0
        self._hov_anim, self._press_anim = QVariantAnimation(self), QVariantAnimation(self)
        self._hov_anim.valueChanged.connect(self._set_hp)
        self._press_anim.valueChanged.connect(self._set_pp)

    def _set_hp(self, v):
        self._hp = float(v)
        self.update()

    def _set_pp(self, v):
        self._pp = float(v)
        self.update()

    def _tween(self, anim, start, end, ms):
        anim.stop()
        anim.setDuration(ms)
        anim.setStartValue(float(start))
        anim.setEndValue(float(end))
        anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        anim.start()

    def intro(self):
        """Pop in: grow from a slightly smaller size while fading in (a soft spring in the macOS style)."""
        self._intro = 0.0
        a = QVariantAnimation(self)
        a.setDuration(420)
        a.setStartValue(0.0)
        a.setEndValue(1.0)
        a.setEasingCurve(mac_curve(True, 1.15) if style_key() == "mac" else group_curve())

        def step(v):
            self._intro = float(v)
            self.update()
        a.valueChanged.connect(step)
        a.start()
        self._intro_anim = a

    def configure(self, name, color, count, compact, horiz):
        self.name, self.color, self.count = name, color, count
        self.compact, self.horiz = compact, horiz
        self.setToolTip("%s (%d tab%s)" % (name, count, "" if count == 1 else "s"))
        self.update()

    def set_open(self, p):
        if abs(p - self.open_p) > 0.001:
            self.open_p = p
            self.update()

    def set_active(self, on):
        if on != self.active:
            self.active = on
            self.update()

    def enterEvent(self, e):
        self.hover = True
        self._tween(self._hov_anim, self._hp, 1.0, 150)
        super().enterEvent(e)

    def leaveEvent(self, e):
        self.hover = False
        if not self.drop:
            self._tween(self._hov_anim, self._hp, 0.0, 260)
        self._tween(self._press_anim, self._pp, 0.0, 200)
        super().leaveEvent(e)

    def mousePressEvent(self, e):
        self._press = e.button() == Qt.MouseButton.LeftButton
        if self._press:
            self._tween(self._press_anim, self._pp, 1.0, 90)
        super().mousePressEvent(e)

    def mouseReleaseEvent(self, e):
        if self._press and e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            self.clicked.emit()
        self._press = False
        self._tween(self._press_anim, self._pp, 0.0, 240)
        super().mouseReleaseEvent(e)

    def dragEnterEvent(self, e):
        if e.mimeData().hasFormat(TAB_MIME):
            self.drop = True
            self._tween(self._hov_anim, self._hp, 1.0, 150)
            e.acceptProposedAction()
        else:
            super().dragEnterEvent(e)

    def dragLeaveEvent(self, e):
        self.drop = False
        self._tween(self._hov_anim, self._hp, 1.0 if self.hover else 0.0, 220)
        super().dragLeaveEvent(e)

    def dropEvent(self, e):
        if not e.mimeData().hasFormat(TAB_MIME):
            super().dropEvent(e)
            return
        self.drop = False
        self._tween(self._hov_anim, self._hp, 1.0 if self.hover else 0.0, 220)
        self.on_drop(int(bytes(e.mimeData().data(TAB_MIME)).decode()), self.gid)
        e.acceptProposedAction()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        key = style_key()
        col = QColor(self.color)
        f = QFont(self.font())
        f.setPixelSize(11)
        f.setBold(key != "term")
        if key == "term":
            try:
                f.setFamilies(TERM_FONTS)
            except Exception:
                pass
        fm = QFontMetrics(f)
        ph = 22.0 if key in ("mac", "windows") else 20.0
        chev = 22.0 if key == "term" else 12.0
        pad = 8.0
        lead = {"windows": 15.0, "term": 6.0}.get(key, pad)
        collapsed = self.open_p < 0.5
        if self.compact:
            label, pw, x0 = "", 30.0, (self.width() - 30.0) / 2
        else:
            room = self.width() - 6 - lead - pad - chev - 4 - (30 if collapsed else 8)
            label = fm.elidedText(self.name, Qt.TextElideMode.ElideRight, max(20, int(room)))
            pw, x0 = lead + pad + chev + 4 + fm.horizontalAdvance(label), 6.0
        y0 = (self.height() - ph) / 2
        rect = QRectF(x0, y0, pw, ph)
        hp = max(self._hp, 1.0 if self.drop else 0.0)
        ring = self.drop or (self.active and collapsed)
        sc = (0.86 + 0.14 * self._intro) * (1.0 - 0.04 * self._pp)
        p.setOpacity(max(0.0, min(1.0, self._intro * 1.5)))
        p.translate(rect.center())
        p.scale(sc, sc)
        p.translate(-rect.center())
        p.setPen(Qt.PenStyle.NoPen)
        if key == "mac":
            g = QLinearGradient(rect.topLeft(), rect.bottomLeft())
            g.setColorAt(0.0, QColor(col.red(), col.green(), col.blue(), int(125 + 60 * hp)))
            g.setColorAt(1.0, QColor(col.red(), col.green(), col.blue(), int(70 + 50 * hp)))
            p.setBrush(QBrush(g))
            p.setPen(QPen(QColor(255, 255, 255, int(70 + 60 * hp)), 1.0))
            p.drawRoundedRect(rect.adjusted(0.5, 0.5, -0.5, -0.5), ph / 2, ph / 2)
            hl = QLinearGradient(rect.topLeft(), QPointF(rect.left(), rect.top() + ph * 0.55))
            hl.setColorAt(0.0, QColor(255, 255, 255, 80))
            hl.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(hl))
            p.drawRoundedRect(rect.adjusted(1.5, 1.5, -1.5, -ph * 0.45), ph / 2 - 1.5, ph / 2 - 1.5)
            ink = QColor(255, 255, 255, 245)
            if ring:
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(QColor(255, 255, 255, 225), 1.6))
                p.drawRoundedRect(rect.adjusted(0.8, 0.8, -0.8, -0.8), ph / 2, ph / 2)
        elif key == "windows":
            p.setBrush(QColor(col.red(), col.green(), col.blue(), int(46 + 44 * hp)))
            p.drawRoundedRect(rect, 5, 5)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(col.red(), col.green(), col.blue(), 235) if ring else QColor(255, 255, 255, int(18 + 16 * hp)), 1.0))
            p.drawRoundedRect(rect.adjusted(0.5, 0.5, -0.5, -0.5), 5, 5)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(col)
            p.drawRoundedRect(QRectF(x0 + 5, y0 + 5, 3, ph - 10), 1.5, 1.5)
            ink = QColor(242, 242, 242)
        elif key == "term":
            p.setBrush(QColor(col.red(), col.green(), col.blue(), int(34 * hp)))
            p.setPen(QPen(QColor(col.red(), col.green(), col.blue(), int(175 + 80 * hp)), 1.6 if ring else 1.0))
            p.drawRoundedRect(rect.adjusted(0.5, 0.5, -0.5, -0.5), 2, 2)
            ink = col
        else:
            p.setBrush(QColor(col.red(), col.green(), col.blue(), int(215 + 40 * hp)))
            p.drawRoundedRect(rect, ph / 2, ph / 2)
            if ring:
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(QColor(255, 255, 255, 230), 1.6))
                p.drawRoundedRect(QRectF(x0 + 0.8, y0 + 0.8, pw - 1.6, ph - 1.6), ph / 2, ph / 2)
            ink = QColor(11, 20, 29)
        cx = x0 + lead + chev / 2 - 1
        if key == "term":
            p.setFont(f)
            p.setPen(ink)
            p.drawText(QRectF(x0 + lead - 1, y0, chev + 2, ph), Qt.AlignmentFlag.AlignCenter,
                       "[v]" if self.open_p >= 0.5 else "[>]")
        else:
            p.save()
            p.translate(cx, y0 + ph / 2)
            p.rotate(-90.0 * (1.0 - self.open_p))
            pen = QPen(ink, 1.8)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPolyline(QPolygonF([QPointF(-3.2, -1.6), QPointF(0.0, 1.6), QPointF(3.2, -1.6)]))
            p.restore()
        if label:
            p.setFont(f)
            p.setPen(ink)
            p.drawText(QRectF(x0 + lead + chev + 3, y0, pw, ph),
                       Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, label)
        if not self.compact and self.open_p < 0.999:
            f.setBold(False)
            p.setFont(f)
            p.setPen(QColor(col.red(), col.green(), col.blue(), int(210 * (1.0 - self.open_p))))
            p.drawText(QRectF(x0 + pw + 7, 0, 48, self.height()),
                       Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                       ("(%d)" if key == "term" else "%d") % self.count)
        p.end()

MAX_PANES = 4


class SplitHandle(QWidget):
    """Draggable divider between two neighbouring panes (double-click = equal widths)."""
    def __init__(self, area, idx):
        super().__init__(area)
        self.area, self.idx = area, idx
        self.setCursor(Qt.CursorShape.SplitHCursor)
        self.hide()

    def mouseMoveEvent(self, e):
        if e.buttons() & Qt.MouseButton.LeftButton:
            self.area.drag_handle(self.idx, self.mapToParent(e.position().toPoint()).x())

    def mouseDoubleClickEvent(self, e):
        n = len(self.area.weights)
        self.area.weights = [1.0 / n] * n
        self.area.relayout()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(accent_color(110))
        p.drawRoundedRect(QRectF(self.width() / 2 - 1.5, self.height() / 2 - 22, 3, 44), 1.5, 1.5)
        p.end()


