class GestureTrail(QWidget):
    """Mouse-transparent overlay that draws the line you drag while making a mouse gesture, with the strokes so far
    and what they will do shown in a small pill at the top of the page."""
    def __init__(self, area):
        super().__init__(area)
        self.pts, self.text, self.known, self.alpha = [], "", False, 1.0
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground)
        self.fade = QVariantAnimation(self)
        self.fade.setDuration(260)
        self.fade.setStartValue(1.0)
        self.fade.setEndValue(0.0)
        self.fade.valueChanged.connect(self._fade_step)
        self.fade.finished.connect(self._fade_done)
        self.hide()

    def begin(self, gpos):
        self.fade.stop()
        self.alpha, self.text, self.known = 1.0, "", False
        self.pts = [self.mapFromGlobal(gpos.toPoint())]
        self.setGeometry(self.parentWidget().rect())
        self.raise_()
        self.show()

    def add(self, gpos):
        p = self.mapFromGlobal(gpos.toPoint())
        if self.pts and abs(p.x() - self.pts[-1].x()) + abs(p.y() - self.pts[-1].y()) < 2:
            return
        a = self.pts[-1] if self.pts else p
        self.pts.append(p)
        if len(self.pts) > 1500:
            del self.pts[:500]
        self.update(QRect(a, p).normalized().adjusted(-9, -9, 9, 9))

    def set_label(self, text, known):
        if (text, known) != (self.text, self.known):
            self.text, self.known = text, known
            self.update()

    def end(self):
        if self.isVisible():
            self.fade.start()

    def _fade_step(self, v):
        self.alpha = float(v)
        self.update()

    def _fade_done(self):
        self.hide()
        self.pts, self.text = [], ""

    def paintEvent(self, e):
        if not self.pts:
            return
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            p.setOpacity(self.alpha)
            if len(self.pts) > 1:
                path = QPainterPath(QPointF(self.pts[0]))
                for q in self.pts[1:]:
                    path.lineTo(QPointF(q))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.setPen(QPen(accent_color(70), 9, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
                p.drawPath(path)
                p.setPen(QPen(accent_color(235), 3.5, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
                p.drawPath(path)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(ACCENT["alt"]))
            p.drawEllipse(QPointF(self.pts[0]), 4.5, 4.5)
            if self.text:
                f = QFont(self.font())
                f.setPointSizeF(max(11.0, f.pointSizeF() + 1.5))
                p.setFont(f)
                w = QFontMetrics(f).horizontalAdvance(self.text) + 36
                r = QRectF((self.width() - w) / 2.0, 16, w, 36)
                p.setBrush(QColor(11, 20, 29, 228 if self.known else 175))
                p.setPen(QPen(accent_color(190 if self.known else 60), 1))
                p.drawRoundedRect(r, 18, 18)
                p.setPen(QColor(236, 244, 250, 255 if self.known else 150))
                p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), self.text)
        finally:
            p.end()


class TabArea(QWidget):
    """Replacement for QStackedWidget: shows one tab, or 2-4 tabs side by side in split view."""
    def __init__(self):
        super().__init__()
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.items, self.cur = [], -1
        self.split, self.weights, self.handles = None, [], []
        self.trail = GestureTrail(self)
        self.corners = PageCorners(self)
        self.veil = PageVeil(self)

    def count(self):
        return len(self.items)

    def widget(self, i):
        return self.items[i] if 0 <= i < len(self.items) else None

    def indexOf(self, w):
        return self.items.index(w) if w in self.items else -1

    def currentIndex(self):
        return self.cur

    def currentWidget(self):
        return self.widget(self.cur)

    def in_split(self, w):
        return bool(self.split) and any(w is t for t in self.split)

    def addWidget(self, w):
        return self.insertWidget(len(self.items), w)

    def insertWidget(self, i, w):
        cw = self.currentWidget()
        w.setParent(self)
        w.hide()
        self.items.insert(i, w)
        self.cur = self.items.index(cw) if cw is not None else 0
        self.relayout()
        return i

    def removeWidget(self, w):
        i = self.indexOf(w)
        if i < 0:
            return
        cw = self.currentWidget()
        self.items.pop(i)
        w.hide()
        if self.in_split(w):
            k = next(j for j, t in enumerate(self.split) if t is w)
            self.split.pop(k)
            self.weights.pop(k)
            if len(self.split) < 2:
                self.split, self.weights = None, []
            else:
                tot = sum(self.weights)
                self.weights = [x / tot for x in self.weights]
        if cw is w or cw is None:
            self.cur = min(i, len(self.items) - 1)
        else:
            self.cur = self.items.index(cw)
        self.relayout()

    def reorder(self, i, to):
        cw = self.currentWidget()
        self.items.insert(to, self.items.pop(i))
        self.cur = self.items.index(cw) if cw is not None else -1

    def setCurrentIndex(self, i):
        if 0 <= i < len(self.items):
            changed = i != self.cur
            self.cur = i
            self.relayout()
            if changed:
                self.veil.pulse()

    def set_split(self, tabs, weights=None):
        """Show `tabs` side by side (2 or more). An empty/short list leaves split view."""
        if len(tabs) < 2:
            self.split, self.weights = None, []
        else:
            n = len(tabs)
            self.split = list(tabs)
            self.weights = list(weights) if weights and len(weights) == n else [1.0 / n] * n
        self.relayout()

    def drag_handle(self, idx, x):
        n = len(self.split)
        total = self.width() - GAP * (n - 1)
        start = sum(self.weights[j] * total + GAP for j in range(idx))
        pair = (self.weights[idx] + self.weights[idx + 1]) * total
        mn = min(120, pair / 3)
        left = max(mn, min(pair - mn, x - GAP / 2 - start))
        self.weights[idx] = left / total
        self.weights[idx + 1] = (pair - left) / total
        self.relayout()

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self.relayout()

    def relayout(self):
        r = self.rect()
        cw = self.currentWidget()
        visible = []
        sp = self.split
        if sp and cw is not None and self.in_split(cw):
            n = len(sp)
            while len(self.handles) < n - 1:
                self.handles.append(SplitHandle(self, len(self.handles)))
            total = r.width() - GAP * (n - 1)
            x = 0
            for k, t in enumerate(sp):
                w = int(total * self.weights[k]) if k < n - 1 else r.width() - x
                t.setGeometry(x, 0, w, r.height())
                visible.append(t)
                x += w
                if k < n - 1:
                    h = self.handles[k]
                    h.setGeometry(x, 0, GAP, r.height())
                    h.show()
                    h.raise_()
                    x += GAP
            for h in self.handles[n - 1:]:
                h.hide()
        else:
            for h in self.handles:
                h.hide()
            if cw is not None:
                cw.setGeometry(r)
                visible = [cw]
        for w in self.items:
            w.setVisible(any(w is v for v in visible))
        self.trail.setGeometry(self.rect())
        self.trail.raise_()
        self.veil.setGeometry(self.rect())
        self.veil.raise_()
        self.corners.setGeometry(self.rect())
        self.corners.raise_()
        for h in self.handles:
            if h.isVisible():
                h.raise_()
        self.corners.update()


class SideFrame(DropTarget, QFrame):
    def __init__(self, on_leave, on_geom=None, on_menu=None):
        super().__init__()
        self.on_leave = on_leave
        self.on_geom = on_geom
        self.on_menu = on_menu
        self.drop_on = False
        self.setAcceptDrops(True)

    def _geom(self):
        if self.on_geom:
            self.on_geom()

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._geom()

    def moveEvent(self, e):
        super().moveEvent(e)
        self._geom()

    def showEvent(self, e):
        super().showEvent(e)
        self._geom()

    def hideEvent(self, e):
        super().hideEvent(e)
        self._geom()

    def contextMenuEvent(self, e):
        if self.on_menu:
            self.on_menu(e.globalPos())
            e.accept()
        else:
            super().contextMenuEvent(e)

    def leaveEvent(self, e):
        self.on_leave()
        super().leaveEvent(e)

    def paintEvent(self, e):
        super().paintEvent(e)
        glass = UI["mode"] == "mac"
        if glass or self.drop_on:
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            if glass:
                paint_glass(p, self.rect(), 20)
            if self.drop_on:
                p.setPen(QPen(accent_color(190), 1.5, Qt.PenStyle.DashLine))
                p.setBrush(accent_color(16))
                p.drawRoundedRect(QRectF(self.rect()).adjusted(2.5, 2.5, -2.5, -2.5), rr(14), rr(14))
            p.end()


class HoverZone(QWidget):
    def __init__(self, on_enter):
        super().__init__()
        self.on_enter = on_enter

    def enterEvent(self, e):
        self.on_enter()
        super().enterEvent(e)


class GeomWatch(QObject):
    """Calls back whenever the widget it is installed on is moved or resized."""
    def __init__(self, parent, cb):
        super().__init__(parent)
        self.cb = cb

    def eventFilter(self, obj, ev):
        if ev.type() in (QEvent.Type.Resize, QEvent.Type.Move):
            self.cb()
        return False


class EssTile(FadeButton):
    """An Essentials tile. When selected it gets a gradient outline built from the colours of its own icon."""

    def __init__(self, radius=12):
        super().__init__(radius)
        self.grad = []

    def paintEvent(self, e):
        super().paintEvent(e)
        if not self.grad or not self.isChecked():
            return
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            r = QRectF(self.rect()).adjusted(0.9, 0.9, -0.9, -0.9)
            g = QLinearGradient(r.topLeft(), r.bottomRight())
            last = max(1, len(self.grad) - 1)
            for i, col in enumerate(self.grad):
                c = QColor(col)
                c.setAlpha(235)
                g.setColorAt(i / last, c)
            p.setPen(QPen(QBrush(g), 1.8))
            p.setBrush(Qt.BrushStyle.NoBrush)
            rad = shape_radius(self.radius, r)
            p.drawRoundedRect(r, rad, rad)
        finally:
            p.end()


class EssDrop(DropTarget, QWidget):
    """The Essentials grid. Drop a tab on it to add that site to Essentials.
    While a tab is being dragged and there are no Essentials yet, it shows an empty drop zone to aim at."""
    def __init__(self, on_drop):
        super().__init__()
        self.on_drop = on_drop
        self.drop = self.zone = False
        self.setAcceptDrops(True)

    def set_zone(self, on):
        self.zone = on
        self.update()

    def dragEnterEvent(self, e):
        if e.mimeData().hasFormat(TAB_MIME):
            self.drop = True
            self.update()
            e.acceptProposedAction()
        else:
            super().dragEnterEvent(e)

    def dragMoveEvent(self, e):
        if e.mimeData().hasFormat(TAB_MIME):
            e.acceptProposedAction()
        else:
            super().dragMoveEvent(e)

    def dragLeaveEvent(self, e):
        self.drop = False
        self.update()
        super().dragLeaveEvent(e)

    def dropEvent(self, e):
        if not e.mimeData().hasFormat(TAB_MIME):
            super().dropEvent(e)
            return
        self.drop = False
        self.update()
        e.acceptProposedAction()
        self.on_drop(int(bytes(e.mimeData().data(TAB_MIME)).decode()))

    def paintEvent(self, e):
        if not (self.drop or self.zone):
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        if self.drop:
            p.setBrush(accent_color(45))
            p.setPen(QPen(accent_color(210), 1.5))
        else:
            p.setBrush(Qt.BrushStyle.NoBrush)
            pen = QPen(accent_color(120), 1.5)
            pen.setStyle(Qt.PenStyle.DashLine)
            p.setPen(pen)
        p.drawRoundedRect(r, 12, 12)
        if self.zone and self.layout() is not None and self.layout().count() == 0:
            p.setPen(accent_color(230 if self.drop else 170))
            txt = "Drop to add to Essentials" if self.width() >= 130 else "\uff0b"
            p.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, txt)


class TabList(DropTarget, QListWidget):
    """Sidebar tab list. Drag a tab onto another tab to open them in split view."""
    def __init__(self, on_middle):
        super().__init__()
        self.on_middle = on_middle
        self.on_drop = None
        self.on_drag = None     # called with True / False when a tab drag starts / ends
        self.drag_start = None
        self._hover_row = -1
        self.islands = []
        self.setHorizontalScrollMode(QListWidget.ScrollMode.ScrollPerPixel)
        self.setVerticalScrollMode(QListWidget.ScrollMode.ScrollPerPixel)
        self.setAcceptDrops(True)
        self.viewport().setAcceptDrops(True)
        m = self.model()
        for sig in (m.rowsInserted, m.rowsRemoved, m.dataChanged, m.layoutChanged):
            sig.connect(lambda *a: self.updateGeometry())
        self._mac_init()

    def sizeHint(self):
        if self.flow() != QListView.Flow.LeftToRight:
            return super().sizeHint()
        w = 2 * self.frameWidth() + self.spacing()
        for i in range(self.count()):
            it = self.item(i)
            if not it.isHidden():
                w += it.sizeHint().width() + self.spacing()
        return QSize(w, self.maximumHeight())

    def minimumSizeHint(self):
        if self.flow() != QListView.Flow.LeftToRight:
            return super().minimumSizeHint()
        return QSize(60, self.maximumHeight())

    def paintEvent(self, e):
        if self.islands:
            horiz = self.flow() == QListView.Flow.LeftToRight
            p = QPainter(self.viewport())
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            for color, rows in self.islands:
                u = None
                for r in rows:
                    it = self.item(r)
                    if it is None or it.isHidden():
                        continue
                    rc = self.visualItemRect(it)
                    if rc.width() <= 0 or rc.height() <= 0:
                        continue
                    u = rc if u is None else u.united(rc)
                if u is None:
                    continue
                c = QColor(color)
                box = QRectF(u).adjusted(-1, 1, 1, -1) if horiz else QRectF(u).adjusted(1, 1, -1, -1)
                ik = style_key()
                fill_a, edge_a, rad = {"mac": (30, 85, rr(18)), "windows": (22, 70, 6.0), "term": (10, 140, 2.0)}.get(
                    ik, (32, 95, rr(14)))
                p.setBrush(QColor(c.red(), c.green(), c.blue(), fill_a))
                p.setPen(QPen(QColor(c.red(), c.green(), c.blue(), edge_a), 1))
                p.drawRoundedRect(box, rad, rad)
            p.end()
        if UI["mode"] == "mac":
            mp = QPainter(self.viewport())
            try:
                mp.setRenderHint(QPainter.RenderHint.Antialiasing)
                self._mac_underlay(mp)
            finally:
                mp.end()
        super().paintEvent(e)

    def _mac_init(self):
        self._sel_from, self._sel_last, self._sel_t = None, None, 1.0
        self._hov_item, self._hov_from, self._hov_last, self._hov_t, self._hov_a = None, None, None, 1.0, 0.0
        self._press, self._press_item = 0.0, None
        self._sel_anim = QVariantAnimation(self)
        self._sel_anim.setDuration(440)
        self._sel_anim.setStartValue(0.0)
        self._sel_anim.setEndValue(1.0)
        self._sel_anim.setEasingCurve(mac_curve(True, 1.05))
        self._sel_anim.valueChanged.connect(self._sel_step)
        self._sel_anim.finished.connect(self._sel_done)
        self._hov_anim = QVariantAnimation(self)
        self._hov_anim.setDuration(260)
        self._hov_anim.setStartValue(0.0)
        self._hov_anim.setEndValue(1.0)
        self._hov_anim.setEasingCurve(mac_curve())
        self._hov_anim.valueChanged.connect(self._hov_step)
        self._hov_anim.finished.connect(self._hov_done)
        self._hov_fade = QVariantAnimation(self)
        self._hov_fade.valueChanged.connect(self._fade_step)
        self._hov_fade.finished.connect(self._fade_done)
        self._press_anim = QVariantAnimation(self)
        self._press_anim.valueChanged.connect(self._press_step)
        self._press_anim.finished.connect(self._press_done)
        self.currentRowChanged.connect(self._sel_changed)

    def setFlow(self, flow):
        self._sel_last = self._sel_from = self._hov_last = self._hov_from = None
        self._hov_item, self._hov_a = None, 0.0
        super().setFlow(flow)

    def _sel_step(self, v):
        self._sel_t = float(v)
        self.viewport().update()

    def _sel_done(self):
        self._sel_from, self._sel_t = None, 1.0
        self.viewport().update()

    def _hov_step(self, v):
        self._hov_t = float(v)
        self.viewport().update()

    def _hov_done(self):
        self._hov_from, self._hov_t = None, 1.0

    def _fade_step(self, v):
        self._hov_a = float(v)
        self.viewport().update()

    def _fade_done(self):
        if self._hov_a < 0.01:
            self._hov_last = self._hov_from = None

    def _press_step(self, v):
        self._press = float(v)
        self.viewport().update()

    def _press_done(self):
        if self._press_anim.endValue() == 0.0 and abs(self._press) < 0.001:
            self._press_item = None

    def _press_to(self, v):
        if UI["mode"] != "mac":
            return
        if v == 0.0 and self._press == 0.0:
            self._press_anim.stop()
            self._press_item = None
            return
        self._press_anim.stop()
        self._press_anim.setStartValue(self._press)
        self._press_anim.setEndValue(v)
        self._press_anim.setDuration(110 if v else 340)
        self._press_anim.setEasingCurve(QEasingCurve.Type.OutCubic if v else mac_curve(True, 2.4))
        self._press_anim.start()

    def _sel_changed(self, row):
        if UI["mode"] != "mac" or self._sel_last is None:
            return
        self._sel_anim.stop()
        self._sel_from = QRectF(self._sel_last)
        self._sel_t = 0.0
        self._sel_anim.start()
        self.viewport().update()

    def _fade_hover(self, to):
        self._hov_fade.stop()
        self._hov_fade.setStartValue(self._hov_a)
        self._hov_fade.setEndValue(to)
        self._hov_fade.setDuration(300 if to < 0.5 else 200)
        self._hov_fade.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._hov_fade.start()

    def _hover_to(self, it):
        if it is self._hov_item:
            return
        self._hov_item = it
        if it is None:
            self._fade_hover(0.0)
        else:
            if self._hov_a > 0.04 and self._hov_last is not None:
                self._hov_anim.stop()
                self._hov_from, self._hov_t = QRectF(self._hov_last), 0.0
                self._hov_anim.start()
            else:
                self._hov_from = None
            self._fade_hover(1.0)
        self.viewport().update()

    def hover_row(self, row):
        """Called by a TabRow when the pointer enters (row) or leaves (None) it."""
        if UI["mode"] != "mac":
            return
        it = None
        if row is not None:
            it = self.itemAt(row.geometry().center())
            if it is not None and self.row(it) == self.currentRow():
                it = None
            elif it is not None and row.hdr_chip is not None and row.hdr_extra:
                pos = row.mapFromGlobal(QCursor.pos())
                if (pos.x() < row.hdr_extra) if row.hdr_horiz else (pos.y() < row.hdr_extra):
                    it = None
        self._hover_to(it)

    def _pill_rect(self, it):
        """Where a tab's highlight pill sits, in viewport coordinates (None when the tab isn't showing)."""
        if it is None or it.isHidden():
            return None
        rc = self.visualItemRect(it)
        if rc.width() <= 0 or rc.height() <= 0:
            return None
        extra = it.data(ROLE_EXTRA) or 0
        grouped = bool(it.data(ROLE_GROUPED))
        r = QRectF(rc)
        if self.flow() == QListView.Flow.LeftToRight:
            return r.adjusted(extra + 2, 3 + (3 if grouped else 0), -2, -3 - (3 if grouped else 0))
        return r.adjusted(4 if grouped else 0, extra + 2, -4 if grouped else 0, -2)

    @staticmethod
    def _lerp_rect(a, b, t):
        return QRectF(a.x() + (b.x() - a.x()) * t, a.y() + (b.y() - a.y()) * t,
                      max(0.0, a.width() + (b.width() - a.width()) * t), max(0.0, a.height() + (b.height() - a.height()) * t))

    def _mac_underlay(self, p):
        off = QPointF(self.horizontalScrollBar().value(), self.verticalScrollBar().value())
        radius = 99 if self.flow() == QListView.Flow.LeftToRight else 12
        if self._hov_a > 0.01:
            tgt = self._pill_rect(self._hov_item)
            r = None
            if tgt is not None:
                tgt = tgt.translated(off)
                r = self._lerp_rect(self._hov_from, tgt, self._hov_t) if self._hov_from is not None else tgt
                self._hov_last = QRectF(r)
            elif self._hov_last is not None:
                r = QRectF(self._hov_last)
            if r is not None:
                d = 2.0 * self._press if (self._press_item is not None and self._press_item is self._hov_item) else 0.0
                rv = r.translated(-off).adjusted(d, d, -d, -d)
                a = self._hov_a
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(glass_rgba(12 * a))
                p.drawRoundedRect(rv, min(rv.height() / 2.0, rr(radius)), min(rv.height() / 2.0, rr(radius)))
                paint_glass(p, rv, radius, 0.4 * a)
        cur = self.currentItem()
        tgt = self._pill_rect(cur)
        if tgt is None:
            return
        tgt = tgt.translated(off)
        r = self._lerp_rect(self._sel_from, tgt, self._sel_t) if self._sel_from is not None else tgt
        self._sel_last = QRectF(r)
        d = 2.0 * self._press if (self._press_item is not None and self._press_item is cur) else 0.0
        rv = r.translated(-off).adjusted(d, d, -d, -d)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glass_rgba(26))
        p.drawRoundedRect(rv, min(rv.height() / 2.0, rr(radius)), min(rv.height() / 2.0, rr(radius)))
        paint_glass(p, rv, radius, 1.0)

    def wheelEvent(self, e):
        if self.flow() == QListView.Flow.LeftToRight:
            bar = self.horizontalScrollBar()
            bar.setValue(bar.value() - e.angleDelta().y() - e.angleDelta().x())
            e.accept()
        else:
            super().wheelEvent(e)

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            self.drag_start = e.position().toPoint()
            if UI["mode"] == "mac":
                it = self.itemAt(self.drag_start)
                if it is not None:
                    self._press_to(1.0)
                    self._press_item = it
        super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        if (e.buttons() & Qt.MouseButton.LeftButton) and self.drag_start is not None:
            if (e.position().toPoint() - self.drag_start).manhattanLength() > QApplication.startDragDistance() * 2:
                it = self.itemAt(self.drag_start)
                self.drag_start = None
                if it is not None:
                    self._start_drag(self.row(it), it)
                    return
        super().mouseMoveEvent(e)

    def _start_drag(self, row, item):
        md = QMimeData()
        md.setData(TAB_MIME, str(row).encode())
        d = QDrag(self)
        d.setMimeData(md)
        pm = self.viewport().grab(self.visualItemRect(item))
        d.setPixmap(pm)
        d.setHotSpot(QPoint(pm.width() // 2, pm.height() // 2))
        self._press_to(0.0)
        if self.on_drag:
            self.on_drag(True)
        try:
            d.exec(Qt.DropAction.MoveAction)
        finally:
            if self.on_drag:
                self.on_drag(False)
        self.set_hover(-1)

    def mouseReleaseEvent(self, e):
        self.drag_start = None
        self._press_to(0.0)
        if e.button() == Qt.MouseButton.MiddleButton:
            it = self.itemAt(e.position().toPoint())
            if it:
                self.on_middle(self.row(it))
                return
        super().mouseReleaseEvent(e)

    def _src(self, e):
        return int(bytes(e.mimeData().data(TAB_MIME)).decode())

    def _row_at(self, e):
        it = self.itemAt(e.position().toPoint())
        return self.row(it) if it is not None else -1

    def dragEnterEvent(self, e):
        if e.mimeData().hasFormat(TAB_MIME):
            e.acceptProposedAction()
        else:
            super().dragEnterEvent(e)

    def dragMoveEvent(self, e):
        if e.mimeData().hasFormat(TAB_MIME):
            r = self._row_at(e)
            self.set_hover(r if r >= 0 and r != self._src(e) else -1)
            e.acceptProposedAction()
        else:
            super().dragMoveEvent(e)

    def dragLeaveEvent(self, e):
        self.set_hover(-1)
        super().dragLeaveEvent(e)

    def dropEvent(self, e):
        if e.mimeData().hasFormat(TAB_MIME):
            src, dst = self._src(e), self._row_at(e)
            self.set_hover(-1)
            if dst >= 0 and dst != src and self.on_drop:
                self.on_drop(src, dst)
            e.acceptProposedAction()
        else:
            super().dropEvent(e)

    def set_hover(self, r):
        if r == self._hover_row:
            return
        for row, on in ((self._hover_row, False), (r, True)):
            it = self.item(row) if row >= 0 else None
            w = self.itemWidget(it) if it is not None else None
            if w is not None:
                w.set_drop(on)
        self._hover_row = r


class TabDelegate(QStyledItemDelegate):
    """Draws a tab's hover/selected highlight below the island header its row may carry, inset inside islands."""
    def paint(self, painter, option, index):
        if UI["mode"] == "mac":
            option = QStyleOptionViewItem(option)
            option.state &= ~(QStyle.StateFlag.State_Selected | QStyle.StateFlag.State_MouseOver)
        extra = index.data(ROLE_EXTRA) or 0
        grouped = bool(index.data(ROLE_GROUPED))
        if extra or grouped:
            opt = QStyleOptionViewItem(option)
            horiz = option.widget is not None and option.widget.flow() == QListView.Flow.LeftToRight
            if horiz:
                opt.rect = opt.rect.adjusted(extra, 3 if grouped else 0, 0, -3 if grouped else 0)
            else:
                opt.rect = opt.rect.adjusted(4 if grouped else 0, extra, -4 if grouped else 0, 0)
            if extra and option.widget is not None:
                pos = option.widget.viewport().mapFromGlobal(QCursor.pos())
                if (pos.x() < opt.rect.left()) if horiz else (pos.y() < opt.rect.top()):
                    opt.state = opt.state & ~QStyle.StateFlag.State_MouseOver
            option = opt
        super().paint(painter, option, index)
        if UI["mode"] == "windows" and option.state & QStyle.StateFlag.State_Selected:
            horiz = option.widget is not None and option.widget.flow() == QListView.Flow.LeftToRight
            rc = QRectF(option.rect)
            pill = QRectF(rc.center().x() - 8, rc.bottom() - 4, 16, 3) if horiz else QRectF(rc.left() + 2, rc.center().y() - 8, 3, 16)
            painter.save()
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(accent_color())
            painter.drawRoundedRect(pill, 1.5, 1.5)
            painter.restore()


class TabPreview(QWidget):
    """Floating card shown while the pointer rests on a tab: a thumbnail of the page, its title and its address.
    It follows the interface style: Default is Fjord's own dark card with an accent edge; macOS is a rounded liquid-glass
    card with a soft shadow, centred text and springy motion; Windows is a flat Fluent flyout with tight corners and quick,
    plain motion. The card glides between tabs, the thumbnail cross-fades, and a tab with no snapshot yet shimmers."""
    W, PAD, THUMB_H, M = 248, 8, 140, 28
    _inst = None

    @classmethod
    def shared(cls):
        if cls._inst is None:
            cls._inst = cls()
        return cls._inst

    def __init__(self):
        super().__init__(None, Qt.WindowType.ToolTip | Qt.WindowType.FramelessWindowHint | Qt.WindowType.NoDropShadowWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.pm, self.old_pm, self.icon_pm, self.lines, self.sub, self.src = None, None, None, [], "", None
        self._t, self._shim, self._hiding, self._pop = 1.0, 0.0, False, False
        self.th = self._theme()
        self._fade = QPropertyAnimation(self, b"windowOpacity", self)
        self._fade.finished.connect(self._fade_done)
        self._move = QPropertyAnimation(self, b"pos", self)
        self._tr = QVariantAnimation(self)
        self._tr.setStartValue(0.0)
        self._tr.setEndValue(1.0)
        self._tr.valueChanged.connect(self._set_t)
        self._shimmer = QVariantAnimation(self)
        self._shimmer.setStartValue(0.0)
        self._shimmer.setEndValue(1.0)
        self._shimmer.setDuration(1300)
        self._shimmer.setLoopCount(-1)
        self._shimmer.valueChanged.connect(self._set_shim)
        self._hide_t = QTimer(self)
        self._hide_t.setSingleShot(True)
        self._hide_t.timeout.connect(self._really_hide)
        self._watch = QTimer(self)
        self._watch.setInterval(200)
        self._watch.timeout.connect(self._check)

    @staticmethod
    def _theme():
        m = UI["mode"]
        if m == "mac":
            return {"mode": "mac", "rad": rr(20), "trad": rr(13), "center": True, "slide": 18, "zoom": 0.10,
                    "move_ms": 400, "tr_ms": 480, "fade_in": 240, "fade_out": 200, "shadow": (22, 85, 6),
                    "move_curve": mac_curve(True, 1.12), "tr_curve": mac_curve(),
                    "title": QColor(247, 249, 252), "sub": QColor(170, 179, 195), "title_w": QFont.Weight.Medium}
        if m == "windows":
            return {"mode": "windows", "rad": max(2.0, min(8.0, rr(8))), "trad": max(2.0, min(4.0, rr(4))), "center": False,
                    "slide": 8, "zoom": 0.025, "move_ms": 167, "tr_ms": 210, "fade_in": 120, "fade_out": 90,
                    "shadow": (14, 70, 3), "move_curve": QEasingCurve(QEasingCurve.Type.OutQuad),
                    "tr_curve": QEasingCurve(QEasingCurve.Type.OutQuad),
                    "title": QColor(255, 255, 255), "sub": QColor(157, 157, 157), "title_w": QFont.Weight.DemiBold}
        return {"mode": "default", "rad": rr(12), "trad": rr(8), "center": False, "slide": 13, "zoom": 0.07,
                "move_ms": 220, "tr_ms": 340, "fade_in": 160, "fade_out": 130, "shadow": (18, 80, 4),
                "move_curve": QEasingCurve(QEasingCurve.Type.OutCubic), "tr_curve": QEasingCurve(QEasingCurve.Type.OutCubic),
                "title": QColor(232, 236, 243), "sub": QColor(138, 149, 166), "title_w": QFont.Weight.DemiBold}

    def _set_t(self, v):
        self._t = float(v)
        self.update()

    def _set_shim(self, v):
        self._shim = float(v)
        self.update()

    def _fade_to(self, v, ms, curve=QEasingCurve.Type.OutCubic):
        self._fade.stop()
        self._fade.setDuration(ms)
        self._fade.setEasingCurve(curve)
        self._fade.setStartValue(self.windowOpacity())
        self._fade.setEndValue(v)
        self._fade.start()

    def _fade_done(self):
        if self._hiding:
            self._hiding = False
            self._shimmer.stop()
            self._move.stop()
            self.hide()

    def _fonts(self):
        base = self.font().pointSizeF()
        base = base if base > 0 else 9.5
        tf, sf = QFont(self.font()), QFont(self.font())
        tf.setPointSizeF(base)
        tf.setWeight(self.th["title_w"])
        sf.setPointSizeF(max(7.0, base - 1.0))
        return tf, sf

    @staticmethod
    def _wrap(text, fm, w, n=2):
        lines, cur = [], ""
        for word in text.split():
            trial = (cur + " " + word).strip()
            if fm.horizontalAdvance(trial) <= w:
                cur = trial
                continue
            if cur:
                lines.append(cur)
            cur = word if fm.horizontalAdvance(word) <= w else fm.elidedText(word, Qt.TextElideMode.ElideRight, w)
        if cur:
            lines.append(cur)
        if len(lines) > n:
            lines = lines[:n]
            lines[-1] = fm.elidedText(lines[-1] + " …", Qt.TextElideMode.ElideRight, w)
        return lines or [""]

    def show_for(self, row, pm, icon_pm, title, sub):
        fresh = not self.isVisible() or self._hiding
        self._hiding = False
        self._hide_t.stop()
        self.th = th = self._theme()
        self._pop = fresh
        self.old_pm = None if fresh else self.pm
        self.src, self.pm, self.icon_pm, self.sub = row, pm, icon_pm, sub
        tf, sf = self._fonts()
        inner = self.W - 2 * self.PAD
        self.lines = self._wrap(title, QFontMetrics(tf), inner)
        ch = self.PAD + self.THUMB_H + 8 + QFontMetrics(tf).height() * len(self.lines) + 2 + QFontMetrics(sf).height() + self.PAD
        self.setFixedSize(self.W + 2 * self.M, ch + 2 * self.M)
        target, away = self._target(row, ch, th["slide"])
        self._move.stop()
        self._move.setDuration(th["move_ms"])
        self._move.setEasingCurve(th["move_curve"])
        if not self.isVisible():
            self.setWindowOpacity(0.0)
            self.move(target + away)
            self.show()
        self._move.setStartValue(self.pos())
        self._move.setEndValue(target)
        self._move.start()
        self._fade_to(1.0, th["fade_in"])
        self._tr.stop()
        self._tr.setDuration(th["tr_ms"])
        self._tr.setEasingCurve(th["tr_curve"])
        self._tr.start()
        if pm is None:
            if self._shimmer.state() != QVariantAnimation.State.Running:
                self._shimmer.start()
        else:
            self._shimmer.stop()
        self._watch.start()
        self.update()

    def _target(self, row, ch, slide):
        """Where the window belongs (the card sits M pixels inside it), and the little offset it slides in from."""
        lst = row._tablist()
        tl = row.mapToGlobal(QPoint(0, 0))
        scr = row.screen().availableGeometry()
        gap, cw = 10, self.W
        if lst is not None and lst.flow() == QListView.Flow.LeftToRight:
            x, y = tl.x() + row.width() // 2 - cw // 2, tl.y() + row.height() + gap
            away = QPoint(0, -slide)
        else:
            x, y = tl.x() + row.width() + gap, tl.y() + row.height() // 2 - ch // 2
            away = QPoint(-slide, 0)
            if x + cw > scr.right():
                x = tl.x() - cw - gap
                away = QPoint(slide, 0)
        x = max(scr.left() + 4, min(x, scr.right() - cw - 4))
        y = max(scr.top() + 4, min(y, scr.bottom() - ch - 4))
        return QPoint(x - self.M, y - self.M), away

    def hide_soon(self):
        self._hide_t.start(90)

    def _really_hide(self):
        self._watch.stop()
        self.src = None
        if not self.isVisible():
            return
        self._hiding = True
        self._fade_to(0.0, self.th["fade_out"], QEasingCurve.Type.InCubic)

    def _check(self):
        r = self.src
        try:
            ok = r is not None and r.isVisible() and r.rect().contains(r.mapFromGlobal(QCursor.pos())) \
                and not QApplication.mouseButtons()
        except RuntimeError:
            ok = False
        if not ok:
            self._really_hide()

    @staticmethod
    def _draw_pm(p, th, pm, opacity, zoom):
        """Paint a snapshot to fill `th` (anchored to the top-left, like a browser's first screen), zoomed about its centre."""
        if opacity <= 0.0:
            return
        tw, thh = pm.width(), pm.height()
        want = th.width() / th.height()
        sw, sh = (tw, tw / want) if tw / max(1, thh) < want else (thh * want, thh)
        sw, sh = min(tw, sw), min(thh, sh)
        zw, zh = sw / zoom, sh / zoom
        src = QRectF((sw - zw) / 2.0, (sh - zh) / 2.0, zw, zh)
        p.setOpacity(max(0.0, min(1.0, opacity)))
        p.drawPixmap(th, pm, src)
        p.setOpacity(1.0)

    def _paint_shadow(self, p, card, rad):
        blur, alpha, dy = self.th["shadow"]
        n = max(4, blur // 2)
        p.setPen(Qt.PenStyle.NoPen)
        for i in range(n):
            grow = blur * (i + 1) / n
            c = QColor(0, 0, 0, max(1, int(alpha / n * 0.9)))
            p.setBrush(c)
            r = card.adjusted(-grow, -grow + dy, grow, grow + dy)
            p.drawRoundedRect(r, rad + grow, rad + grow)

    def paintEvent(self, e):
        T, mode, t = self.th, self.th["mode"], self._t
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        M, PAD = self.M, self.PAD
        card = QRectF(M, M, self.W, self.height() - 2 * M)
        if mode == "mac" and self._pop:
            s = 0.92 + 0.08 * max(0.0, min(1.0, t))
            c = card.center()
            p.translate(c)
            p.scale(s, s)
            p.translate(-c)
        rad = T["rad"]
        self._paint_shadow(p, card, rad)
        body = card.adjusted(0.5, 0.5, -0.5, -0.5)
        cpath = QPainterPath()
        cpath.addRoundedRect(body, rad, rad)
        if mode == "mac":
            p.fillPath(cpath, QColor(24, 28, 38, 206))
            wash = QLinearGradient(body.topLeft(), body.bottomLeft())
            wash.setColorAt(0.0, glass_rgba(40))
            wash.setColorAt(0.45, glass_rgba(10))
            wash.setColorAt(1.0, glass_rgba(4))
            p.fillPath(cpath, QBrush(wash))
            edge = QLinearGradient(body.topLeft(), body.bottomLeft())
            edge.setColorAt(0.0, QColor(255, 255, 255, 105))
            edge.setColorAt(1.0, QColor(255, 255, 255, 26))
            p.setPen(QPen(QBrush(edge), 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(cpath)
        elif mode == "windows":
            p.fillPath(cpath, QColor(44, 44, 44, 252))
            p.setPen(QPen(QColor(255, 255, 255, 24), 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(cpath)
        else:
            p.fillPath(cpath, QColor(22, 26, 34, 246))
            p.setPen(QPen(accent_color(70), 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(cpath)

        th = QRectF(card.left() + PAD, card.top() + PAD, self.W - 2 * PAD, self.THUMB_H)
        tr = max(2.0, T["trad"])
        clip = QPainterPath()
        clip.addRoundedRect(th, tr, tr)
        p.save()
        p.setClipPath(clip)
        p.fillRect(th, {"mac": QColor(0, 0, 0, 80), "windows": QColor(30, 30, 30)}.get(mode, QColor(12, 15, 21)))
        zoom_in = 1.0 + T["zoom"] * (1.0 - t)
        if self.pm is not None and not self.pm.isNull():
            if self.old_pm is not None and not self.old_pm.isNull():
                self._draw_pm(p, th, self.old_pm, 1.0 - t, 1.0)
            self._draw_pm(p, th, self.pm, t if self.old_pm is not None else min(1.0, t * 1.6), zoom_in)
        else:
            sweep = -th.width() * 0.6 + self._shim * th.width() * 2.2
            g = QLinearGradient(th.left() + sweep, th.top(), th.left() + sweep + th.width() * 0.6, th.bottom())
            g.setColorAt(0.0, QColor(255, 255, 255, 0))
            g.setColorAt(0.5, QColor(255, 255, 255, 20))
            g.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.fillRect(th, QBrush(g))
            if self.icon_pm is not None and not self.icon_pm.isNull():
                size = int(40 * (0.85 + 0.15 * min(1.0, t)))
                ic = self.icon_pm.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
                p.setOpacity(max(0.0, min(1.0, t * 1.5)))
                p.drawPixmap(int(th.center().x() - ic.width() / 2), int(th.center().y() - ic.height() / 2), ic)
                p.setOpacity(1.0)
        p.restore()
        p.setPen(QPen(QColor(255, 255, 255, {"mac": 34, "windows": 20}.get(mode, 16)), 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(th.adjusted(0.5, 0.5, -0.5, -0.5), tr, tr)

        tf, sf = self._fonts()
        align = Qt.AlignmentFlag.AlignHCenter if T["center"] else Qt.AlignmentFlag.AlignLeft
        flags = int(align | Qt.AlignmentFlag.AlignVCenter)
        tw = self.W - 2 * PAD
        p.setOpacity(max(0.0, min(1.0, t * 1.4)))
        y = th.bottom() + 8 + 5.0 * (1.0 - min(1.0, t))
        p.setFont(tf)
        p.setPen(T["title"])
        lh = QFontMetrics(tf).height()
        for ln in self.lines:
            p.drawText(QRectF(card.left() + PAD, y, tw, lh), flags, ln)
            y += lh
        p.setFont(sf)
        p.setPen(T["sub"])
        sm = QFontMetrics(sf)
        p.drawText(QRectF(card.left() + PAD, y + 2, tw, sm.height()), flags, sm.elidedText(self.sub, Qt.TextElideMode.ElideRight, tw))
        p.end()


class AudioBadge(QWidget):
    """The tab's sound control. A slim hand-drawn speaker: click it to mute or unmute the tab. Rest the pointer on it and a small
    volume slider slides out beside it (drag it, or use the mouse wheel); it tucks back in a moment after the pointer leaves.
    When a tab starts making sound the speaker blooms in (grows from small, fades up, and sends out a soft ring) while the tab
    title eases aside for it. Animations are made only while they run and dropped afterwards, so an idle badge holds almost nothing."""
    toggled = pyqtSignal()
    volume_changed = pyqtSignal(float)
    ICON_W, GAP, TRACK_W, PAD = 16, 6, 44, 4

    def __init__(self):
        super().__init__()
        self.muted, self.level = False, 1.0
        self._ext, self._hi, self._app = 0.0, 0.0, 1.0
        self._press = None
        self._anims = {}
        self._out = None
        self.setFixedSize(self.ICON_W, 16)
        self.setMouseTracking(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    @property
    def active(self):
        """True while the slider is out or being used, so the tab row doesn't hide the badge from under the pointer."""
        return self._ext > 0.01 or self._press is not None or self.underMouse()

    def set_state(self, muted, level):
        muted, level = bool(muted), max(0.0, min(1.0, float(level)))
        if muted != self.muted or abs(level - self.level) > 0.001:
            self.muted, self.level = muted, level
            self.update()

    def _shown_level(self):
        return 0.0 if self.muted else self.level

    def _tween(self, key, start, end, ms, curve, slot):
        old = self._anims.pop(key, None)
        if old is not None:
            old.stop()
            old.deleteLater()
        a = QVariantAnimation(self)
        a.setDuration(ms)
        a.setEasingCurve(curve)
        a.setStartValue(float(start))
        a.setEndValue(float(end))
        a.valueChanged.connect(slot)
        a.finished.connect(lambda k=key, an=a: self._tween_done(k, an))
        self._anims[key] = a
        a.start()

    def _tween_done(self, key, anim):
        if self._anims.get(key) is anim:
            del self._anims[key]
        anim.deleteLater()

    def _stop_anims(self):
        for a in list(self._anims.values()):
            a.stop()
            a.deleteLater()
        self._anims.clear()

    def _apply_width(self):
        w = self.ICON_W * min(1.0, self._app * 1.25) + self._ext * (self.GAP + self.TRACK_W + self.PAD)
        self.setFixedWidth(max(1, int(round(w))))

    def _set_ext(self, v):
        self._ext = float(v)
        self._apply_width()
        self.update()

    def _set_app(self, v):
        self._app = float(v)
        self._apply_width()
        self.update()

    def _set_hi(self, v):
        self._hi = float(v)
        self.update()

    def appear(self):
        """Called by the tab row right after it shows the badge because sound started."""
        self._app = 0.0
        self._apply_width()
        self._tween("app", 0.0, 1.0, 420, QEasingCurve.Type.OutBack, self._set_app)

    def _hi_to(self, target):
        self._tween("hi", self._hi, target, 150, QEasingCurve.Type.OutCubic, self._set_hi)

    def _out_stop(self):
        if self._out is not None:
            self._out.stop()

    def _out_start(self):
        if self._out is None:
            self._out = QTimer(self)
            self._out.setSingleShot(True)
            self._out.setInterval(380)
            self._out.timeout.connect(self._collapse)
        self._out.start()

    def _expand(self):
        self._out_stop()
        if self._ext < 0.999:
            self._tween("ext", self._ext, 1.0, 260, QEasingCurve.Type.OutCubic, self._set_ext)

    def _collapse(self):
        if self._press is None and not self.underMouse() and self._ext > 0.0:
            self._tween("ext", self._ext, 0.0, 220, QEasingCurve.Type.InOutCubic, self._set_ext)

    def hideEvent(self, e):
        self._stop_anims()
        self._out_stop()
        self._ext, self._app, self._hi, self._press = 0.0, 1.0, 0.0, None
        self.setFixedWidth(self.ICON_W)
        super().hideEvent(e)

    def enterEvent(self, e):
        self._expand()
        self._hi_to(1.0)
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._hi_to(0.0)
        if self._press is None:
            self._out_start()
        super().leaveEvent(e)

    def _track_x0(self):
        return self.ICON_W + self.GAP

    def _value_at(self, x):
        return max(0.0, min(1.0, (x - self._track_x0()) / float(self.TRACK_W)))

    def _set_level_user(self, v):
        self.level = max(0.0, min(1.0, v))
        self.update()
        self.volume_changed.emit(self.level)

    def mousePressEvent(self, e):
        if e.button() != Qt.MouseButton.LeftButton:
            e.ignore()
            return
        x = e.position().x()
        if x >= self.ICON_W + 2 and self._ext > 0.5:
            self._press = "vol"
            self._out_stop()
            self._set_level_user(self._value_at(x))
        else:
            self._press = "icon"
        self.update()

    def mouseMoveEvent(self, e):
        if self._press == "vol":
            self._set_level_user(self._value_at(e.position().x()))

    def mouseReleaseEvent(self, e):
        if e.button() != Qt.MouseButton.LeftButton or self._press is None:
            e.ignore()
            return
        kind, self._press = self._press, None
        if kind == "icon" and e.position().x() < self.ICON_W + 3 and 0 <= e.position().y() <= self.height():
            self.toggled.emit()
        if not self.underMouse():
            self._out_start()
        self.update()

    def wheelEvent(self, e):
        dy = e.angleDelta().y()
        if not dy:
            e.ignore()
            return
        step = 0.05 * max(1, abs(dy) // 120)
        self._expand()
        self._set_level_user(self._shown_level() + (step if dy > 0 else -step))
        e.accept()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        lvl = self._shown_level()
        app = self._app
        col = QColor(142, 163, 180, 175) if self.muted else accent_color(240)
        if self._hi > 0.01:
            col = QColor(int(col.red() + (255 - col.red()) * 0.35 * self._hi), int(col.green() + (255 - col.green()) * 0.35 * self._hi),
                         int(col.blue() + (255 - col.blue()) * 0.35 * self._hi), int(col.alpha() + (255 - col.alpha()) * self._hi))
        if app < 0.999 or app > 1.001:
            p.setOpacity(max(0.0, min(1.0, app * 1.8)))
            sc = 0.45 + 0.55 * app
            p.translate(self.ICON_W / 2.0, 8.0)
            p.scale(sc, sc)
            p.translate(-self.ICON_W / 2.0, -8.0)
        p.setPen(QPen(col, 1.2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.setBrush(col)
        body = QPainterPath()
        body.moveTo(2.6, 6.3)
        body.lineTo(4.9, 6.3)
        body.lineTo(7.9, 3.7)
        body.lineTo(7.9, 12.3)
        body.lineTo(4.9, 9.7)
        body.lineTo(2.6, 9.7)
        body.closeSubpath()
        p.drawPath(body)
        p.setBrush(Qt.BrushStyle.NoBrush)
        pen = QPen(col, 1.2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        if self.muted or lvl <= 0.001:
            p.drawLine(QPointF(10.6, 6.2), QPointF(13.6, 9.8))
            p.drawLine(QPointF(13.6, 6.2), QPointF(10.6, 9.8))
        else:
            p.drawArc(QRectF(4.9, 4.9, 6.2, 6.2), -42 * 16, 84 * 16)
            if lvl > 0.4:
                soft = QColor(col)
                soft.setAlpha(int(col.alpha() * 0.55))
                pen.setColor(soft)
                p.setPen(pen)
                p.drawArc(QRectF(2.3, 2.3, 11.4, 11.4), -42 * 16, 84 * 16)
        if app < 0.999:
            q = max(0.0, min(1.0, app))
            ring = QColor(col)
            ring.setAlpha(int(150 * (1.0 - q)))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(ring, 1.1))
            rr_ = 2.5 + 5.0 * q
            p.drawEllipse(QPointF(self.ICON_W / 2.0, 8.0), rr_, rr_)
        if self._ext > 0.01:
            a = self._ext
            x0, cy = float(self._track_x0()), self.height() / 2.0
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(255, 255, 255, int(52 * a)))
            p.drawRoundedRect(QRectF(x0, cy - 1.5, self.TRACK_W, 3), 1.5, 1.5)
            fx = x0 + self.TRACK_W * lvl
            if lvl > 0.001:
                fill = QColor(col)
                fill.setAlpha(int(255 * a))
                p.setBrush(fill)
                p.drawRoundedRect(QRectF(x0, cy - 1.5, max(3.0, fx - x0), 3), 1.5, 1.5)
            r = 3.3 + (0.9 if self._press == "vol" else 0.0)
            p.setBrush(QColor(255, 255, 255, int(245 * a)))
            p.drawEllipse(QPointF(fx, cy), r, r)
        p.end()


class TabRow(QWidget):
    def __init__(self, tab, on_close):
        super().__init__()
        self.tab = tab
        self._pv_timer = QTimer(self)
        self._pv_timer.setSingleShot(True)
        self._pv_timer.timeout.connect(self._show_preview)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(10, 0, 6, 0)
        lay.setSpacing(6)
        self.icon = QLabel()
        self.icon.setFixedSize(16, 16)
        self.title = QLabel("New Tab")
        self.title.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.audio = AudioBadge()
        self.audio.hide()
        self.audio.toggled.connect(self._audio_toggle)
        self.audio.volume_changed.connect(self._audio_volume)
        self.split_mark = QLabel("⧉")
        self.split_mark.hide()
        self.split_on = False
        self.group_color = None
        self.drop = False
        self.hdr_chip, self.hdr_extra, self.hdr_horiz, self.grouped = None, 0, False, False
        self.icon_pm, self.sleeping = None, False
        self.mem_mb, self.show_mem = None, True
        for w in (self.icon, self.title, self.split_mark):
            w.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        close = FadeButton(8)
        close.setObjectName("close")
        close.setText("✕")
        close.clicked.connect(lambda: on_close(tab))
        self.xbtn = FadeButton(7)
        self.xbtn.setParent(self)
        self.xbtn.setObjectName("miniclose")
        self.xbtn.setText("✕")
        self.xbtn.setFixedSize(14, 14)
        self.xbtn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.xbtn.clicked.connect(lambda: on_close(tab))
        self.xbtn.hide()
        self.lay = lay
        self.close_btn = close
        self.compact = False
        self.side_compact = False
        self.squeeze = False
        self.tight = False
        self.padl, self.padr = QWidget(), QWidget()
        for pw in (self.padl, self.padr):
            pw.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
            pw.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
            pw.hide()
        for w, s in ((self.padl, 1), (self.icon, 0), (self.title, 1), (self.split_mark, 0), (self.audio, 0), (self.padr, 1), (close, 0)):
            lay.addWidget(w, s)

    def set_compact(self, c):
        self.side_compact = c
        self._check_width(True)

    def _check_width(self, force=False):
        """Horizontal tabs shrink as more are opened: below a width the title goes (icon only), and a little before
        that the close button turns into a hover badge. In the sidebar neither applies."""
        lst = self._tablist()
        horiz = lst is not None and lst.flow() == QListView.Flow.LeftToRight
        sq = tg = False
        if horiz and not self.side_compact:
            w = self.width() - (self.hdr_extra if (self.hdr_chip is not None and self.hdr_horiz) else 0)
            sq = w < HTAB_ICON_W
            tg = not sq and w < HTAB_TIGHT_W
        if force or (sq, tg) != (self.squeeze, self.tight):
            self.squeeze, self.tight = sq, tg
            self._refresh_mode()

    def _refresh_mode(self):
        c = self.side_compact or self.squeeze
        self.compact = c
        self.split_mark.setVisible(self.split_on and not c)
        self.title.setVisible(not c)
        self.close_btn.setVisible(not c and not self.tight)
        for w in (self.padl, self.padr):
            w.setVisible(c)
        if c:
            self.audio.hide()
        else:
            try:
                self.update_audio(self.tab)
            except RuntimeError:
                pass
        self._refresh_mem()
        self._apply_margins()
        if not (c or self.tight):
            self.xbtn.hide()
        self._place_xbtn()

    def _place_xbtn(self):
        y = (self.height() - self.xbtn.height()) // 2 if (self.tight and not self.compact) else 2
        self.xbtn.move(self.width() - 16, max(0, y))

    def _apply_margins(self):
        l, t, r, b = (0, 0, 0, 0) if self.compact else ((14, 0, 10, 0) if self.grouped else (10, 0, 6, 0))
        if self.tight and not self.compact:
            r = 3
        if self.hdr_chip is not None:
            if self.hdr_horiz:
                l += self.hdr_extra
            else:
                t += self.hdr_extra
        self.lay.setContentsMargins(l, t, r, b)

    def set_grouped(self, on):
        if on != self.grouped:
            self.grouped = on
            self._apply_margins()

    def set_header(self, chip, extra=0, horiz=False):
        """Make this row the carrier of an island header (or pass None to release it)."""
        old = self.hdr_chip
        if old is not None and old is not chip:
            try:
                if old.parent() is self:
                    old.hide()
                    old.setParent(None)
            except RuntimeError:
                pass
        self.hdr_chip, self.hdr_extra, self.hdr_horiz = chip, (extra if chip is not None else 0), horiz
        self._check_width()
        self._apply_margins()
        if chip is not None:
            chip.setParent(self)
            self._place_header()
            chip.show()
            chip.raise_()
        self.update()

    def _place_header(self):
        if self.hdr_chip is None:
            return
        if self.hdr_horiz:
            self.hdr_chip.setGeometry(0, 0, self.hdr_extra, self.height())
        else:
            self.hdr_chip.setGeometry(0, 0, self.width(), self.hdr_extra)

    def set_group(self, color):
        self.group_color = color
        self.update()

    def set_split(self, on):
        self.split_on = on
        self.split_mark.setVisible(on and not self.compact)

    def set_drop(self, on):
        self.drop = on
        self.update()

    def set_mem(self, mb, show):
        """mb: this tab's renderer memory (None = unknown/sleeping); show: whether the RAM feature is on."""
        key = (None if mb is None else int(round(mb)), bool(show))
        if key == getattr(self, "_mem_key", None):
            return
        self._mem_key = key
        self.mem_mb, self.show_mem = mb, show
        self._refresh_mem()
        self.update()

    def _refresh_mem(self):
        on = self.show_mem and self.mem_mb is not None
        self.setToolTip((self.toolTip().split("\n")[0] + ("\n" + fmt_mem(self.mem_mb) + " RAM" if on else "")))

    def paintEvent(self, e):
        if self.show_mem and self.mem_mb is not None:
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            ox = self.hdr_extra if (self.hdr_chip is not None and self.hdr_horiz) else 0
            oy = self.hdr_extra if (self.hdr_chip is not None and not self.hdr_horiz) else 0
            self._paint_ram_ring(p, ox, oy)
            p.end()
        if not self.drop:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        ox = self.hdr_extra if (self.hdr_chip is not None and self.hdr_horiz) else 0
        oy = self.hdr_extra if (self.hdr_chip is not None and not self.hdr_horiz) else 0
        p.setPen(QPen(accent_color(255), 2))
        p.setBrush(accent_color(50))
        rc = QRectF(2 + ox, 2 + oy, self.width() - 4 - ox, self.height() - 4 - oy)
        rad = self._rad(rc)
        p.drawRoundedRect(rc, rad, rad)
        p.end()

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._check_width()
        self._place_xbtn()
        self._place_header()

    def _tablist(self):
        v = self.parentWidget()
        lst = v.parentWidget() if v is not None else None
        return lst if isinstance(lst, TabList) else None

    def _paint_ram_ring(self, p, ox, oy):
        """The RAM heat outline, drawn to suit the interface style: a plain outline in Default (open at the bottom on
        horizontal tabs, like the tab shape), a thinner outline over a faint tint of the same colour in macOS, and a
        fine flat outline in Windows that keeps clear of the accent marker under the current tab."""
        mode = UI["mode"]
        lst = self._tablist()
        horiz = lst is not None and lst.flow() == QListView.Flow.LeftToRight
        inset = 3.0 if mode == "windows" else 2.0
        rc = QRectF(inset + ox, inset + oy, self.width() - 2 * inset - ox, self.height() - 2 * inset - oy)
        if mode == "windows" and horiz:
            rc.setBottom(rc.bottom() - 3.0)
        rad = self._rad(rc)
        p.setBrush(Qt.BrushStyle.NoBrush)
        if mode == "mac":
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(heat_color(self.mem_mb, 24))
            p.drawRoundedRect(rc, rad, rad)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(heat_color(self.mem_mb, 195), 1.5))
            p.drawRoundedRect(rc, rad, rad)
        elif mode == "windows":
            p.setPen(QPen(heat_color(self.mem_mb, 235), 1.5))
            p.drawRoundedRect(rc, rad, rad)
        elif horiz:
            r = min(rr(9), rc.width() / 2.0, rc.height() / 2.0)
            path = QPainterPath()
            path.moveTo(rc.left(), rc.bottom())
            path.lineTo(rc.left(), rc.top() + r)
            path.arcTo(QRectF(rc.left(), rc.top(), 2 * r, 2 * r), 180, -90)
            path.lineTo(rc.right() - r, rc.top())
            path.arcTo(QRectF(rc.right() - 2 * r, rc.top(), 2 * r, 2 * r), 90, -90)
            path.lineTo(rc.right(), rc.bottom())
            p.setPen(QPen(heat_color(self.mem_mb, 220), 2.0))
            p.drawPath(path)
        else:
            p.setPen(QPen(heat_color(self.mem_mb, 220), 2.0))
            p.drawRoundedRect(rc, rad, rad)

    def _rad(self, rect):
        """Corner radius of the ring/drop outline: a full capsule in horizontal macOS style, otherwise a soft 12."""
        lst = self._tablist()
        if UI["mode"] == "mac" and lst is not None and lst.flow() == QListView.Flow.LeftToRight:
            return rect.height() / 2.0
        if UI["mode"] == "windows":
            return min(rr(5), rect.height() / 2.0)
        return rr(12)

    def _preview_on(self):
        br = getattr(self.tab, "browser", None)
        return br is not None and bool(br.settings.get("tab_preview", True))

    def _show_preview(self):
        """The pointer has rested on this tab: float a thumbnail + title card next to it."""
        t = self.tab
        if not self._preview_on() or t.closing or not self.isVisible() or QApplication.mouseButtons():
            return
        pos = self.mapFromGlobal(QCursor.pos())
        if not self.rect().contains(pos):
            return
        if self.hdr_chip is not None and self.hdr_extra and ((pos.x() < self.hdr_extra) if self.hdr_horiz else (pos.y() < self.hdr_extra)):
            return
        br = t.browser
        if br.cur() is t:
            t.snap()
        title = (t.title() or self.title.text() or "New Tab").strip()
        u = t.pending if t.pending is not None else t.url()
        host = br.host_of(u) if u.scheme() in ("http", "https") else ""
        sub = host or ("This page" if u.scheme() else "New tab")
        if self.sleeping:
            sub += "  ·  asleep"
        elif self.show_mem and self.mem_mb is not None:
            sub += "  ·  " + fmt_mem(self.mem_mb) + " RAM"
        TabPreview.shared().show_for(self, t.thumb, self.icon_pm, title, sub)

    def event(self, e):
        if e.type() == QEvent.Type.ToolTip and self._preview_on():
            return True
        return super().event(e)

    def enterEvent(self, e):
        if self.compact or self.tight:
            self.xbtn.show()
            self.xbtn.raise_()
        lst = self._tablist()
        if lst is not None:
            lst.hover_row(self)
        if self._preview_on():
            self._pv_timer.start(60 if TabPreview.shared().isVisible() else 450)
        super().enterEvent(e)

    def leaveEvent(self, e):
        if not self.rect().contains(self.mapFromGlobal(QCursor.pos())):
            self.xbtn.hide()
        lst = self._tablist()
        if lst is not None:
            lst.hover_row(None)
        self._pv_timer.stop()
        if TabPreview.shared().src is self:
            TabPreview.shared().hide_soon()
        super().leaveEvent(e)

    def set_icon(self, icon):
        self.icon_pm = icon.pixmap(16, 16)
        self._show_icon()

    def set_sleeping(self, on):
        """A sleeping (frozen/discarded) tab shows a greyed-out icon."""
        if on != self.sleeping:
            self.sleeping = on
            self._show_icon()

    def _show_icon(self):
        pm = self.icon_pm
        if pm is None or pm.isNull():
            self.icon.setPixmap(QPixmap())
            return
        if self.sleeping:
            img = pm.toImage().convertToFormat(QImage.Format.Format_ARGB32)
            for y in range(img.height()):
                for x in range(img.width()):
                    c = img.pixelColor(x, y)
                    g = int(0.299 * c.red() + 0.587 * c.green() + 0.114 * c.blue())
                    img.setPixelColor(x, y, QColor(g, g, g, int(c.alpha() * 0.6)))
            pm = QPixmap.fromImage(img)
            pm.setDevicePixelRatio(self.icon_pm.devicePixelRatio())
        self.icon.setPixmap(pm)

    def update_audio(self, tab):
        p = tab.page()
        muted = p.isAudioMuted()
        self.audio.set_state(muted, getattr(tab, "volume", 1.0))
        self.audio.setToolTip("Unmute tab" if muted else "Mute tab")
        vis = (muted or p.recentlyAudible() or self.audio.active) and not self.compact
        if vis and not self.audio.isVisibleTo(self):
            self.audio.setVisible(True)
            self.audio.appear()
        else:
            self.audio.setVisible(vis)

    def _sync_player(self):
        """Keep the sidebar player's mute button in step when the tab's own badge changes things."""
        try:
            pl = getattr(getattr(self.tab, "browser", None), "player", None)
            if pl is not None and pl.tab is self.tab:
                pl.mute_btn.set_kind("mute" if self.tab.page().isAudioMuted() else "sound")
        except RuntimeError:
            pass

    def _audio_toggle(self):
        tab = self.tab
        try:
            pg = tab.page()
            now = not pg.isAudioMuted()
            if not now and getattr(tab, "volume", 1.0) < 0.05:
                tab.volume = 0.6
                pg.runJavaScript(volume_js(tab.volume))
            pg.setAudioMuted(now)
        except RuntimeError:
            return
        self.update_audio(tab)
        self._sync_player()

    def _audio_volume(self, v):
        """The slider was moved: set this tab's media volume. Dragging up from muted unmutes; dragging to zero mutes."""
        tab = self.tab
        try:
            pg = tab.page()
            tab.volume = float(v)
            pg.runJavaScript(volume_js(tab.volume))
            if v <= 0.001:
                pg.setAudioMuted(True)
            elif pg.isAudioMuted():
                pg.setAudioMuted(False)
        except RuntimeError:
            return
        self.update_audio(tab)
        self._sync_player()


# ====================================================================================================
# 37  MEDIA PLAYER: SCRIPTS & HELPERS
# ====================================================================================================

SIDE_DEFAULT_W, SIDE_MIN_W, SIDE_MAX_W = 230, 180, 480
COMPACT_DEFAULT_W, COMPACT_MIN_W, COMPACT_MAX_W = 56, 50, 190
VIZ_BARS = 24
VIZ_TICK_MS = 25
VIZ_NEUTRAL = ("#e4edf3", "#9fb3c2")


def clamp_side_w(v):
    try:
        return max(SIDE_MIN_W, min(SIDE_MAX_W, int(v)))
    except (TypeError, ValueError):
        return SIDE_DEFAULT_W


def clamp_compact_w(v):
    try:
        return max(COMPACT_MIN_W, min(COMPACT_MAX_W, int(v)))
    except (TypeError, ValueError):
        return COMPACT_DEFAULT_W


MEDIA_HOOK_JS = """(function(){try{var ms=navigator.mediaSession;if(!ms||ms.__fj)return;
var H=window.__fjH={},orig=ms.setActionHandler.bind(ms);
ms.setActionHandler=function(a,fn){H[a]=fn;return orig(a,fn);};ms.__fj=1;}catch(e){}})();"""

_MEDIA_PICK = ("var els=[].slice.call(document.querySelectorAll('video,audio'));"
               "var m=els.filter(function(e){return !e.paused&&!e.ended})[0]"
               "||els.filter(function(e){return e.currentTime>0&&e.readyState>0})[0]||els[0];")

MEDIA_STATE_JS = "(function(){try{" + _MEDIA_PICK + """
if(!m)return JSON.stringify({none:1});
var md=null,art='';
try{md=navigator.mediaSession&&navigator.mediaSession.metadata;}catch(e){}
if(md&&md.artwork&&md.artwork.length){var best=md.artwork[0],bs=0;
 md.artwork.forEach(function(a){var s=parseInt((a.sizes||'0').split('x')[0])||0;if(s>=bs){bs=s;best=a;}});art=best.src||'';}
var d=m.duration;
return JSON.stringify({paused:m.paused,t:m.currentTime||0,d:isFinite(d)?d:0,
 title:(md&&md.title)||'',artist:(md&&(md.artist||md.album))||'',art:art});
}catch(e){return JSON.stringify({none:1});}})()"""

_PREV_SEL = ".ytp-prev-button,.previous-button,.skipControl__previous,[data-testid=\"control-button-skip-back\"]"
_NEXT_SEL = ".ytp-next-button,.next-button,.skipControl__next,[data-testid=\"control-button-skip-forward\"]"


VIS_JS = ("(function(){try{" + _MEDIA_PICK + """
if(!m||m.tagName!=='VIDEO'||!m.videoWidth||document.fullscreenElement||document.pictureInPictureElement)return 'none';
var r=m.getBoundingClientRect();
if(r.height<90||r.width<120)return 'none';
var vh=window.innerHeight||document.documentElement.clientHeight;
var vis=Math.min(r.bottom,vh)-Math.max(r.top,0);
return Math.max(0,vis)/r.height;
}catch(e){return 'none';}})()""")
PIP_AWAY, PIP_BACK = 0.2, 0.55


def volume_js(v):
    """Set the volume of every video / audio element on the page, and of any that start playing later. Only the main page is
    reached, so media inside embedded frames keeps its own volume."""
    v = max(0.0, min(1.0, float(v)))
    return ("(function(){try{var v=%.3f;window.__fjVol=(v>=0.999)?null:v;"
            "if(!window.__fjVolHook){window.__fjVolHook=1;"
            "document.addEventListener('play',function(e){var t=e.target;"
            "if(window.__fjVol!=null&&t&&t.volume!==undefined){try{t.volume=window.__fjVol;}catch(x){}}},true);}"
            "[].forEach.call(document.querySelectorAll('video,audio'),function(m){try{m.volume=v;}catch(e){}});"
            "}catch(e){}})()") % v


def media_js(action, arg=0.0):
    body = {
        "toggle": "if(m){if(m.paused){m.play();}else{m.pause();}}",
        "pause": "if(m&&!m.paused){m.pause();}",
        "seek": "if(m&&isFinite(m.duration)){m.currentTime=m.duration*%f;}" % arg,
        "next": ("if(h.nexttrack){h.nexttrack({action:'nexttrack'});}"
                 "else if(!clk('%s')&&m&&isFinite(m.duration)){m.currentTime=Math.min(m.duration,m.currentTime+10);}" % _NEXT_SEL),
        "prev": ("if(m&&m.currentTime>=4){m.currentTime=0;}"
                 "else if(h.previoustrack){h.previoustrack({action:'previoustrack'});}"
                 "else{clk('%s');}" % _PREV_SEL),
    }[action]
    return ("(function(){try{" + _MEDIA_PICK + "var h=window.__fjH||{};"
            "function clk(s){var b=document.querySelector(s);if(b){b.click();return true;}return false;}"
            + body + "}catch(e){}})()")


VIZ_JS = ("(function(){try{" + _MEDIA_PICK + """
if(!m)return '[]';
var V=window.__fjV;
if(!V||V.m!==m){
 if(V){try{V.ctx.close();}catch(e){}}
 window.__fjV=null;
 var AC=window.AudioContext||window.webkitAudioContext,cap=m.captureStream||m.mozCaptureStream;
 if(!AC||!cap)return 'null';
 var ctx=new AC({latencyHint:'interactive'}),st=cap.call(m);
 if(!st.getAudioTracks().length){ctx.close();return '[]';}
 var an=ctx.createAnalyser();
 an.fftSize=1024;an.smoothingTimeConstant=0.3;an.minDecibels=-85;an.maxDecibels=-20;
 ctx.createMediaStreamSource(st).connect(an);
 V=window.__fjV={m:m,ctx:ctx,an:an,buf:new Uint8Array(an.frequencyBinCount)};
}
if(V.ctx.state==='suspended')V.ctx.resume();
V.an.getByteFrequencyData(V.buf);
var n=NBANDS,out=[],buf=V.buf,len=buf.length,sr=V.ctx.sampleRate,hz=sr/(2*len),
 lo=60,hi=Math.min(14000,sr*0.42),k=Math.pow(hi/lo,1/n);
for(var i=0;i<n;i++){
 var f0=lo*Math.pow(k,i),f1=f0*k,a=Math.floor(f0/hz),b=Math.ceil(f1/hz),v;
 if(b-a<=1){ /* band narrower than one FFT bin (the bass): interpolate so neighbouring bars differ */
  var c=Math.sqrt(f0*f1)/hz,i0=Math.floor(c),fr=c-i0;
  v=(buf[i0]*(1-fr)+buf[Math.min(len-1,i0+1)]*fr)/255;
 }else{
  var s=0,mx=0;
  for(var j=a;j<b&&j<len;j++){s+=buf[j];if(buf[j]>mx)mx=buf[j];}
  v=(s/(b-a)*0.5+mx*0.5)/255;
 }
 v*=0.85+0.45*i/n; /* offset the natural roll-off of the highs */
 out.push(Math.round(Math.min(1,v)*100)/100);
}
return JSON.stringify(out);
}catch(e){return 'null';}})()""").replace("NBANDS", str(VIZ_BARS))
VIZ_STOP_JS = "(function(){try{var V=window.__fjV;if(V){V.ctx.close();window.__fjV=null;}}catch(e){}})()"


def pip_js(max_w, force=False):
    """One call per tick returns the playback position and play state, plus a fresh JPEG frame only when the video has actually
    moved on (same frame = no re-encode, no transfer, no extra memory). Returns 'none' when the page has no video with picture yet,
    'null' when it won't let us read its frames (cross-origin media), or a small JSON string."""
    return ("(function(){try{" + _MEDIA_PICK + """
if(!m||m.tagName!=='VIDEO'||!m.videoWidth||m.readyState<2)return 'none';
var d=m.duration,o={t:m.currentTime||0,d:isFinite(d)?d:0,p:m.paused};
var P=window.__fjP;
if(!P){P=window.__fjP={c:document.createElement('canvas'),k:-1,mw:0,e:null};P.x=P.c.getContext('2d',{alpha:false});}
if(!FORCE&&P.k===m.currentTime&&P.mw===MAXW&&P.e===m)return JSON.stringify(o);
var w=Math.min(MAXW,m.videoWidth),h=Math.max(1,Math.round(w*m.videoHeight/m.videoWidth));
if(P.c.width!==w||P.c.height!==h){P.c.width=w;P.c.height=h;}
P.x.drawImage(m,0,0,w,h);
o.f=P.c.toDataURL('image/jpeg',0.7);P.k=m.currentTime;P.mw=MAXW;P.e=m;
return JSON.stringify(o);
}catch(e){return 'null';}})()""").replace("MAXW", str(int(max_w))).replace("FORCE", "true" if force else "false")


def rounded_pixmap(pm, size, radius):
    """Centre-crop to a square and round the corners (rendered at 2x so it stays crisp on hi-dpi)."""
    s2 = size * 2
    pm = pm.scaled(s2, s2, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
    out = QPixmap(s2, s2)
    out.fill(Qt.GlobalColor.transparent)
    p = QPainter(out)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    path = QPainterPath()
    path.addRoundedRect(QRectF(0, 0, s2, s2), radius * 2, radius * 2)
    p.setClipPath(path)
    p.drawPixmap((s2 - pm.width()) // 2, (s2 - pm.height()) // 2, pm)
    p.end()
    out.setDevicePixelRatio(2)
    return out


def safe_art_url(url):
    """Artwork URLs come from the page, so only fetch plain https hosts (never IPs / localhost / LAN)."""
    u = QUrl(url)
    host = u.host().lower()
    if u.scheme() != "https" or not host or host == "localhost" or host.endswith((".local", ".internal")):
        return False
    try:
        ipaddress.ip_address(host.strip("[]"))
        return False
    except ValueError:
        return True


def art_palette(pm):
    """A vivid (main, alt) colour pair taken from artwork or an icon; None if the image is basically greyscale."""
    if pm is None or pm.isNull():
        return None
    img = pm.toImage().scaled(48, 48, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
    img = img.convertToFormat(QImage.Format.Format_ARGB32)
    bins = [[0.0, 0.0, 0.0, 0.0] for _ in range(24)]
    total = vivid = 0
    for y in range(img.height()):
        for x in range(img.width()):
            r, g, b, a = img.pixelColor(x, y).getRgb()
            if a < 128:
                continue
            total += 1
            h, sat, val = colorsys.rgb_to_hsv(r / 255.0, g / 255.0, b / 255.0)
            if sat < 0.2 or val < 0.2:
                continue
            vivid += 1
            wgt = sat * val
            bk = bins[int(h * 24) % 24]
            bk[0] += wgt
            bk[1] += r * wgt
            bk[2] += g * wgt
            bk[3] += b * wgt
    if not total or vivid < total * 0.03:
        return None
    best = max(range(24), key=lambda k: bins[k][0] + 0.5 * (bins[(k - 1) % 24][0] + bins[(k + 1) % 24][0]))
    wsum = rs = gs = bs = 0.0
    for j in (-1, 0, 1):
        bk = bins[(best + j) % 24]
        wsum, rs, gs, bs = wsum + bk[0], rs + bk[1], gs + bk[2], bs + bk[3]
    if wsum <= 0:
        return None
    return derive_accent("#%02x%02x%02x" % (int(rs / wsum), int(gs / wsum), int(bs / wsum)))


# ====================================================================================================
# 38  MEDIA PLAYER: WIDGETS, VISUALISER & PICTURE-IN-PICTURE
# ====================================================================================================

class SideGrip(QWidget):
    """Invisible drag handle on the sidebar's right edge. Drag = resize, double-click = reset."""
    def __init__(self, parent, get_w, set_w, done, reset):
        super().__init__(parent)
        self.get_w, self.set_w, self.done, self.reset = get_w, set_w, done, reset
        self.dragging, self._hover = False, False
        self._x0 = self._w0 = 0
        self.setCursor(Qt.CursorShape.SplitHCursor)
        self.hide()

    def enterEvent(self, e):
        self._hover = True
        self.update()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._hover = False
        self.update()
        super().leaveEvent(e)

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            self.dragging = True
            self._x0, self._w0 = e.globalPosition().x(), self.get_w()
            self.update()

    def mouseMoveEvent(self, e):
        if self.dragging:
            self.set_w(int(self._w0 + e.globalPosition().x() - self._x0))

    def mouseReleaseEvent(self, e):
        if self.dragging:
            self.dragging = False
            self.update()
            self.done()

    def mouseDoubleClickEvent(self, e):
        self.reset()

    def paintEvent(self, e):
        if not (self._hover or self.dragging):
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(accent_color(210 if self.dragging else 120))
        p.drawRoundedRect(QRectF(6.5, self.height() / 2 - 20, 3, 40), 1.5, 1.5)
        p.end()


class ClickLabel(QLabel):
    clicked = pyqtSignal()

    def mouseReleaseEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            self.clicked.emit()
        super().mouseReleaseEvent(e)


class ElidedLabel(ClickLabel):
    def __init__(self, text=""):
        super().__init__()
        self._full = ""
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.setText(text)

    def setText(self, t):
        self._full = t or ""
        self._elide()

    def _elide(self):
        super().setText(self.fontMetrics().elidedText(self._full, Qt.TextElideMode.ElideRight, max(10, self.width())))

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._elide()


class MediaButton(FadeButton):
    """Round transport button with a hand-drawn icon (no emoji / font dependence)."""
    def __init__(self, kind, size=28, solid=False):
        super().__init__(size // 2)
        self.kind, self.solid = kind, solid
        self.accent = False
        self.setFixedSize(size, size)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def set_kind(self, k):
        if k != self.kind:
            self.kind = k
            self.update()

    def paintEvent(self, e):
        super().paintEvent(e)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width() / 2, self.height() / 2
        sq = term_on()
        face = QRectF(1, 1, self.width() - 2, self.height() - 2)
        if self.solid:
            p.setPen(Qt.PenStyle.NoPen)
            if self.accent:
                p.setBrush(_mix(QColor(ACCENT["main"]), QColor(ACCENT["alt"]), self._h))
            else:
                p.setBrush(QColor(255, 255, 255, 26))
            if sq:
                p.drawRoundedRect(face, 3, 3)
            else:
                p.drawEllipse(face)
        if self.accent and self.solid:
            col = QColor("#030704" if sq else "#0b141d")
            col.setAlpha(240)
        elif self.accent:
            col = _mix(QColor(ACCENT["main"]), QColor(255, 255, 255), 0.42)
            col.setAlpha(int(190 + 65 * self._h))
        else:
            col = QColor(228, 237, 243, int(185 + 70 * self._h))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(col)
        k = self.kind

        def tri(*pts):
            p.drawPolygon(QPolygonF([QPointF(w + x, h + y) for x, y in pts]))
        if k == "play":
            tri((-4, -6.5), (-4, 6.5), (6, 0))
        elif k == "pause":
            p.drawRoundedRect(QRectF(w - 5, h - 6, 3.6, 12), 1, 1)
            p.drawRoundedRect(QRectF(w + 1.4, h - 6, 3.6, 12), 1, 1)
        elif k == "next":
            tri((-6, -5.5), (-6, 5.5), (3, 0))
            p.drawRoundedRect(QRectF(w + 4, h - 5.5, 2, 11), 1, 1)
        elif k == "prev":
            tri((6, -5.5), (6, 5.5), (-3, 0))
            p.drawRoundedRect(QRectF(w - 6, h - 5.5, 2, 11), 1, 1)
        elif k in ("sound", "mute"):
            tri((-7, -2.5), (-4, -2.5), (0, -6), (0, 6), (-4, 2.5), (-7, 2.5))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(col, 1.4, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            if k == "sound":
                p.drawArc(QRectF(w - 3, h - 4, 8, 8), -50 * 16, 100 * 16)
                p.drawArc(QRectF(w - 6, h - 7, 14, 14), -50 * 16, 100 * 16)
            else:
                p.drawLine(QPointF(w + 3, h - 3), QPointF(w + 8, h + 3))
                p.drawLine(QPointF(w + 8, h - 3), QPointF(w + 3, h + 3))
        p.end()


class SeekBar(QWidget):
    """Thin progress line; click or drag to seek."""
    seek = pyqtSignal(float)

    def __init__(self):
        super().__init__()
        self.setFixedHeight(10)
        self.frac, self.ok, self._drag = 0.0, False, False
        self.color = None
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def set_value(self, f, ok):
        if self._drag:
            return
        self.frac, self.ok = max(0.0, min(1.0, f)), ok
        self.update()

    def set_color(self, hexcol):
        self.color = hexcol
        self.update()

    def _fill(self):
        c = QColor(self.color) if self.color else accent_color(235)
        c.setAlpha(235)
        return c

    def _at(self, e):
        return max(0.0, min(1.0, e.position().x() / max(1, self.width())))

    def mousePressEvent(self, e):
        if self.ok and e.button() == Qt.MouseButton.LeftButton:
            self._drag, self.frac = True, self._at(e)
            self.update()

    def mouseMoveEvent(self, e):
        if self._drag:
            self.frac = self._at(e)
            self.update()

    def mouseReleaseEvent(self, e):
        if self._drag:
            self._drag = False
            self.seek.emit(self._at(e))

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        y, th = self.height() / 2 - 1.5, 3
        p.setBrush(QColor(255, 255, 255, 30))
        p.drawRoundedRect(QRectF(0, y, self.width(), th), 1.5, 1.5)
        if self.ok and self.frac > 0:
            p.setBrush(self._fill())
            p.drawRoundedRect(QRectF(0, y, max(3.0, self.width() * self.frac), th), 1.5, 1.5)
        p.end()


class Visualizer(QWidget):
    """The sidebar player's spectrum: bars, mirrored bars, a wave or a dot matrix. Colours follow the playing track's artwork
    and fade smoothly between tracks. vals always holds VIZ_BARS levels; the Detail setting only changes how many are drawn."""
    def __init__(self, style="bars", dens=2, size=2):
        super().__init__()
        self.vals = [0.0] * VIZ_BARS
        self.pal = None
        self.c1 = [float(x) for x in _rgb(ACCENT["main"])]
        self.c2 = [float(x) for x in _rgb(ACCENT["alt"])]
        self.style, self.n = "bars", VIZ_DENS[2]
        self.set_look(style, dens, size)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)

    def set_look(self, style, dens, size):
        self.style = style if style in dict(VIZ_STYLES) else "bars"
        self.n = VIZ_DENS.get(dens, VIZ_DENS[2])
        self.setFixedHeight(VIZ_HEIGHT.get(size, VIZ_HEIGHT[2]))
        self.update()

    def _target(self):
        return self.pal or (ACCENT["main"], ACCENT["alt"])

    def set_palette(self, pal, snap=False):
        self.pal = pal
        if snap:
            m, a = self._target()
            self.c1, self.c2 = [float(x) for x in _rgb(m)], [float(x) for x in _rgb(a)]
            self.update()

    def step_colors(self, k=0.08):
        m, a = self._target()
        for cur, tgt in ((self.c1, _rgb(m)), (self.c2, _rgb(a))):
            for i in range(3):
                cur[i] += (tgt[i] - cur[i]) * k

    def _levels(self, n=None):
        """vals resampled to the number of bars or dots the Detail setting asks for, each clamped to 0..1."""
        n, src = n or self.n, self.vals
        if n == len(src):
            return [max(0.0, min(1.0, v)) for v in src]
        out = []
        for k in range(n):
            pos = k / max(1, n - 1) * (len(src) - 1)
            i = int(pos)
            j = min(len(src) - 1, i + 1)
            f = pos - i
            out.append(max(0.0, min(1.0, src[i] * (1 - f) + src[j] * f)))
        return out

    def _col(self, t, alpha=255):
        c = QColor(*(int(self.c1[j] + (self.c2[j] - self.c1[j]) * t) for j in range(3)))
        c.setAlpha(max(0, min(255, int(alpha))))
        return c

    def paintEvent(self, e):
        w, h = float(self.width()), float(self.height())
        n = min(self.n, max(6, int(w // 3.5)))
        lv = self._levels(n)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        if self.style == "wave":
            self._paint_wave(p, w, h, lv)
        elif self.style == "dots":
            self._paint_dots(p, w, h, lv)
        else:
            gap = 2.0 if n <= 24 else 1.0
            bw = max(1.0, (w - gap * (n - 1)) / n)
            rad = min(bw / 2, 2.0)
            mirror = self.style == "mirror"
            for i, v in enumerate(lv):
                p.setBrush(self._col(i / max(1, n - 1), 120 + 135 * v))
                x = i * (bw + gap)
                if mirror:
                    bh = max(2.0, v * h)
                    p.drawRoundedRect(QRectF(x, (h - bh) / 2, bw, bh), rad, rad)
                else:
                    bh = max(2.0, v * h)
                    p.drawRoundedRect(QRectF(x, h - bh, bw, bh), rad, rad)
        p.end()

    def _paint_wave(self, p, w, h, lv):
        n = len(lv)
        pad = 1.5
        pts = [QPointF(i / max(1, n - 1) * w, h - pad - max(0.04, v) * (h - 2 * pad)) for i, v in enumerate(lv)]
        path = QPainterPath(pts[0])
        for i in range(1, n - 1):
            mid = QPointF((pts[i].x() + pts[i + 1].x()) / 2, (pts[i].y() + pts[i + 1].y()) / 2)
            path.quadTo(pts[i], mid)
        path.lineTo(pts[-1])
        fill = QPainterPath(path)
        fill.lineTo(w, h)
        fill.lineTo(0, h)
        fill.closeSubpath()
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0.0, self._col(0.5, 110))
        g.setColorAt(1.0, self._col(0.5, 0))
        p.setBrush(QBrush(g))
        p.drawPath(fill)
        lg = QLinearGradient(0, 0, w, 0)
        lg.setColorAt(0.0, self._col(0.0))
        lg.setColorAt(1.0, self._col(1.0))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QBrush(lg), 1.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)

    def _paint_dots(self, p, w, h, lv):
        n = len(lv)
        d = max(2.0, min(4.0, h / 5.0))
        g = d * 0.6
        rows = max(2, int((h + g) // (d + g)))
        cw = w / n
        d = min(d, cw * 0.8)
        top = h - (rows * (d + g) - g)
        for i, v in enumerate(lv):
            lit = int(round(v * rows))
            x = cw * (i + 0.5)
            for r in range(rows):
                y = h - d / 2 - r * (d + g)
                if y - d / 2 < top - 0.01:
                    break
                p.setBrush(self._col(i / max(1, n - 1), 245 - 75 * (r / rows)) if r < lit else QColor(255, 255, 255, 22))
                p.drawEllipse(QPointF(x, y), d / 2, d / 2)


class PipFrame(QWidget):
    """A small floating picture-in-picture window: rounded, soft shadow, always on top. Drag it anywhere (it glides to the nearest
    screen corner when let go, with a little throw), pull the bottom-right corner to resize it, click to pause or play."""
    closed = pyqtSignal()
    toggled = pyqtSignal()
    back = pyqtSignal()
    seek = pyqtSignal(float)
    M = 20

    def __init__(self, width=340):
        super().__init__(None, Qt.WindowType.Tool | Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint
                         | Qt.WindowType.NoDropShadowWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        self.setAttribute(Qt.WidgetAttribute.WA_MacAlwaysShowToolWindow)
        self.setMouseTracking(True)
        self.img = None
        self.aspect = 16 / 9
        self.vw = max(220, min(720, int(width)))
        self.paused, self.frac, self.can_seek = False, 0.0, False
        self._hov, self._hover_anim = 0.0, QVariantAnimation(self)
        self._hover_anim.setDuration(200)
        self._hover_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._hover_anim.valueChanged.connect(self._set_hov)
        self._pop, self._lift, self._flash = 1.0, 0.0, 1.0
        self._flash_paused = False
        self._born = time.monotonic()
        self._seek_t = 0.0
        self._pop_anim, self._lift_anim, self._flash_anim = QVariantAnimation(self), QVariantAnimation(self), QVariantAnimation(self)
        self._pop_anim.valueChanged.connect(self._set_pop)
        self._lift_anim.valueChanged.connect(self._set_lift)
        self._flash_anim.valueChanged.connect(self._set_flash)
        self._flash_anim.setDuration(420)
        self._flash_anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._press = None
        self._moved = 0.0
        self._trail = []
        self._glide = None
        self._closing = False
        self._fit()

    def _fit(self):
        vh = max(100, int(round(self.vw / self.aspect)))
        self.setFixedSize(self.vw + 2 * self.M, vh + 2 * self.M)

    def _vr(self):
        return QRectF(self.M, self.M, self.width() - 2 * self.M, self.height() - 2 * self.M)

    def set_aspect(self, a):
        if a > 0.2 and abs(a - self.aspect) > 0.01:
            self.aspect = a
            self._fit()

    def set_frame(self, img):
        if img is None or img.isNull():
            return
        self.img = img
        self.set_aspect(img.width() / img.height())
        self.update()

    def _set_pop(self, v):
        self._pop = float(v)
        self.update()

    def _set_lift(self, v):
        self._lift = float(v)
        self.update()

    def _set_flash(self, v):
        self._flash = float(v)
        self.update()

    def _ease_to(self, anim, cur, target, ms, curve):
        anim.stop()
        anim.setEasingCurve(curve)
        anim.setDuration(ms)
        anim.setStartValue(float(cur))
        anim.setEndValue(float(target))
        anim.start()

    def _lift_to(self, target):
        self._ease_to(self._lift_anim, self._lift, target, 150 if target else 320, QEasingCurve.Type.OutCubic)

    def set_state(self, paused, frac, can_seek):
        if (self._press is not None and self._press[0] == "seek") or time.monotonic() - self._seek_t < 0.5:
            frac = self.frac
        if paused != self.paused and time.monotonic() - self._born > 0.7:
            self._flash_paused = bool(paused)
            self._flash_anim.stop()
            self._flash_anim.setStartValue(0.0)
            self._flash_anim.setEndValue(1.0)
            self._flash_anim.start()
        if (paused, can_seek) != (self.paused, self.can_seek) or abs(frac - self.frac) > 0.0005:
            self.paused, self.frac, self.can_seek = paused, frac, can_seek
            self.update()

    def _set_hov(self, v):
        self._hov = float(v)
        self.update()

    def _hover_to(self, target):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hov)
        self._hover_anim.setEndValue(float(target))
        self._hover_anim.start()

    def _screen_area(self):
        scr = QApplication.screenAt(self.frameGeometry().center()) or self.screen() or QApplication.primaryScreen()
        return scr.availableGeometry()

    def corner_pos(self, which, area=None):
        """Top-left window position for a corner: 0 top-left, 1 top-right, 2 bottom-left, 3 bottom-right."""
        a = area or self._screen_area()
        gap = 22 - self.M
        x = a.left() + gap if which in (0, 2) else a.right() + 1 - self.width() - gap
        y = a.top() + gap if which in (0, 1) else a.bottom() + 1 - self.height() - gap
        return QPoint(x, y)

    def nearest_corner(self, pt):
        a = self._screen_area()
        cx = 0 if pt.x() < a.center().x() else 1
        cy = 0 if pt.y() < a.center().y() else 2
        return cx + cy

    def _animate(self, prop, start, end, ms, curve, done=None):
        an = QPropertyAnimation(self, prop)
        an.setDuration(ms)
        an.setStartValue(start)
        an.setEndValue(end)
        an.setEasingCurve(curve)
        if done:
            an.finished.connect(done)
        an.start(QPropertyAnimation.DeletionPolicy.DeleteWhenStopped)
        return an

    def open_animated(self):
        """Rises from just below its corner while swelling up from a slightly smaller size, with a tiny overshoot."""
        end = self.corner_pos(3)
        self.move(end + QPoint(0, 26))
        self.setWindowOpacity(0.0)
        self._pop = 0.0
        self.show()
        self._glide = (self._animate(b"pos", end + QPoint(0, 26), end, 480, QEasingCurve.Type.OutQuint),
                       self._animate(b"windowOpacity", 0.0, 1.0, 240, QEasingCurve.Type.OutCubic))
        self._ease_to(self._pop_anim, 0.0, 1.0, 520, QEasingCurve.Type.OutBack)

    def close_animated(self):
        if self._closing:
            return
        self._closing = True
        here = self.pos()

        def done():
            self.hide()
            self.closed.emit()
            self.deleteLater()
        self._glide = (self._animate(b"pos", here, here + QPoint(0, 14), 220, QEasingCurve.Type.InQuad),
                       self._animate(b"windowOpacity", self.windowOpacity(), 0.0, 220, QEasingCurve.Type.InQuad, done))
        self._ease_to(self._pop_anim, self._pop, 0.0, 220, QEasingCurve.Type.InQuad)

    def _snap(self, throw=QPointF(0, 0)):
        """Glide to the corner nearest to where the window will have drifted to, with a small ease-out."""
        proj = self.frameGeometry().center() + QPoint(int(throw.x() * 0.16), int(throw.y() * 0.16))
        end = self.corner_pos(self.nearest_corner(proj))
        if end == self.pos():
            return
        self._glide = self._animate(b"pos", self.pos(), end, 520, QEasingCurve.Type.OutQuint)

    def _hit(self, pt):
        vr = self._vr()
        if not vr.contains(pt):
            return None
        if (pt - QPointF(vr.right() - 22, vr.top() + 22)).manhattanLength() < 22:
            return "close"
        if (pt - QPointF(vr.left() + 22, vr.top() + 22)).manhattanLength() < 22:
            return "back"
        if pt.x() > vr.right() - 26 and pt.y() > vr.bottom() - 26:
            return "size"
        if pt.y() > vr.bottom() - 20 and self.can_seek:
            return "seek"
        return "body"

    def enterEvent(self, e):
        self._hover_to(1)
        super().enterEvent(e)

    def leaveEvent(self, e):
        if self._press is None:
            self._hover_to(0)
        super().leaveEvent(e)

    def mousePressEvent(self, e):
        if e.button() != Qt.MouseButton.LeftButton:
            return
        if self._glide:
            for g in (self._glide if isinstance(self._glide, tuple) else (self._glide,)):
                try:
                    g.stop()
                except RuntimeError:
                    pass
        hit = self._hit(e.position())
        gp = e.globalPosition()
        self._moved = 0.0
        self._trail = [(time.monotonic(), gp)]
        if hit in ("close", "back"):
            self._press = ("btn", hit)
        elif hit == "size":
            self._press = ("size", gp, self.vw)
        elif hit == "seek":
            self._press = ("seek",)
            self._seek_to(e.position())
        else:
            self._press = ("drag", gp - QPointF(self.pos()))
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            self._lift_to(1.0)

    def mouseMoveEvent(self, e):
        gp = e.globalPosition()
        if self._press is None:
            hit = self._hit(e.position())
            self.setCursor(Qt.CursorShape.PointingHandCursor if hit in ("close", "back", "seek")
                           else Qt.CursorShape.SizeFDiagCursor if hit == "size" else Qt.CursorShape.ArrowCursor)
            return
        kind = self._press[0]
        if kind == "drag":
            tl = gp - self._press[1]
            self._moved = max(self._moved, (gp - self._trail[0][1]).manhattanLength())
            self.move(int(tl.x()), int(tl.y()))
            self._trail.append((time.monotonic(), gp))
            self._trail = self._trail[-6:]
        elif kind == "size":
            self._moved = 99
            nw = max(220, min(720, int(self._press[2] + (gp.x() - self._press[1].x()))))
            if nw != self.vw:
                self.vw = nw
                self._fit()
                self.update()
        elif kind == "seek":
            self._seek_to(e.position())

    def mouseReleaseEvent(self, e):
        if e.button() != Qt.MouseButton.LeftButton or self._press is None:
            return
        kind, self._press = self._press[0], None
        hit = self._hit(e.position())
        if kind == "btn":
            if hit == "close":
                self.close_animated()
            elif hit == "back":
                self.back.emit()
        elif kind == "drag":
            self.setCursor(Qt.CursorShape.ArrowCursor)
            self._lift_to(0.0)
            if self._moved < 4:
                self.toggled.emit()
            else:
                v = QPointF(0, 0)
                if len(self._trail) >= 2:
                    (t0, p0), (t1, p1) = self._trail[0], self._trail[-1]
                    dt = t1 - t0
                    if dt > 0.001 and time.monotonic() - t1 < 0.12:
                        v = (p1 - p0) / dt
                self._snap(v)
        elif kind == "size":
            self._snap()
        if not self.underMouse():
            self._hover_to(0)

    def mouseDoubleClickEvent(self, e):
        if self._hit(e.position()) == "body":
            self.back.emit()

    def _seek_to(self, pt):
        vr = self._vr()
        f = max(0.0, min(1.0, (pt.x() - vr.left() - 14) / max(1.0, vr.width() - 28)))
        self.frac, self._seek_t = f, time.monotonic()
        self.update()
        self.seek.emit(f)

    def paintEvent(self, e):
        vr = self._vr()
        R = 14.0
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        sc = (0.88 + 0.12 * self._pop) * (1.0 + 0.022 * self._lift)
        if abs(sc - 1.0) > 0.0005:
            mid = QPointF(self.width() / 2.0, self.height() / 2.0)
            p.translate(mid)
            p.scale(sc, sc)
            p.translate(-mid)
        p.setPen(Qt.PenStyle.NoPen)
        dy = 4 + 4 * self._lift
        for i in range(12):
            p.setBrush(QColor(0, 0, 0, int(7 + 3 * self._lift)))
            p.drawRoundedRect(vr.adjusted(-i, -i + dy, i, i + dy), R + i, R + i)
        clip = QPainterPath()
        clip.addRoundedRect(vr, R, R)
        p.setClipPath(clip)
        p.fillRect(vr, QColor(8, 10, 14))
        if self.img is not None:
            p.drawImage(vr, self.img)
        h = self._hov if not self.paused else max(self._hov, 0.85)
        if h > 0.01:
            top = QLinearGradient(0, vr.top(), 0, vr.top() + 64)
            top.setColorAt(0, QColor(0, 0, 0, int(150 * h)))
            top.setColorAt(1, QColor(0, 0, 0, 0))
            p.fillRect(QRectF(vr.left(), vr.top(), vr.width(), 64), QBrush(top))
            bot = QLinearGradient(0, vr.bottom() - 56, 0, vr.bottom())
            bot.setColorAt(0, QColor(0, 0, 0, 0))
            bot.setColorAt(1, QColor(0, 0, 0, int(170 * h)))
            p.fillRect(QRectF(vr.left(), vr.bottom() - 56, vr.width(), 56), QBrush(bot))
            self._paint_controls(p, vr, h)
        p.setClipping(False)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor(255, 255, 255, 46), 1.0))
        p.drawRoundedRect(vr.adjusted(0.5, 0.5, -0.5, -0.5), R, R)
        if self._flash < 0.999:
            self._paint_flash(p, vr)
        p.end()

    def _paint_flash(self, p, vr):
        """The brief swelling, fading play or pause symbol when the state changes."""
        f = self._flash
        a = (1.0 - f) * (1.0 - f)
        c = vr.center()
        r = 26 + 20 * f
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(20, 24, 30, int(150 * a)))
        p.drawEllipse(c, r, r)
        p.setBrush(QColor(255, 255, 255, int(255 * a)))
        p.save()
        p.translate(c)
        s = 1.0 + 0.3 * f
        p.scale(s, s)
        if self._flash_paused:
            p.drawRoundedRect(QRectF(-8, -9, 5.5, 18), 1.6, 1.6)
            p.drawRoundedRect(QRectF(2.5, -9, 5.5, 18), 1.6, 1.6)
        else:
            p.drawPolygon(QPolygonF([QPointF(-6, -9), QPointF(-6, 9), QPointF(10, 0)]))
        p.restore()

    def _paint_controls(self, p, vr, h):
        a = int(255 * h)
        white = QColor(255, 255, 255, a)
        disc = QColor(20, 24, 30, int(150 * h))
        p.setPen(Qt.PenStyle.NoPen)
        for c in (QPointF(vr.right() - 22, vr.top() + 22), QPointF(vr.left() + 22, vr.top() + 22)):
            p.setBrush(disc)
            p.drawEllipse(c, 13, 13)
        pen = QPen(white, 1.7, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
        p.setPen(pen)
        c = QPointF(vr.right() - 22, vr.top() + 22)
        p.drawLine(c + QPointF(-4, -4), c + QPointF(4, 4))
        p.drawLine(c + QPointF(-4, 4), c + QPointF(4, -4))
        c = QPointF(vr.left() + 22, vr.top() + 22)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(QRectF(c.x() - 5, c.y() - 3, 8, 8), 1.5, 1.5)
        p.drawLine(c + QPointF(-1, 1), c + QPointF(5, -5))
        p.drawLine(c + QPointF(1, -5), c + QPointF(5, -5))
        p.drawLine(c + QPointF(5, -5), c + QPointF(5, -1))
        cc = QPointF(vr.center().x(), vr.center().y() - 6)
        p.save()
        csc = 0.84 + 0.16 * h
        p.translate(cc)
        p.scale(csc, csc)
        p.translate(-cc)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(20, 24, 30, int(165 * h)))
        p.drawEllipse(cc, 23, 23)
        p.setBrush(white)
        if self.paused:
            tri = QPolygonF([cc + QPointF(-6, -9), cc + QPointF(-6, 9), cc + QPointF(10, 0)])
            p.drawPolygon(tri)
        else:
            p.drawRoundedRect(QRectF(cc.x() - 8, cc.y() - 9, 5.5, 18), 1.6, 1.6)
            p.drawRoundedRect(QRectF(cc.x() + 2.5, cc.y() - 9, 5.5, 18), 1.6, 1.6)
        p.restore()
        p.setPen(Qt.PenStyle.NoPen)
        by = vr.bottom() - 11
        x0, x1 = vr.left() + 14, vr.right() - 28
        p.setBrush(QColor(255, 255, 255, int(70 * h)))
        p.drawRoundedRect(QRectF(x0, by - 1.5, x1 - x0, 3), 1.5, 1.5)
        if self.can_seek:
            p.setBrush(accent_color(a))
            p.drawRoundedRect(QRectF(x0, by - 1.5, max(3.0, (x1 - x0) * self.frac), 3), 1.5, 1.5)
        p.setPen(QPen(QColor(255, 255, 255, int(150 * h)), 1.4, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        for k in (5, 10):
            p.drawLine(QPointF(vr.right() - 5, vr.bottom() - k - 1), QPointF(vr.right() - k - 1, vr.bottom() - 5))


class FloatGrip(QWidget):
    """A resize handle for the floating media player. Three of them sit in the card's shadow margin on the sides away from the
    page edge it rests against: one on the free side ("h": wider), one on the free top or bottom ("v": taller) and one on
    the free corner ("hv": both). Double-click any of them to go back to the default size."""
    def __init__(self, owner, mode):
        super().__init__(owner)
        self.o, self.mode = owner, mode
        self.setToolTip("Drag to resize \u00b7 double-click to reset")
        self.setMouseTracking(True)

    def enterEvent(self, e):
        self.update()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self.update()
        super().leaveEvent(e)

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            g = e.globalPosition()
            self.o._grip_press(self.mode, g.x(), g.y())
        e.accept()

    def mouseMoveEvent(self, e):
        if e.buttons() & Qt.MouseButton.LeftButton:
            g = e.globalPosition()
            self.o._grip_move(g.x(), g.y())
        e.accept()

    def mouseReleaseEvent(self, e):
        self.o._grip_release()
        e.accept()

    def mouseDoubleClickEvent(self, e):
        self.o.reset_size()
        e.accept()

    def paintEvent(self, e):
        o = self.o
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            hot = self.underMouse() or (o._rs is not None and o._rs[0] == self.mode)
            c = QColor(ACCENT["main"]) if o._skin() == "term" else QColor(255, 255, 255)
            fr, fb = "l" in o.corner, "t" in o.corner
            sh, ti = o.SH, o.GRIP_IN
            cx = ti if fr else sh
            cy = ti if fb else sh
            ix, iy = (-1 if fr else 1), (-1 if fb else 1)
            if self.mode == "hv":
                c.setAlpha(170 if hot else 75)
                p.setPen(QPen(c, 1.4, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                for k in (4, 8):
                    p.drawLine(QPointF(cx + ix * 3, cy + iy * (3 + k)), QPointF(cx + ix * (3 + k), cy + iy * 3))
            elif hot:
                c.setAlpha(170)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(c)
                if self.mode == "h":
                    p.drawRoundedRect(QRectF(cx + ix * 4 - 1.5, self.height() / 2.0 - 11, 3, 22), 1.5, 1.5)
                else:
                    p.drawRoundedRect(QRectF(self.width() / 2.0 - 11, cy + iy * 4 - 1.5, 22, 3), 1.5, 1.5)
        finally:
            p.end()


class MediaPlayer(QFrame):
    """Zen-style mini player pinned to the bottom of the sidebar. Follows whichever tab last played audio."""
    def __init__(self, browser, parent):
        super().__init__(parent)
        self.b = browser
        self.setObjectName("media")
        self.tab = None
        self.compact = False
        self.floating = False
        self._watching = None
        c = browser.settings.get("player_corner")
        self.corner = c if c in ("tl", "tr", "bl", "br") else "bl"
        self._dp = None
        self._fw = self._clamp_fw(browser.settings.get("player_width"))
        self._fh = self._clamp_fh(browser.settings.get("player_height"))
        self._nat_h = 0
        self._rs = None
        self._art_base = None
        self._dragging, self._samples = False, []
        self._lift, self._lift_anim = 0.0, None
        self._leaving, self._gen = False, 0
        self._goal = None
        self._pal_last = None
        self.paused = True
        self.viz_on = bool(browser.settings.get("visualizer"))
        self._misses = 0
        self._art_key, self._art_cache, self._art_pending = None, {}, set()
        self._real, self._real_ts = [], -999.0
        self._art_pal, self._viz_sent = {}, 0.0
        self.net = QNetworkAccessManager(self)
        self.pip = None
        self._pip_busy = False
        self.pip_timer = QTimer(self)
        self.pip_timer.setInterval(33)
        self.pip_timer.timeout.connect(self._pip_tick)
        self._auto_pip = False
        self._auto_dismissed = False
        self._vis_busy = False
        self.scroll_timer = QTimer(self)
        self.scroll_timer.setInterval(280)
        self.scroll_timer.timeout.connect(self._scroll_tick)

        self.lay = QVBoxLayout(self)
        self.lay.setContentsMargins(10, 10, 10, 8)
        self.lay.setSpacing(6)
        self.top = QHBoxLayout()
        self.top.setSpacing(9)
        self.art = ClickLabel()
        self.art.setFixedSize(36, 36)
        self.art.setCursor(Qt.CursorShape.PointingHandCursor)
        self.art.clicked.connect(self._art_clicked)
        self.textw = QWidget()
        tl = QVBoxLayout(self.textw)
        tl.setContentsMargins(0, 0, 0, 0)
        tl.setSpacing(1)
        self.title, self.sub = ElidedLabel(), ElidedLabel()
        self.title.setObjectName("mediatitle")
        self.sub.setObjectName("mediasub")
        self.title.setCursor(Qt.CursorShape.PointingHandCursor)
        self.title.clicked.connect(self.open_pip)
        self.sub.clicked.connect(self.open_pip)
        tl.addStretch(1)
        tl.addWidget(self.title)
        tl.addWidget(self.sub)
        tl.addStretch(1)
        self.close_btn = FadeButton(8)
        self.close_btn.setObjectName("close")
        self.close_btn.setText("✕")
        self.close_btn.setToolTip("Stop and hide")
        self.close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.close_btn.clicked.connect(self.stop_and_hide)
        self.top.addWidget(self.art)
        self.top.addWidget(self.textw, 1)
        self.top.addWidget(self.close_btn, 0, Qt.AlignmentFlag.AlignTop)
        self.lay.addLayout(self.top)
        self.cplay = MediaButton("play", 30, solid=True)
        self.cplay.clicked.connect(lambda: self.control("toggle"))
        self.cplay.setToolTip("Play / pause")
        self.cplay.hide()
        self.lay.addWidget(self.cplay, 0, Qt.AlignmentFlag.AlignHCenter)

        self.viz = Visualizer(*viz_look(browser.settings))
        self.viz.hide()
        self.lay.addWidget(self.viz)
        self.seekbar = SeekBar()
        self.seekbar.seek.connect(lambda f: self._run(media_js("seek", f)))
        self.lay.addWidget(self.seekbar)

        self.ctl_wrap = QWidget()
        cl = QHBoxLayout(self.ctl_wrap)
        cl.setContentsMargins(0, 0, 0, 0)
        cl.setSpacing(4)
        self.prev_btn, self.play_btn = MediaButton("prev", 28), MediaButton("play", 32, solid=True)
        self.next_btn, self.mute_btn = MediaButton("next", 28), MediaButton("sound", 28)
        self.prev_btn.clicked.connect(lambda: self.control("prev"))
        self.play_btn.clicked.connect(lambda: self.control("toggle"))
        self.next_btn.clicked.connect(lambda: self.control("next"))
        self.mute_btn.clicked.connect(self.toggle_mute)
        cl.addStretch(1)
        for w in (self.prev_btn, self.play_btn, self.next_btn, self.mute_btn):
            cl.addWidget(w)
        cl.addStretch(1)
        self.lay.addWidget(self.ctl_wrap)

        self.grip = FloatGrip(self, "hv")
        self.gripx = FloatGrip(self, "h")
        self.gripy = FloatGrip(self, "v")
        self._grips = (self.gripx, self.gripy, self.grip)
        for g in self._grips:
            g.hide()

        self.poll_timer = QTimer(self)
        self.poll_timer.setInterval(700)
        self.poll_timer.timeout.connect(self.poll)
        self.viz_timer = QTimer(self)
        self.viz_timer.setInterval(VIZ_TICK_MS)
        self.viz_timer.timeout.connect(self._viz_tick)
        self.hide()

    FLOAT_W = 300
    MIN_W = 240
    MAX_W = 560

    @classmethod
    def _clamp_fw(cls, v):
        try:
            v = int(v)
        except (TypeError, ValueError):
            v = cls.FLOAT_W
        return max(cls.MIN_W, min(cls.MAX_W, v))

    def _max_fw(self):
        """Widest the card may be: the cap, or the page area if that is narrower."""
        stack = getattr(self.b, "stack", None)
        room = stack.width() - 2 * self.EDGE if stack is not None and stack.width() > 0 else self.MAX_W
        return max(self.MIN_W, min(self.MAX_W, room))

    def _eff_fw(self):
        return max(self.MIN_W, min(self._fw, self._max_fw()))

    MAX_H = 480
    GRIP_IN = 6

    @classmethod
    def _clamp_fh(cls, v):
        try:
            v = int(v)
        except (TypeError, ValueError):
            return None
        return max(60, min(cls.MAX_H, v)) if v > 0 else None

    def _max_fh(self):
        """Tallest the card may be (not counting its shadow room)."""
        stack = getattr(self.b, "stack", None)
        room = stack.height() - 2 * self.EDGE if stack is not None and stack.height() > 0 else self.MAX_H
        return max(60, min(self.MAX_H, room))

    def _fit(self):
        """Height of the whole widget: its natural height, or the height the person pulled it to. Extra height goes first to
        a bigger picture and then to the gaps between the rows, so a tall card looks deliberate rather than stretched."""
        sh = self.SH
        if self.art.width() != 36:
            self.art.setFixedSize(36, 36)
            self._show_art()
        self.lay.setSpacing(6)
        self.lay.activate()
        h0 = self.lay.sizeHint().height()
        self._nat_h = h0 - 2 * sh
        h = h0
        if self._fh is not None:
            h = max(h0, min(self._max_fh(), self._fh) + 2 * sh)
        e = h - h0
        if e > 0:
            g = min(int(e * 0.6), 40)
            if g:
                self.art.setFixedSize(36 + g, 36 + g)
                self._show_art()
            gaps = max(1, sum(1 for i in range(self.lay.count()) if not self.lay.itemAt(i).isEmpty()) - 1)
            self.lay.setSpacing(6 + max(0, e - g) // gaps)
            self.lay.activate()
        return h

    def _place_grip(self):
        """The handles sit in the shadow margin on the sides away from the page edge the card rests against, so pulling one
        outwards always makes the card bigger. Free side = wider, free top/bottom = taller, free corner = both."""
        if getattr(self, "grip", None) is None:
            return
        W, H, sh, ti = self.width(), self.height(), self.SH, self.GRIP_IN
        L, R, T, B = sh, W - sh, sh, H - sh
        fr, fb = "l" in self.corner, "t" in self.corner
        xz = (R - ti, W - (R - ti)) if fr else (0, L + ti)
        yz = (B - ti, H - (B - ti)) if fb else (0, T + ti)
        self.grip.setGeometry(xz[0], yz[0], xz[1], yz[1])
        ys = (T, max(1, B - ti - T)) if fb else (T + ti, max(1, B - T - ti))
        self.gripx.setGeometry(xz[0], ys[0], xz[1], ys[1])
        xs = (L, max(1, R - ti - L)) if fr else (L + ti, max(1, R - L - ti))
        self.gripy.setGeometry(xs[0], yz[0], xs[1], yz[1])
        self.grip.setCursor(Qt.CursorShape.SizeFDiagCursor if fr == fb else Qt.CursorShape.SizeBDiagCursor)
        self.gripx.setCursor(Qt.CursorShape.SizeHorCursor)
        self.gripy.setCursor(Qt.CursorShape.SizeVerCursor)
        for g in self._grips:
            g.update()
            g.raise_()

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._place_grip()

    def _grip_press(self, mode, gx, gy):
        self._rs = (mode, float(gx), float(gy), self._eff_fw(), self.height() - 2 * self.SH)
        for g in self._grips:
            g.update()

    def _grip_move(self, gx, gy):
        if self._rs is None:
            return
        mode, x0, y0, w0, h0 = self._rs
        changed = False
        if "h" in mode:
            d = float(gx) - x0
            if "r" in self.corner:
                d = -d
            nw = max(self.MIN_W, min(self._max_fw(), int(w0 + d)))
            if nw != self._fw:
                self._fw, changed = nw, True
        if "v" in mode:
            d = float(gy) - y0
            if "b" in self.corner:
                d = -d
            nh = max(60, min(self._max_fh(), int(h0 + d)))
            if nh != self._fh:
                self._fh, changed = nh, True
        if changed:
            self.place()

    def _grip_release(self):
        if self._rs is None:
            return
        self._rs = None
        if self._fh is not None and self._fh <= self._nat_h + 1:
            self._fh = None
            self.place()
        for g in self._grips:
            g.update()
        st = self.b.settings
        st["player_width"] = self._fw
        if self._fh is None:
            st.pop("player_height", None)
        else:
            st["player_height"] = self._fh
        jsave("settings.json", st)

    def reset_size(self):
        self._fw, self._fh, self._rs = self.FLOAT_W, None, None
        self.b.settings.pop("player_width", None)
        self.b.settings.pop("player_height", None)
        jsave("settings.json", self.b.settings)
        self.place(True)

    def _set_art_pm(self, pm):
        self._art_base = pm
        self._show_art()

    def _show_art(self):
        """Shows the artwork at the picture's current size (it is pre-rendered at the normal size, so it is scaled when bigger)."""
        pm = self._art_base
        if pm is None or pm.isNull():
            return
        s = self.art.width()
        if s != 36:
            dpr = pm.devicePixelRatio() or 1.0
            pm = pm.scaled(int(s * dpr), int(s * dpr), Qt.AspectRatioMode.KeepAspectRatio,
                           Qt.TransformationMode.SmoothTransformation)
            pm.setDevicePixelRatio(dpr)
        self.art.setPixmap(pm)

    SH = 10
    EDGE = 14

    @staticmethod
    def _skin():
        return "term" if term_on() else UI["mode"]

    def _margins(self):
        if self.floating:
            m = self.SH
            return (10 + m, 12 + m, 10 + m, 8 + m)
        return (4, 6, 4, 6) if self.compact else (10, 10, 10, 8)

    def set_floating(self, on, parent):
        """Sidebar (vertical tabs): pinned to the bottom of the sidebar. Horizontal tabs have no sidebar, so the player
        becomes a card that floats over the page: drag it and it glides to the nearest corner. It wears the accent colour
        and its own Default / macOS / Windows / Terminal look."""
        on = bool(on)
        if self.parent() is not parent:
            self.setParent(parent)
        self.floating = on
        self._leaving, self._gen = False, self._gen + 1
        self.setGraphicsEffect(None)
        stop_anim(self, b"pos")
        if on:
            self.setFixedWidth(self._eff_fw() + 2 * self.SH)
            for g in self._grips:
                g.show()
            for w in (self.art, self.title, self.sub):
                w.installEventFilter(self)
            stack = getattr(self.b, "stack", None)
            if stack is not None and self._watching is not stack:
                if self._watching is not None:
                    try:
                        self._watching.removeEventFilter(self)
                    except RuntimeError:
                        pass
                stack.installEventFilter(self)
                self._watching = stack
            self.setCursor(Qt.CursorShape.OpenHandCursor)
        else:
            self.setMinimumWidth(0)
            self.setMaximumWidth(16777215)
            for g in self._grips:
                g.hide()
            self.art.setFixedSize(36, 36)
            self.lay.setSpacing(6)
            self._show_art()
            for w in (self.art, self.title, self.sub):
                w.removeEventFilter(self)
            if self._watching is not None:
                try:
                    self._watching.removeEventFilter(self)
                except RuntimeError:
                    pass
                self._watching = None
            self.unsetCursor()
        for b in (self.prev_btn, self.play_btn, self.next_btn, self.mute_btn, self.cplay):
            b.accent = on
            b.update()
        self._apply_palette(self._pal_last)
        self.refresh_look()
        if on:
            self.place()
        else:
            self.setVisible(self.tab is not None)

    def refresh_look(self):
        """Re-dress the floating card for the current accent colour and interface style (also called when either changes)."""
        if not self.floating:
            self.setStyleSheet("")
            self.lay.setContentsMargins(*self._margins())
            self.update()
            return
        if self._skin() == "term":
            title, sub = "#8dffb0", "#12b84a"
        else:
            title, sub = "#ffffff", _mix(QColor(ACCENT["main"]), QColor(255, 255, 255), 0.38).name()
        self.setStyleSheet("QFrame#media { background: transparent; border: none; } "
                           "QLabel#mediatitle { color: %s; } QLabel#mediasub { color: %s; }" % (title, sub))
        self.lay.setContentsMargins(*self._margins())
        for b in (self.prev_btn, self.play_btn, self.next_btn, self.mute_btn, self.cplay):
            b.update()
        self.update()
        self.place()

    def _anchor(self, corner, w, h):
        """Top-left of the widget (with its shadow room) so the card rests in `corner` of the page area."""
        root, stack, m, sh = self.parentWidget(), self.b.stack, self.EDGE, self.SH
        o = stack.mapTo(root, QPoint(0, 0))
        vw, vh = w - 2 * sh, h - 2 * sh
        x = o.x() + m if "l" in corner else o.x() + stack.width() - m - vw
        y = o.y() + m if "t" in corner else o.y() + stack.height() - m - vh
        return QPoint(x - sh, y - sh)

    def _slide(self):
        """Which way the card slides in from: up from the edge it rests against."""
        return 1 if "b" in self.corner else -1

    def place(self, animate_move=False):
        """Floating only: rest in the chosen corner of the page, or tuck away in focus mode / when nothing is playing."""
        if not self.floating or self._dragging:
            return
        root = self.parentWidget()
        stack = getattr(self.b, "stack", None)
        if root is None or stack is None:
            return
        if (self.tab is None or getattr(self.b, "focus_mode", False)
                or not self.b.settings.get("float_player", True)):
            if self.isVisible() and not self._leaving:
                self._vanish()
            return
        w = self._eff_fw() + 2 * self.SH
        if self.width() != w:
            self.setFixedWidth(w)
        h = self._fit()
        if self.size() != QSize(w, h):
            self.resize(w, h)
        self._place_grip()
        goal = self._anchor(self.corner, w, h)
        if not self.isVisible():
            self._goal = goal
            self.move(goal)
            self._show_in()
            return
        if self._leaving:
            return
        if goal == self._goal and self.pos() == goal:
            return
        self._goal = goal
        if animate_move and self.pos() != goal:
            animate(self, b"pos", self.pos(), goal, 260)
        else:
            stop_anim(self, b"pos")
            self.move(goal)

    def _show_in(self):
        """Fade in while gliding a little way up from the page edge (macOS adds a gentle spring; Terminal just blinks on)."""
        self._leaving = False
        self._gen += 1
        stop_anim(self, b"pos")
        end = self.pos()
        self.show()
        self.raise_()
        sk = self._skin()
        if sk == "term":
            fade_widget(self, 0.0, 1.0, 140)
            return
        fade_widget(self, 0.0, 1.0, 260)
        start = QPoint(end.x(), end.y() + 20 * self._slide())
        if sk == "mac":
            animate(self, b"pos", start, end, 560, curve=mac_curve(True, 1.12))
        else:
            animate(self, b"pos", start, end, 400)

    def _vanish(self):
        """Fade out while dropping back towards the page edge, then hide."""
        if not self.isVisible() or self._leaving:
            return
        self._leaving = True
        self._gen += 1
        gen = self._gen

        def gone():
            try:
                if self._gen == gen and self._leaving:
                    self._leaving = False
                    self.hide()
                    self.setGraphicsEffect(None)
            except RuntimeError:
                pass
        try:
            fade_widget(self, 1.0, 0.0, 200, done=gone)
            if self._skin() != "term":
                animate(self, b"pos", self.pos(), self.pos() + QPoint(0, 12 * self._slide()), 200)
        except RuntimeError:
            gone()

    def _appear(self):
        if not self.floating:
            self.show()
            return
        was_leaving = self._leaving
        self._leaving, self._gen = False, self._gen + 1
        self.place()
        if was_leaving and self.isVisible() and self._goal is not None:
            fade_widget(self, 0.35, 1.0, 220)
            animate(self, b"pos", self.pos(), self._goal, 300)

    def _set_lift(self, v):
        self._lift = float(v)
        self.update()

    def _lift_to(self, target):
        if self._lift_anim is not None:
            self._lift_anim.stop()
        a = QVariantAnimation(self)
        a.setDuration(180)
        a.setStartValue(float(self._lift))
        a.setEndValue(float(target))
        a.setEasingCurve(QEasingCurve.Type.OutCubic)
        a.valueChanged.connect(self._set_lift)
        self._lift_anim = a
        a.start()

    def _drag_press(self, gpos):
        self._dp = (QPoint(gpos), self.pos())
        self._dragging = False
        self._samples = [(time.monotonic(), QPointF(gpos))]

    def _drag_move(self, gpos):
        """Returns True once a drag is under way (the caller then swallows the event so no click follows)."""
        if self._dp is None:
            return False
        d = QPoint(gpos) - self._dp[0]
        if not self._dragging:
            if abs(d.x()) + abs(d.y()) < 6:
                return False
            self._dragging = True
            stop_anim(self, b"pos")
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            self._lift_to(1.0)
            self.raise_()
        root, sh = self.parentWidget(), self.SH
        o = self.b.stack.mapTo(root, QPoint(0, 0))
        x = self._dp[1].x() + d.x()
        y = self._dp[1].y() + d.y()
        x = max(o.x() - sh, min(o.x() + self.b.stack.width() - self.width() + sh, x))
        y = max(o.y() - sh, min(o.y() + self.b.stack.height() - self.height() + sh, y))
        self.move(x, y)
        now = time.monotonic()
        self._samples.append((now, QPointF(gpos)))
        self._samples = [t for t in self._samples if now - t[0] < 0.12]
        return True

    def _drag_release(self):
        """Returns True if this was a drag (so the release must not count as a click). The card keeps a little of the
        flick's momentum, then glides to whichever corner it is nearest."""
        was = self._dragging
        self._dp, self._dragging = None, False
        if not was:
            return False
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self._lift_to(0.0)
        vx = vy = 0.0
        if len(self._samples) >= 2:
            (t0, p0), (t1, p1) = self._samples[0], self._samples[-1]
            dt = max(1e-3, t1 - t0)
            vx, vy = (p1.x() - p0.x()) / dt, (p1.y() - p0.y()) / dt
        root, stack = self.parentWidget(), self.b.stack
        o = stack.mapTo(root, QPoint(0, 0))
        cx = self.x() + self.width() / 2.0 + max(-420.0, min(420.0, vx)) * 0.14
        cy = self.y() + self.height() / 2.0 + max(-420.0, min(420.0, vy)) * 0.14
        corner = ("t" if cy < o.y() + stack.height() / 2.0 else "b") + ("l" if cx < o.x() + stack.width() / 2.0 else "r")
        if corner != self.corner:
            self.corner = corner
            self.b.settings["player_corner"] = corner
            jsave("settings.json", self.b.settings)
            self._place_grip()
        w, h = self.width(), self.height()
        self._goal = self._anchor(self.corner, w, h)
        curve = mac_curve(True, 1.06) if self._skin() == "mac" else QEasingCurve.Type.OutCubic
        animate(self, b"pos", self.pos(), self._goal, 520 if self._skin() == "mac" else 380, curve=curve)
        return True

    def mousePressEvent(self, e):
        if self.floating and e.button() == Qt.MouseButton.LeftButton:
            self._drag_press(e.globalPosition().toPoint())
            e.accept()
            return
        super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        if self.floating and self._dp is not None:
            self._drag_move(e.globalPosition().toPoint())
            e.accept()
            return
        super().mouseMoveEvent(e)

    def mouseReleaseEvent(self, e):
        if self.floating and e.button() == Qt.MouseButton.LeftButton and self._dp is not None:
            self._drag_release()
            e.accept()
            return
        super().mouseReleaseEvent(e)

    def eventFilter(self, obj, ev):
        t = ev.type()
        if obj is self._watching:
            if self.floating and t in (QEvent.Type.Resize, QEvent.Type.Move):
                QTimer.singleShot(0, lambda: self.place(True))
            return False
        if self.floating and obj in (self.art, self.title, self.sub):
            if t == QEvent.Type.MouseButtonPress and ev.button() == Qt.MouseButton.LeftButton:
                self._drag_press(ev.globalPosition().toPoint())
            elif t == QEvent.Type.MouseMove and self._dp is not None:
                if self._drag_move(ev.globalPosition().toPoint()):
                    return True
            elif t == QEvent.Type.MouseButtonRelease and self._dp is not None:
                if self._drag_release():
                    return True
        return False

    def paintEvent(self, e):
        if not self.floating:
            super().paintEvent(e)
            return
        p = QPainter(self)
        try:
            self._paint_card(p)
        except Exception:
            log_error("media card paint")
        finally:
            p.end()

    def _paint_card(self, p):
        sk, sh = self._skin(), self.SH
        r = QRectF(self.rect()).adjusted(sh, sh, -sh, -sh)
        rad = {"default": 18.0, "mac": 22.0, "windows": 8.0, "term": 2.0}.get(sk, 18.0)
        lift = self._lift
        acc, alt = QColor(ACCENT["main"]), QColor(ACCENT["alt"])
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        if sk != "term":
            layers = 7
            for i in range(layers, 0, -1):
                grow = i * (sh / float(layers))
                a = (4.5 + 7.0 * lift) * (1.0 - (i - 1) / float(layers))
                p.setBrush(QColor(0, 0, 0, int(a)))
                rr_ = r.adjusted(-grow, -grow, grow, grow).translated(0, 2.0 + 3.0 * lift)
                p.drawRoundedRect(rr_, rad + grow, rad + grow)
        path = QPainterPath()
        path.addRoundedRect(r.adjusted(0.5, 0.5, -0.5, -0.5), rad, rad)
        wash = QLinearGradient(r.topLeft(), r.bottomRight())
        if sk == "term":
            paint_term_panel(p, r, rad)
            hold = QColor(ACCENT["main"])
            hold.setAlpha(int(70 + 90 * lift))
            p.setPen(QPen(hold, 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        elif sk == "mac":
            paint_glass_panel(p, r.toRect(), rad, None, "#101b26")
            a1, a2 = QColor(acc), QColor(alt)
            a1.setAlpha(46)
            a2.setAlpha(8)
            wash.setColorAt(0.0, a1)
            wash.setColorAt(1.0, a2)
            p.save()
            p.setClipPath(path)
            p.fillRect(r, QBrush(wash))
            p.restore()
        elif sk == "windows":
            p.fillPath(path, QColor(themed("#172431")))
            a1, a2 = QColor(acc), QColor(alt)
            a1.setAlpha(30)
            a2.setAlpha(0)
            wash.setColorAt(0.0, a1)
            wash.setColorAt(1.0, a2)
            p.save()
            p.setClipPath(path)
            p.fillRect(r, QBrush(wash))
            p.restore()
            edge = _mix(QColor(255, 255, 255), acc, 0.5 * lift)
            edge.setAlpha(int(30 + 90 * lift))
            p.setPen(QPen(edge, 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        else:
            p.fillPath(path, QColor(themed("#101b26")))
            a1, a2 = QColor(acc), QColor(alt)
            a1.setAlpha(58)
            a2.setAlpha(12)
            wash.setColorAt(0.0, a1)
            wash.setColorAt(1.0, a2)
            p.save()
            p.setClipPath(path)
            p.fillRect(r, QBrush(wash))
            p.restore()
            ring = QColor(acc)
            ring.setAlpha(int(85 + 110 * lift))
            p.setPen(QPen(ring, 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        g = QColor(ACCENT["main"]) if sk == "term" else QColor(255, 255, 255)
        g.setAlpha(int(55 + 120 * lift))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        gw = 26.0
        p.drawRoundedRect(QRectF(r.center().x() - gw / 2, r.top() + 4.5, gw, 3.0), 1.5 if sk != "term" else 0.5,
                          1.5 if sk != "term" else 0.5)

    def on_audible(self, tab, audible):
        if audible and not tab.closing and tab is not self.tab:
            self.attach(tab)

    def attach(self, tab):
        if self.tab is not None:
            self._stop_viz_js(self.tab)
            self.close_pip()
        self.tab, self.paused, self._misses, self._art_key = tab, False, 0, None
        self._real, self._real_ts = [], -999.0
        self._viz_sent = 0.0
        self._set_play_kind("pause")
        self.mute_btn.set_kind("mute" if tab.page().isAudioMuted() else "sound")
        self.title.setText(tab.title() or self.b.host_of(tab.url()) or "Playing")
        self.sub.setText(self.b.host_of(tab.url()))
        self.seekbar.set_value(0, False)
        self._set_art("")
        self.viz.setVisible(self.viz_on)
        self._appear()
        self.poll_timer.start()
        self._auto_pip = self._auto_dismissed = self._vis_busy = False
        self.scroll_timer.start()
        self.poll()
        self._sync_viz()

    def clear(self):
        self.scroll_timer.stop()
        self._auto_pip = self._auto_dismissed = False
        self.close_pip()
        if self.tab is not None:
            self._stop_viz_js(self.tab)
        self.tab = None
        self.poll_timer.stop()
        self.viz_timer.stop()
        if self.floating and self.isVisible():
            self._vanish()
        else:
            self.hide()

    def stop_and_hide(self):
        self._run(media_js("pause"))
        self.clear()

    def _set_play_kind(self, kind):
        self.play_btn.set_kind(kind)
        self.cplay.set_kind(kind)

    def set_compact(self, c):
        self.compact = c
        self.cplay.setVisible(c)
        self.art.setToolTip("Pop out the video" if c else "")
        for w in (self.textw, self.close_btn, self.seekbar, self.ctl_wrap):
            w.setVisible(not c)
        self.lay.setContentsMargins(*self._margins())
        self.top.setSpacing(0 if c else 9)
        self.top.setAlignment(self.art, Qt.AlignmentFlag.AlignHCenter if c else Qt.AlignmentFlag.AlignLeft)
        self.viz.setVisible(self.viz_on and self.tab is not None)
        self._sync_viz()
        self.place()

    def _run(self, js):
        if self.tab is None:
            return
        try:
            self.tab.page().runJavaScript(js)
        except RuntimeError:
            self.clear()

    def poll(self):
        t = self.tab
        if t is None:
            return
        try:
            if self.b.stack.indexOf(t) < 0 or t.closing:
                self.clear()
                return
            t.page().runJavaScript(MEDIA_STATE_JS, lambda r, t=t: self._on_state(t, r))
        except RuntimeError:
            self.clear()

    def _on_state(self, t, raw):
        if t is not self.tab:
            return
        try:
            d = json.loads(raw) if raw else {"none": 1}
        except ValueError:
            d = {"none": 1}
        if d.get("none"):
            self._misses += 1
            if self._misses >= 4:
                self.clear()
            return
        self._misses = 0
        self.update_state(d)

    def update_state(self, d):
        t = self.tab
        title = d.get("title") or t.title() or "Playing"
        sub = d.get("artist") or self.b.host_of(t.url())
        self.title.setText(title)
        self.sub.setText(sub)
        self.setToolTip(title)
        paused = bool(d.get("paused"))
        if paused != self.paused:
            self.paused = paused
            self._set_play_kind("play" if paused else "pause")
            self._sync_viz()
        dur = d.get("d") or 0
        self.seekbar.set_value((d.get("t") or 0) / dur if dur > 0 else 0, dur > 0)
        if self.pip is not None:
            self.pip.set_state(paused, (d.get("t") or 0) / dur if dur > 0 else 0.0, dur > 0)
        self.mute_btn.set_kind("mute" if t.page().isAudioMuted() else "sound")
        self._set_art(d.get("art") or "")

    def control(self, action):
        if action == "toggle":
            self._toggle_t = time.monotonic()
            self.paused = not self.paused
            self._set_play_kind("play" if self.paused else "pause")
            if self.pip is not None:
                self.pip.set_state(self.paused, self.pip.frac, self.pip.can_seek)
            self._sync_viz()
        self._run(media_js(action))
        QTimer.singleShot(250, self.poll)

    def toggle_mute(self):
        if self.tab is None:
            return
        pg = self.tab.page()
        pg.setAudioMuted(not pg.isAudioMuted())
        self.tab.row.update_audio(self.tab)
        self.mute_btn.set_kind("mute" if pg.isAudioMuted() else "sound")

    def goto(self):
        if self.tab is not None:
            i = self.b.stack.indexOf(self.tab)
            if i >= 0:
                self.b.tabs.setCurrentRow(i)

    def _art_clicked(self):
        self.open_pip()

    def open_pip(self):
        """Clicking the player pops the video out into the floating frame. Audio-only or protected media just opens its tab."""
        self._open_pip()

    def _open_pip(self, auto=False):
        if self.tab is None:
            return
        if self.pip is not None:
            if not auto:
                self.goto()
            return
        if auto:
            self._auto_pip = True
        t = self.tab
        try:
            t.page().runJavaScript(pip_js(640, True), lambda r, t=t, a=auto: self._pip_first(t, r, a))
        except RuntimeError:
            self.clear()

    def _scroll_tick(self):
        t = self.tab
        if t is None or self._vis_busy or self.b.cur() is not t:
            return
        if (self.paused and self.pip is None) or not self.b.settings.get("auto_pip", True):
            return
        self._vis_busy = True
        try:
            t.page().runJavaScript(VIS_JS, lambda r, t=t: self._on_vis(t, r))
        except RuntimeError:
            self._vis_busy = False
            self.clear()

    def _on_vis(self, t, raw):
        self._vis_busy = False
        if t is not self.tab:
            return
        try:
            f = float(raw)
        except (TypeError, ValueError):
            return
        if f < PIP_AWAY:
            if self.pip is None and not self._auto_pip and not self._auto_dismissed and not self.paused:
                self._open_pip(auto=True)
        elif f > PIP_BACK:
            self._auto_dismissed = False
            if self.pip is not None and self._auto_pip:
                self._auto_pip = False
                self.close_pip()

    def _pip_first(self, t, r, auto=False):
        if t is not self.tab or self.pip is not None:
            return
        meta = self._pip_meta(r)
        if not (meta and meta.get("f")):
            if auto:
                self._auto_pip, self._auto_dismissed = False, True
                return
            if r == "null":
                self.b.toast("This site doesn't let Fjord copy its video, so it opened the tab instead", 4500)
            self.goto()
            return
        self.pip = PipFrame()
        self.pip.toggled.connect(lambda: self.control("toggle"))
        self.pip.back.connect(self._pip_back)
        self.pip.seek.connect(lambda f: self._run(media_js("seek", f)))
        self.pip.closed.connect(self._pip_closed)
        self._pip_img(meta["f"])
        self.pip.open_animated()
        self._pip_apply_meta(meta)
        self.pip_timer.start()
        self.poll()

    def _pip_back(self):
        self._auto_dismissed = True
        self.close_pip()
        self.goto()

    def _pip_closed(self):
        if self._auto_pip:
            self._auto_dismissed = True
        self._auto_pip = False
        self.pip = None
        self.pip_timer.stop()
        self._run("try{window.__fjP=null}catch(e){}")

    def close_pip(self):
        if self.pip is not None:
            self.pip_timer.stop()
            self.pip.close_animated()

    @staticmethod
    def _pip_meta(r):
        if isinstance(r, str) and r.startswith("{"):
            try:
                d = json.loads(r)
                return d if isinstance(d, dict) else None
            except ValueError:
                return None
        return None

    def _pip_apply_meta(self, d):
        """Position and play/pause ride along with every frame, so the picture, the progress bar and the buttons always agree
        (before, they only refreshed with the slower sidebar poll)."""
        dur = d.get("d") or 0
        frac = (d.get("t") or 0) / dur if dur > 0 else 0.0
        paused = bool(d.get("p"))
        if time.monotonic() - getattr(self, "_toggle_t", 0.0) < 0.6:
            paused = self.paused
        elif paused != self.paused:
            self.paused = paused
            self._set_play_kind("play" if paused else "pause")
            self._sync_viz()
        self.seekbar.set_value(frac, dur > 0)
        if self.pip is not None:
            self.pip.set_state(paused, frac, dur > 0)

    def _pip_img(self, data_url):
        try:
            img = QImage()
            if img.loadFromData(base64.b64decode(data_url.split(",", 1)[1])) and self.pip is not None:
                self.pip.set_frame(img)
        except (ValueError, IndexError):
            pass

    def _pip_tick(self):
        if self.pip is None or self.tab is None:
            self.pip_timer.stop()
            return
        if self._pip_busy or not self.pip.isVisible():
            return
        if self.paused:
            self._pip_idle = (getattr(self, "_pip_idle", 0) + 1) % 6
            if self._pip_idle:
                return
        self._pip_busy = True
        t = self.tab
        dpr = self.pip.devicePixelRatioF()
        want = max(280, min(800, int(self.pip.vw * dpr)))
        try:
            t.page().runJavaScript(pip_js(want), lambda r, t=t: self._pip_got(t, r))
        except RuntimeError:
            self._pip_busy = False
            self.clear()

    def _pip_got(self, t, r):
        self._pip_busy = False
        if t is not self.tab or self.pip is None:
            return
        meta = self._pip_meta(r)
        if meta is None:
            return
        if meta.get("f"):
            self._pip_img(meta["f"])
        self._pip_apply_meta(meta)

    def contextMenuEvent(self, e):
        if self.tab is None:
            return
        m = QMenu(self)
        m.addAction("Picture in picture", self.open_pip)
        ap = m.addAction("Pop out video when scrolled away")
        ap.setCheckable(True)
        ap.setChecked(bool(self.b.settings.get("auto_pip", True)))
        ap.triggered.connect(lambda on: self.b.set_auto_pip(bool(on)))
        m.addAction("Go to tab", self.goto)
        muted = self.tab.page().isAudioMuted()
        m.addAction("Unmute tab" if muted else "Mute tab", self.toggle_mute)
        a = m.addAction("Audio visualiser")
        a.setCheckable(True)
        a.setChecked(self.viz_on)
        a.triggered.connect(lambda on: self.b.set_visualizer(bool(on)))
        if self.floating:
            m.addSeparator()
            if self._fw != self.FLOAT_W or self._fh is not None:
                m.addAction("Reset player size", self.reset_size)
            m.addAction("Hide floating player", lambda: self.b.set_float_player(False))
        m.addSeparator()
        m.addAction("Stop and hide", self.stop_and_hide)
        m.exec(e.globalPos())

    def _fallback_art(self):
        pm = QPixmap(72, 72)
        pm.fill(Qt.GlobalColor.transparent)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(accent_color(45))
        p.drawRoundedRect(QRectF(0, 0, 72, 72), rr(20), rr(20))
        ic = self.tab.icon() if self.tab is not None else QIcon()
        if not ic.isNull():
            ip = ic.pixmap(40, 40)
            p.drawPixmap(16, 16, 40, 40, ip)
        else:
            p.setPen(accent_color(255))
            f = QFont(self.font())
            f.setPixelSize(34)
            p.setFont(f)
            p.drawText(QRectF(0, 0, 72, 72), Qt.AlignmentFlag.AlignCenter, "♪")
        p.end()
        pm.setDevicePixelRatio(2)
        return pm

    def _icon_palette(self):
        ic = self.tab.icon() if self.tab is not None else QIcon()
        return art_palette(ic.pixmap(32, 32)) if not ic.isNull() else None

    def _apply_palette(self, pal):
        self._pal_last = pal
        if self.floating:
            pal = None
        self.viz.set_palette(pal, snap=not self.viz_timer.isActive())
        self.seekbar.set_color(pal[0] if pal else None)

    def _set_art(self, url):
        icon_key = self.tab.icon().cacheKey() if (self.tab is not None and not url) else 0
        key = (url, icon_key)
        if key == self._art_key:
            return
        self._art_key = key
        pm = self._art_cache.get(url) if url else None
        if pm is not None:
            self._set_art_pm(pm)
            self._apply_palette(self._art_pal.get(url, VIZ_NEUTRAL))
            return
        self._set_art_pm(self._fallback_art())
        can_fetch = bool(url) and not self.b.settings.get("vpn") and safe_art_url(url)
        if can_fetch and url not in self._art_pending:
            self._art_pending.add(url)
            req = QNetworkRequest(QUrl(url))
            req.setAttribute(QNetworkRequest.Attribute.RedirectPolicyAttribute,
                             QNetworkRequest.RedirectPolicy.NoLessSafeRedirectPolicy)
            rep = self.net.get(req)
            rep.downloadProgress.connect(lambda got, _tot, r=rep: r.abort() if got > 3_000_000 else None)
            rep.finished.connect(lambda r=rep, u=url: self._art_done(r, u))
        if not can_fetch:
            self._apply_palette(self._icon_palette())

    def _art_done(self, rep, url):
        self._art_pending.discard(url)
        data = bytes(rep.readAll()) if rep.error() == QNetworkReply.NetworkError.NoError else b""
        rep.deleteLater()
        pm = QPixmap()
        if data and pm.loadFromData(data):
            if len(self._art_cache) >= 8:
                self._art_cache.pop(next(iter(self._art_cache)))
            if len(self._art_pal) >= 16:
                self._art_pal.pop(next(iter(self._art_pal)))
            self._art_cache[url] = rounded_pixmap(pm, 36, 9)
            self._art_pal[url] = art_palette(pm) or VIZ_NEUTRAL
            self._art_key = None
            self.poll()
        elif self._art_key and self._art_key[0] == url:
            self._apply_palette(self._icon_palette())

    def set_viz(self, on):
        self.viz_on = on
        if not on and self.tab is not None:
            self._stop_viz_js(self.tab)
        self.viz.vals = [0.0] * VIZ_BARS
        self.viz.setVisible(on and self.tab is not None)
        self._sync_viz()
        self.place()

    def set_viz_look(self, style, dens, size):
        """Applies the Style / Detail / Height settings to the sidebar visualiser."""
        self.viz.set_look(style, dens, size)
        self.place()

    def _stop_viz_js(self, tab):
        try:
            tab.page().runJavaScript(VIZ_STOP_JS)
        except RuntimeError:
            pass

    def _sync_viz(self):
        run = (self.viz_on and self.tab is not None and self.isVisible()
               and (not self.paused or max(self.viz.vals) > 0.01))
        if run and not self.viz_timer.isActive():
            self.viz_timer.start()
        elif not run:
            self.viz_timer.stop()

    def showEvent(self, e):
        super().showEvent(e)
        self._sync_viz()

    def hideEvent(self, e):
        super().hideEvent(e)
        self.viz_timer.stop()

    def _viz_data(self, t, raw):
        self._viz_sent = 0.0
        if t is not self.tab or not raw:
            return
        try:
            data = json.loads(raw)
        except ValueError:
            return
        if isinstance(data, list) and len(data) == VIZ_BARS and max(data) > 0.03:
            self._real, self._real_ts = data, time.monotonic()

    @staticmethod
    def _ambient(now):
        out = []
        for i in range(VIZ_BARS):
            a = math.sin(now * (2.1 + 0.37 * i) + i * 1.7)
            b = math.sin(now * (1.3 + 0.21 * i) + i * 0.6)
            pulse = 0.7 + 0.3 * math.sin(now * 2.4)
            out.append(max(0.06, min(1.0, (0.62 - 0.014 * i) * (0.4 + 0.4 * a * a + 0.2 * b) * pulse)))
        return out

    def _viz_tick(self):
        now = time.monotonic()
        vals = self.viz.vals
        if self.tab is not None and not self.paused:
            if self._viz_sent == 0.0 or now - self._viz_sent > 0.3:
                self._viz_sent = now
                try:
                    self.tab.page().runJavaScript(VIZ_JS, lambda r, t=self.tab: self._viz_data(t, r))
                except RuntimeError:
                    self._viz_sent = 0.0
                    return
            targets = self._real if (now - self._real_ts) < 1.5 and len(self._real) == VIZ_BARS else self._ambient(now)
        else:
            targets = [0.0] * VIZ_BARS
        for i in range(VIZ_BARS):
            vals[i] += (targets[i] - vals[i]) * (0.85 if targets[i] > vals[i] else 0.3)
        self.viz.step_colors()
        self.viz.update()
        if self.paused and max(vals) < 0.01:
            self.viz_timer.stop()


# ====================================================================================================
# 39  FOCUS MODE WIDGETS
# ====================================================================================================

class FocusPill(QPushButton):
    """Focus mode's way back. A thin zone along the top edge of the window wakes a small pill that slides down from it;
    clicking the pill leaves focus mode. Both are drawn over the page, so they never resize anything."""
    def __init__(self, browser):
        super().__init__("Exit focus mode", browser)
        self.b = browser
        self.setObjectName("focuspill")
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setStyleSheet("#focuspill{background:rgba(16,28,40,238);border:1px solid rgba(255,255,255,0.14);border-radius:15px;"
                           "color:#e4edf3;font-size:12px;padding:7px 18px} #focuspill:hover{background:rgba(30,50,68,245)}")
        self.clicked.connect(lambda _c=False: browser.set_focus_mode(False))
        self._shown = False
        self._out = QTimer(self)
        self._out.setSingleShot(True)
        self._out.timeout.connect(self.retract)
        self.zone = HoverZone(self.peek)
        self.zone.setParent(browser)
        self.zone.hide()
        self.hide()

    def place(self):
        p = self.parentWidget()
        if p is None:
            return
        self.zone.setGeometry(0, 8, p.width(), 8)
        if self._shown:
            self.adjustSize()
            self.move((p.width() - self.width()) // 2, 14)
            self.raise_()
        if self.zone.isVisible():
            self.zone.raise_()

    def set_active(self, on):
        self._out.stop()
        self._shown = False
        self.hide()
        self.zone.setVisible(bool(on))
        if on:
            self.place()

    def peek(self):
        if not self.b.focus_mode:
            return
        self._out.start(2600)
        if self._shown:
            return
        self._shown = True
        self.adjustSize()
        p = self.parentWidget()
        x = (p.width() - self.width()) // 2
        self.show()
        self.raise_()
        animate(self, b"pos", QPoint(x, -self.height()), QPoint(x, 14), 240)

    def retract(self):
        if not self._shown:
            return
        if self.underMouse():
            self._out.start(1200)
            return
        self._shown = False
        animate(self, b"pos", self.pos(), QPoint(self.x(), -self.height() - 4), 200, done=self.hide)


class HoverBar(QFrame):
    """Floating pill (link URL / short messages) drawn over the page, so showing it never resizes the window."""
    def __init__(self, parent):
        super().__init__(parent)
        self.setObjectName("hoverbar")
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(10, 5, 14, 5)
        lay.setSpacing(8)
        self.icon = QLabel()
        self.icon.setFixedSize(16, 16)
        self.icon.setScaledContents(True)
        self.text = QLabel()
        lay.addWidget(self.icon)
        lay.addWidget(self.text)
        self.setStyleSheet("#hoverbar{background:rgba(16,28,40,238);border:1px solid rgba(255,255,255,0.12);"
                           "border-radius:13px} #hoverbar QLabel{background:transparent;color:#e4edf3;font-size:12px}")
        self.hide()

    def set_content(self, text, pm=None):
        parent = self.parentWidget()
        maxw = max(160, (parent.width() if parent else 800) - 120)
        self.text.setText(self.text.fontMetrics().elidedText(text, Qt.TextElideMode.ElideMiddle, maxw))
        if pm is not None and not pm.isNull():
            self.icon.setPixmap(pm)
            self.icon.show()
        else:
            self.icon.hide()
        self.adjustSize()
        self.place()
        self.show()
        self.raise_()

    def place(self):
        parent = self.parentWidget()
        if parent is not None:
            self.move(parent.width() - self.width() - 16, parent.height() - self.height() - 16)


