# 42  CUSTOMISABLE TOOLBAR
# ====================================================================================================

class IconGrid(QWidget):
    """Compact mode: the toolbar's icon buttons in the sidebar, wrapped onto as many rows as the sidebar's width needs.
    It re-flows whenever the sidebar is resized."""
    GAP = 4

    def __init__(self):
        super().__init__()
        self.items, self.cols = [], 0
        self.grid = QGridLayout(self)
        self.grid.setContentsMargins(0, 0, 0, 0)
        self.grid.setHorizontalSpacing(self.GAP)
        self.grid.setVerticalSpacing(self.GAP)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

    def _cols_for(self, width):
        return max(1, int((max(0, width) + self.GAP) // (ToolIcon.SIZE + self.GAP)))

    def set_items(self, widgets, avail=200):
        for w in self.items:
            self.grid.removeWidget(w)
        self.items = list(widgets)
        self.cols = -1
        self.reflow(self.width() if self.width() > 60 else avail)

    def reflow(self, width):
        cols = self._cols_for(width)
        if cols == self.cols:
            return
        for c in range(max(self.cols, 0) + 2):
            self.grid.setColumnStretch(c, 0)
        for w in self.items:
            self.grid.removeWidget(w)
        self.cols = cols
        for i, w in enumerate(self.items):
            self.grid.addWidget(w, i // cols, i % cols)
        self.grid.setColumnStretch(cols, 1)
        rows = (len(self.items) + cols - 1) // cols
        self.setFixedHeight(rows * ToolIcon.SIZE + max(0, rows - 1) * self.GAP if rows else 0)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if self.items and self._cols_for(e.size().width()) != self.cols:
            QTimer.singleShot(0, lambda: self.reflow(self.width()))

TB_MIME = "application/x-fjord-tbitem"
TB_ITEMS = {"side": "Sidebar", "back": "Back", "fwd": "Forward", "reload": "Reload", "engine": "Search engine",
            "speed": "Speed", "vpn": "Privacy shield", "ext": "Extensions", "star": "Bookmark", "ytdl": "Video download", "site": "Site settings", "scratch": "Scratchpad",
            "tabsearch": "Command palette", "uistyle": "Interface style", "menu": "Menu"}
TB_GLYPHS = {"side": "sidebar", "back": "back", "fwd": "forward", "reload": "reload", "speed": "speed", "vpn": "shield",
             "ext": "puzzle", "star": "star", "ytdl": "save", "site": "sliders", "scratch": "scratch", "tabsearch": "search", "uistyle": "ui_default", "menu": "dots"}
TB_DEFAULT = ["side", "back", "fwd", "reload", "addr", "engine", "speed", "vpn", "ext", "star", "ytdl", "site", "scratch", "tabsearch", "menu"]
TB_FIXED = ("addr", "menu")
TB_STRETCH = {"addr": 5, "space": 1}
TB_SIDE_ONLY = ("scratch", "tabsearch")
_TB_INST = re.compile(r"^(sep|space)#\d+$")


def tb_base(iid):
    return iid.split("#")[0]


def clean_toolbar(raw):
    """Turn whatever settings.json holds into a valid toolbar order (unknown/duplicate ids dropped, addr + menu kept)."""
    if not isinstance(raw, list):
        return list(TB_DEFAULT)
    out = []
    for x in raw:
        if isinstance(x, str) and x not in out and (x in TB_ITEMS or x == "addr" or _TB_INST.match(x)):
            out.append(x)
    if "addr" not in out:
        out.insert(out.index("reload") + 1 if "reload" in out else 0, "addr")
    if "menu" not in out:
        out.append("menu")
    return out


SB_ITEMS = {"group": "New group", "focus": "Focus mode", "search": "Command palette", "scratch": "Scratchpad"}
SB_DESC = {"group": "Makes an empty tab group you can drag tabs onto",
           "focus": "Hides the tabs, sidebar and toolbar so only the page is left",
           "search": "Opens the command palette (Ctrl+K by default)",
           "scratch": "Opens the Scratchpad drawer, and takes anything you drop on it"}
SB_DEFAULT = {"top": ["group", "focus", "search"], "bottom": ["scratch"]}
SB_HOME = {"group": "top", "focus": "top", "search": "top", "scratch": "bottom"}


def clean_side_btns(raw):
    """Turn whatever settings.json holds for the sidebar buttons into {"top": [...], "bottom": [...]}: the buttons above the
    tab list and the ones under it, each in order. A button that is in neither list is hidden. Unknown or repeated ids
    are dropped, and a missing or broken value gives the default layout."""
    if not isinstance(raw, dict):
        return {z: list(v) for z, v in SB_DEFAULT.items()}
    out, seen = {}, set()
    for zone in ("top", "bottom"):
        out[zone] = []
        lst = raw.get(zone)
        for x in (lst if isinstance(lst, list) else []):
            if isinstance(x, str) and x in SB_ITEMS and x not in seen:
                seen.add(x)
                out[zone].append(x)
    return out


SB_MIME = "application/x-fjord-sbitem"
SB_GLYPHS = {"group": "group", "focus": "focus", "search": "search", "scratch": "scratch"}


class SbTile(QWidget):
    """One sidebar button in the customise popup. Drag it to another place or another lane."""
    W, H = 74, 62

    def __init__(self, pop, iid):
        super().__init__()
        self.pop, self.iid, self.press_pos = pop, iid, None
        self.setFixedSize(self.W, self.H)
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self.setToolTip(SB_DESC[self.iid])

    def mousePressEvent(self, e):
        self.press_pos = e.position().toPoint() if e.button() == Qt.MouseButton.LeftButton else None

    def mouseMoveEvent(self, e):
        if (e.buttons() & Qt.MouseButton.LeftButton) and self.press_pos is not None \
                and (e.position().toPoint() - self.press_pos).manhattanLength() >= QApplication.startDragDistance():
            self.press_pos = None
            self.pop.drag_item(self.iid, self)

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 16))
        p.drawRoundedRect(QRectF(self.rect()), rr(12), rr(12))
        cx, cy = self.W / 2.0, 22.0
        draw_glyph(p, SB_GLYPHS[self.iid], QRectF(cx - 10, cy - 10, 20, 20), QColor(themed("#b5c6d4")), 1.7)
        p.setPen(QColor(themed("#8ea3b4")))
        f = p.font()
        f.setPixelSize(10)
        p.setFont(f)
        txt = QFontMetrics(f).elidedText(SB_ITEMS[self.iid], Qt.TextElideMode.ElideRight, self.W - 8)
        p.drawText(QRectF(0, 38, self.W, 18), Qt.AlignmentFlag.AlignCenter, txt)
        p.end()


class SbLane(QFrame):
    """A row of buttons in the customise popup (above the tabs, below the tabs, or hidden). Drop a tile on it to place it there."""
    def __init__(self, pop, zone):
        super().__init__()
        self.pop, self.zone, self.tiles, self.marker, self.over = pop, zone, [], None, False
        self.setAcceptDrops(True)
        self.setMinimumHeight(SbTile.H + 16)
        self.lay = QHBoxLayout(self)
        self.lay.setContentsMargins(8, 8, 8, 8)
        self.lay.setSpacing(8)
        self.lay.addStretch(1)

    def set_items(self, ids):
        for tile in self.tiles:
            self.lay.removeWidget(tile)
            tile.hide()
            tile.deleteLater()
        self.tiles = []
        for iid in ids:
            tile = SbTile(self.pop, iid)
            self.lay.insertWidget(len(self.tiles), tile)
            self.tiles.append(tile)
        self.update()

    def slot_at(self, x):
        k = sum(1 for tile in self.tiles if tile.geometry().center().x() < x)
        if k < len(self.tiles):
            return k, self.tiles[k].geometry().left() - 5
        return k, (self.tiles[-1].geometry().right() + 5 if self.tiles else 10)

    def dragEnterEvent(self, e):
        self.dragMoveEvent(e)

    def dragMoveEvent(self, e):
        if not e.mimeData().hasFormat(SB_MIME):
            e.ignore()
            return
        e.acceptProposedAction()
        self.over = True
        self.marker = self.slot_at(e.position().toPoint().x())[1]
        self.update()

    def dragLeaveEvent(self, e):
        self.over, self.marker = False, None
        self.update()

    def dropEvent(self, e):
        if not e.mimeData().hasFormat(SB_MIME):
            return
        iid = bytes(e.mimeData().data(SB_MIME)).decode("utf-8", "ignore")
        idx = self.slot_at(e.position().toPoint().x())[0]
        self.over, self.marker = False, None
        e.acceptProposedAction()
        self.pop.pending = lambda: self.pop.place(iid, self.zone, idx)
        self.update()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(accent_color(24) if self.over else QColor(255, 255, 255, 8))
        p.drawRoundedRect(r, rr(14), rr(14))
        pen = QPen(accent_color(170 if self.over else 70), 1.2)
        pen.setDashPattern([3.0, 3.0])
        p.setPen(pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(r, rr(14), rr(14))
        if not self.tiles:
            p.setPen(QColor(themed("#8ea3b4")))
            f = p.font()
            f.setPixelSize(11)
            p.setFont(f)
            p.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, "Drop buttons here")
        if self.marker is not None:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(accent_color())
            p.drawRoundedRect(QRectF(self.marker - 1.5, 8, 3, self.height() - 16), 1.5, 1.5)
        p.end()


class SideButtonsEditor(GlassPopup):
    """Small popup for arranging the sidebar's buttons. Drag a button within its row, to the other row, or to Hidden."""
    GUARD = "_sbedit_closed"

    def __init__(self, win):
        super().__init__(win)
        self.setWindowFlags(Qt.WindowType.Tool | Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setObjectName("privdash")
        self.setStyleSheet(themed(PrivacyDashboard._qss()))
        self.setFixedWidth(358)
        self.pending = None
        lay = QVBoxLayout(self)
        lay.setContentsMargins(14, 14, 14, 14)
        lay.setSpacing(6)
        t = QLabel("Customize sidebar buttons")
        t.setObjectName("hd")
        s = QLabel("Drag a button to rearrange it, move it to the other row, or drop it on Hidden to remove it.")
        s.setObjectName("sub")
        s.setWordWrap(True)
        lay.addWidget(t)
        lay.addWidget(s)
        self.lanes = {}
        heads = (("top", "Above the tab list"), ("bottom", "Below the tab list"), ("hidden", "Hidden"))
        for zone, head in heads:
            lab = QLabel(head)
            lab.setObjectName("sub")
            lay.addSpacing(4)
            lay.addWidget(lab)
            self.lanes[zone] = SbLane(self, zone)
            lay.addWidget(self.lanes[zone])
        if win.horiz:
            note = QLabel("With horizontal tabs only New group and Focus mode sit by the tabs. Scratchpad and Command palette "
                          "are toolbar buttons then.")
            note.setObjectName("sub")
            note.setWordWrap(True)
            lay.addWidget(note)
        foot = QHBoxLayout()
        reset = QPushButton("Reset")
        done = QPushButton("Done")
        for b in (reset, done):
            b.setObjectName("pbtn")
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        reset.clicked.connect(self.reset)
        done.clicked.connect(self.close)
        foot.addStretch(1)
        foot.addWidget(reset)
        foot.addWidget(done)
        lay.addSpacing(4)
        lay.addLayout(foot)
        self.refresh()

    def refresh(self):
        conf = clean_side_btns(self.win.settings.get("side_btns"))
        self.lanes["top"].set_items(conf["top"])
        self.lanes["bottom"].set_items(conf["bottom"])
        self.lanes["hidden"].set_items([i for i in SB_ITEMS if i not in conf["top"] and i not in conf["bottom"]])

    def place(self, iid, zone, idx):
        self.win.side_btn_place(iid, zone, idx)
        self.refresh()

    def reset(self):
        self.win._side_btn_apply("reset", "")
        self.refresh()

    def drag_item(self, iid, src):
        drag = QDrag(self)
        mime = QMimeData()
        mime.setData(SB_MIME, iid.encode())
        drag.setMimeData(mime)
        pm = src.grab()
        ghost = QPixmap(pm.size())
        ghost.fill(Qt.GlobalColor.transparent)
        gp = QPainter(ghost)
        gp.setOpacity(0.85)
        gp.drawPixmap(0, 0, pm)
        gp.end()
        drag.setPixmap(ghost)
        drag.setHotSpot(QPoint(pm.width() // 2, pm.height() // 2))
        self.pending = None
        drag.exec(Qt.DropAction.MoveAction)
        for lane in self.lanes.values():
            lane.over, lane.marker = False, None
            lane.update()
        fn, self.pending = self.pending, None
        if fn:
            QTimer.singleShot(0, fn)

    def show_near(self):
        self.adjustSize()
        win = self.win
        if not win.horiz and win.side.isVisible():
            pos = win.side.mapToGlobal(QPoint(win.side.width() + 8, 60))
        else:
            pos = win.mapToGlobal(QPoint((win.width() - self.width()) // 2, 80))
        scr = win.screen().availableGeometry()
        pos.setX(max(scr.left() + 8, min(pos.x(), scr.right() - self.width() - 8)))
        pos.setY(max(scr.top() + 8, min(pos.y(), scr.bottom() - self.height() - 8)))
        self.move(pos)
        self.show()
        self.raise_()

    def keyPressEvent(self, e):
        if e.key() == Qt.Key.Key_Escape:
            self.close()
            return
        super().keyPressEvent(e)

    def _before_close(self):
        self.win._sb_editor = None


class TbSeparator(QWidget):
    """A thin vertical divider line between toolbar buttons."""
    def __init__(self):
        super().__init__()
        self.setFixedSize(11, ToolIcon.SIZE)

    def paintEvent(self, e):
        p = QPainter(self)
        p.setPen(QPen(QColor(255, 255, 255, 46), 1))
        x = self.width() // 2
        p.drawLine(x, 9, x, self.height() - 9)
        p.end()


class TbSpacer(QWidget):
    """Flexible empty space that pushes the buttons on either side apart. Only visible while customising."""
    def __init__(self):
        super().__init__()
        self.editing = False
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setFixedHeight(ToolIcon.SIZE)
        self.setMinimumWidth(6)

    def set_editing(self, on):
        self.editing = on
        self.setMinimumWidth(34 if on else 6)
        self.update()

    def paintEvent(self, e):
        if not self.editing:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        c = QColor(255, 255, 255, 70)
        p.setPen(QPen(c, 1.3))
        y, x0, x1 = self.height() / 2.0, 8.0, self.width() - 8.0
        if x1 - x0 > 14:
            p.drawLine(QPointF(x0, y), QPointF(x1, y))
            p.drawLine(QPointF(x0, y), QPointF(x0 + 5, y - 4))
            p.drawLine(QPointF(x0, y), QPointF(x0 + 5, y + 4))
            p.drawLine(QPointF(x1, y), QPointF(x1 - 5, y - 4))
            p.drawLine(QPointF(x1, y), QPointF(x1 - 5, y + 4))
        p.end()


class TbOverlay(QWidget):
    """Sits on top of the toolbar while customising. It swallows clicks (so buttons don't fire), draws the dashed
    outlines and the drop marker, starts drags, and is the drop target for rearranging."""
    def __init__(self, ed):
        super().__init__(ed.win.toolbar)
        self.ed = ed
        self.hover = self.press = self.press_pos = self.marker = self.src = None
        self.setMouseTracking(True)
        self.setAcceptDrops(True)
        self.hide()

    def item_at(self, pos):
        for _i, iid, w in self.ed.visible_items():
            if iid != "addr" and self.ed.rect_of(w).contains(pos):
                return iid
        return None

    def mousePressEvent(self, e):
        if e.button() != Qt.MouseButton.LeftButton:
            return
        self.press_pos = e.position().toPoint()
        self.press = self.item_at(self.press_pos)
        if self.press is None:
            h = self.window().windowHandle()
            if h and not self.window().isFullScreen():
                h.startSystemMove()

    def mouseReleaseEvent(self, e):
        self.press = None

    def mouseMoveEvent(self, e):
        pos = e.position().toPoint()
        if (e.buttons() & Qt.MouseButton.LeftButton) and self.press is not None \
                and (pos - self.press_pos).manhattanLength() >= QApplication.startDragDistance():
            iid, self.press = self.press, None
            self.ed.drag_item(iid, self.ed.widget(iid))
            return
        h = self.item_at(pos)
        if h != self.hover:
            self.hover = h
            self.setCursor(Qt.CursorShape.OpenHandCursor if h else Qt.CursorShape.ArrowCursor)
            self.update()

    def leaveEvent(self, e):
        self.hover = None
        self.update()

    def contextMenuEvent(self, e):
        iid = self.item_at(e.pos())
        m = QMenu(self)
        if iid and tb_base(iid) not in TB_FIXED:
            m.addAction("Remove from toolbar", lambda: self.ed.remove(iid))
        m.addAction("Reset toolbar", self.ed.reset)
        m.addAction("Done", self.ed.stop)
        m.exec(e.globalPos())

    def _mime_id(self, e):
        if not e.mimeData().hasFormat(TB_MIME):
            return None
        return bytes(e.mimeData().data(TB_MIME)).decode("utf-8", "ignore")

    def dragEnterEvent(self, e):
        self.dragMoveEvent(e)

    def dragMoveEvent(self, e):
        if self._mime_id(e) is None:
            e.ignore()
            return
        e.acceptProposedAction()
        self.marker = self.ed.slot_at(e.position().toPoint().x())[1]
        self.update()

    def dragLeaveEvent(self, e):
        self.marker = None
        self.update()

    def dropEvent(self, e):
        iid = self._mime_id(e)
        if iid is None:
            return
        idx = self.ed.slot_at(e.position().toPoint().x())[0]
        self.marker = None
        e.acceptProposedAction()
        self.ed.pending = lambda: self.ed.place(iid, idx)
        self.update()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        for _i, iid, w in self.ed.visible_items():
            if iid == "addr":
                continue
            r = QRectF(self.ed.rect_of(w)).adjusted(0.5, 0.5, -0.5, -0.5)
            hot = iid == self.hover
            p.setPen(Qt.PenStyle.NoPen)
            if iid == self.src:
                p.setBrush(QColor(0, 0, 0, 120))
            elif hot:
                p.setBrush(accent_color(34))
            else:
                p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(r, rr(12), rr(12))
            pen = QPen(accent_color(170 if hot else 90), 1.2)
            pen.setDashPattern([3.0, 3.0])
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(r, rr(12), rr(12))
        if self.marker is not None:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(accent_color())
            p.drawRoundedRect(QRectF(self.marker - 1.5, 3, 3, self.height() - 6), 1.5, 1.5)
        p.end()


class TbTile(QWidget):
    """A hidden toolbar item (or a new separator / flexible space) in the customise tray; drag it onto the toolbar."""
    W, H = 74, 62

    def __init__(self, ed, iid):
        super().__init__()
        self.ed, self.iid, self.press_pos = ed, iid, None
        self.setFixedSize(self.W, self.H)
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self.setToolTip("Drag onto the toolbar")

    def label(self):
        return {"sep": "Separator", "space": "Flexible space"}.get(self.iid) or TB_ITEMS.get(self.iid, self.iid)

    def mousePressEvent(self, e):
        self.press_pos = e.position().toPoint() if e.button() == Qt.MouseButton.LeftButton else None

    def mouseMoveEvent(self, e):
        if (e.buttons() & Qt.MouseButton.LeftButton) and self.press_pos is not None \
                and (e.position().toPoint() - self.press_pos).manhattanLength() >= QApplication.startDragDistance():
            self.press_pos = None
            self.ed.drag_item(self.iid, self)

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 16))
        p.drawRoundedRect(QRectF(self.rect()), rr(12), rr(12))
        cx, cy, col = self.W / 2.0, 22.0, QColor(themed("#b5c6d4"))
        if self.iid == "sep":
            p.setPen(QPen(col, 1.5))
            p.drawLine(QPointF(cx, cy - 9), QPointF(cx, cy + 9))
        elif self.iid == "space":
            p.setPen(QPen(col, 1.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(cx - 12, cy), QPointF(cx + 12, cy))
            for s in (-1, 1):
                p.drawLine(QPointF(cx + 12 * s, cy), QPointF(cx + 7 * s, cy - 4))
                p.drawLine(QPointF(cx + 12 * s, cy), QPointF(cx + 7 * s, cy + 4))
        elif self.iid == "engine":
            pm = engine_icon(self.ed.win.engine).pixmap(20, 20)
            p.drawPixmap(int(cx - 10), int(cy - 10), pm)
        else:
            draw_glyph(p, TB_GLYPHS.get(self.iid, "dots"), QRectF(cx - 10, cy - 10, 20, 20), col, 1.7)
        p.setPen(QColor(themed("#8ea3b4")))
        f = p.font()
        f.setPixelSize(10)
        p.setFont(f)
        txt = QFontMetrics(f).elidedText(self.label(), Qt.TextElideMode.ElideRight, self.W - 8)
        p.drawText(QRectF(0, 38, self.W, 18), Qt.AlignmentFlag.AlignCenter, txt)
        p.end()


class TbPanel(QFrame):
    """The tray under the toolbar while customising: hidden items live here. Drop a toolbar button on it to remove it."""
    def __init__(self, ed):
        super().__init__()
        self.ed, self.tiles, self.cols, self.over = ed, [], 0, False
        self.setObjectName("tbpanel")
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setAcceptDrops(True)
        lay = QVBoxLayout(self)
        lay.setContentsMargins(16, 12, 16, 14)
        lay.setSpacing(8)
        head = QHBoxLayout()
        title = QLabel("Customize toolbar")
        title.setObjectName("tbtitle")
        reset = QPushButton("Reset")
        reset.setObjectName("tbreset")
        done = QPushButton("Done")
        done.setObjectName("tbdone")
        for b in (reset, done):
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        reset.clicked.connect(lambda: ed.reset())
        done.clicked.connect(lambda: ed.stop())
        head.addWidget(title)
        head.addStretch(1)
        head.addWidget(reset)
        head.addWidget(done)
        hint = QLabel("Drag buttons on the toolbar to rearrange them. Drop them here to remove them, "
                      "or drag items from here onto the toolbar to add them.")
        hint.setObjectName("tbhint")
        hint.setWordWrap(True)
        self.grid = QGridLayout()
        self.grid.setSpacing(8)
        lay.addLayout(head)
        lay.addWidget(hint)
        lay.addLayout(self.grid)
        self.hide()

    def refresh(self):
        for t in self.tiles:
            t.hide()
            t.deleteLater()
        self.tiles = [TbTile(self.ed, i) for i in self.ed.hidden_ids() + ["sep", "space"]]
        self.cols = 0
        self.arrange()

    def arrange(self):
        cols = max(1, (self.width() - 32) // (TbTile.W + 8))
        if cols == self.cols:
            return
        self.cols = cols
        while self.grid.count():
            self.grid.takeAt(0)
        for c in range(40):
            self.grid.setColumnStretch(c, 0)
        for n, t in enumerate(self.tiles):
            self.grid.addWidget(t, n // cols, n % cols, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop)
            t.show()
        self.grid.setColumnStretch(cols, 1)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self.arrange()

    def dragEnterEvent(self, e):
        self.dragMoveEvent(e)

    def dragMoveEvent(self, e):
        if e.mimeData().hasFormat(TB_MIME):
            e.acceptProposedAction()
            if not self.over:
                self.over = True
                self.update()
        else:
            e.ignore()

    def dragLeaveEvent(self, e):
        self.over = False
        self.update()

    def dropEvent(self, e):
        iid = bytes(e.mimeData().data(TB_MIME)).decode("utf-8", "ignore")
        self.over = False
        self.update()
        e.acceptProposedAction()
        self.ed.pending = lambda: self.ed.remove(iid)

    def paintEvent(self, e):
        super().paintEvent(e)
        if self.over:
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            pen = QPen(accent_color(190), 1.4)
            pen.setDashPattern([4.0, 4.0])
            p.setPen(pen)
            p.setBrush(accent_color(24))
            p.drawRoundedRect(QRectF(self.rect()).adjusted(1, 1, -1, -1), rr(16), rr(16))
            p.end()


class ToolbarEditor(QObject):
    """Owns the toolbar's item order (saved in settings.json) and the drag-and-drop customise mode."""
    def __init__(self, win):
        super().__init__(win)
        self.win = win
        self.editing = False
        self.pending = None
        self.order = clean_toolbar(win.settings.get("toolbar"))
        self.seq = 1 + max([int(x.split("#")[1]) for x in self.order if "#" in x] or [0])
        self.widgets = {"addr": win.addr, "side": win.btn_side, "back": win.btn_back, "fwd": win.btn_fwd,
                        "reload": win.btn_reload, "engine": win.btn_engine, "speed": win.btn_speed,
                        "vpn": win.btn_vpn, "ext": win.btn_ext, "star": win.btn_star, "ytdl": win.btn_ytdl, "site": win.btn_site,
                        "scratch": win.scratch_btn, "tabsearch": win.search_btn, "uistyle": win.btn_style, "menu": win.btn_menu}
        if not win.settings.get("tb_tabsearch_seeded"):
            win.settings["tb_tabsearch_seeded"] = True
            if "tabsearch" not in self.order:
                at = self.order.index("scratch") + 1 if "scratch" in self.order else max(0, len(self.order) - 1)
                self.order.insert(at, "tabsearch")
                if isinstance(win.settings.get("toolbar"), list):
                    win.settings["toolbar"] = list(self.order)
            jsave("settings.json", win.settings)
        if not win.settings.get("tb_site_seeded"):
            win.settings["tb_site_seeded"] = True
            if isinstance(win.settings.get("toolbar"), list):
                at = self.order.index("star") + 1 if "star" in self.order else max(0, len(self.order) - 1)
                for k, iid in enumerate([i for i in ("site",) if i not in self.order]):
                    self.order.insert(at + k, iid)
                win.settings["toolbar"] = list(self.order)
            jsave("settings.json", win.settings)
        if not win.settings.get("tb_ytdl_seeded"):
            win.settings["tb_ytdl_seeded"] = True
            if isinstance(win.settings.get("toolbar"), list):
                at = self.order.index("star") + 1 if "star" in self.order else max(0, len(self.order) - 1)
                for k, iid in enumerate([i for i in ("ytdl",) if i not in self.order]):
                    self.order.insert(at + k, iid)
                win.settings["toolbar"] = list(self.order)
            jsave("settings.json", win.settings)
        self.overlay = TbOverlay(self)
        self.panel = TbPanel(self)
        self._tick = QTimer(self)
        self._tick.setInterval(40)
        self._tick.timeout.connect(self._sync)

    def widget(self, iid):
        w = self.widgets.get(iid)
        if w is None:
            w = TbSeparator() if tb_base(iid) == "sep" else TbSpacer()
            w.setParent(self.win.toolbar)
            self.widgets[iid] = w
        return w

    def apply(self):
        """Put the toolbar widgets in the saved order. Items that are off the toolbar are hidden."""
        win, lay = self.win, self.win.tb_lay
        if win.side_tb_active():
            self._apply_side()
            return
        win.winreveal.set_active(False)
        horiz = bool(getattr(win, "horiz", False))
        self._side_clear()
        for w in self.widgets.values():
            lay.removeWidget(w)
        lay.removeWidget(win.drag_zone)
        lay.removeWidget(win.winctl)
        win.strip_lay.removeWidget(win.winctl)
        for i in reversed(range(lay.count())):
            if lay.itemAt(i).spacerItem() is not None:
                lay.takeAt(i)
        mac = UI["mode"] == "mac"
        win.addr.setMaximumWidth(680 if mac else 16777215)
        if mac and not horiz:
            lay.addWidget(win.winctl)
            lay.addSpacing(12)
        for iid in [i for i in self.widgets if "#" in i and i not in self.order]:
            w = self.widgets.pop(iid)
            w.hide()
            w.deleteLater()
        shown = set()
        caps, run = [], []
        for iid in self.order:
            if (iid == "side" and horiz) or (iid in TB_SIDE_ONLY and not horiz):
                continue
            w = self.widget(iid)
            base = tb_base(iid)
            if mac and base == "addr":
                caps.append(run)
                run = []
                lay.addStretch(1)
            lay.addWidget(w, TB_STRETCH.get(base, 0))
            if mac:
                if base == "addr":
                    lay.addStretch(1)
                elif base in ("sep", "space"):
                    caps.append(run)
                    run = []
                else:
                    run.append(w)
                    if iid == "side":
                        caps.append(run)
                        run = []
                        lay.addSpacing(10)
            w.show()
            if isinstance(w, TbSpacer):
                w.set_editing(self.editing)
            shown.add(iid)
        caps.append(run)
        win.toolbar.caps = [c for c in caps if c] if mac else []
        lay.addWidget(win.drag_zone)
        if horiz:
            if mac:
                win.strip_lay.insertWidget(0, win.winctl)
            else:
                win.strip_lay.addWidget(win.winctl)
        elif not mac:
            lay.addWidget(win.winctl)
        win.winctl.show()
        win.toolbar.update()
        for iid, w in self.widgets.items():
            if iid not in shown and not (iid in TB_SIDE_ONLY and not horiz):
                w.hide()
        if self.editing:
            self.panel.refresh()
            self.overlay.update()

    def _side_clear(self):
        """Take every toolbar widget back out of Compact mode's sidebar header (so they can go back on the toolbar)."""
        win = self.win
        for lay in (win.st_title_lay, win.st_addr_lay):
            for w in list(self.widgets.values()) + [win.winctl]:
                lay.removeWidget(w)
            for i in reversed(range(lay.count())):
                if lay.itemAt(i).spacerItem() is not None:
                    lay.takeAt(i)
        win.st_icons.set_items([])

    def _apply_side(self):
        """Compact mode, like Zen: the sidebar's top row holds the menu and sidebar buttons on the left and back, forward and
        reload on the right, with the address bar under it. Nothing else from the toolbar is shown, and the window buttons
        are not on it: WinReveal slides them in when the pointer reaches the window's top edge."""
        win, lay = self.win, self.win.tb_lay
        for w in self.widgets.values():
            lay.removeWidget(w)
        lay.removeWidget(win.drag_zone)
        lay.removeWidget(win.winctl)
        win.strip_lay.removeWidget(win.winctl)
        for i in reversed(range(lay.count())):
            if lay.itemAt(i).spacerItem() is not None:
                lay.takeAt(i)
        for iid in [i for i in self.widgets if "#" in i and i not in self.order]:
            w = self.widgets.pop(iid)
            w.hide()
            w.deleteLater()
        self._side_clear()
        win.addr.setMaximumWidth(16777215)
        title, addr_row = win.st_title_lay, win.st_addr_lay
        for iid in ("menu", "side"):
            title.addWidget(self.widget(iid))
        title.addStretch(1)
        for iid in ("back", "fwd", "reload"):
            title.addWidget(self.widget(iid))
        addr_row.addWidget(win.addr, 1)
        win.st_icons.hide()
        shown = {"menu", "side", "back", "fwd", "reload", "addr"}
        for iid in shown:
            self.widget(iid).show()
        for iid, w in self.widgets.items():
            if iid not in shown and iid not in TB_SIDE_ONLY:
                w.hide()
        win.toolbar.caps = []
        win.toolbar.update()
        win.winreveal.set_active(True)

    def available(self, iid):
        horiz = bool(getattr(self.win, "horiz", False))
        return not ((iid == "side" and horiz) or (iid in TB_SIDE_ONLY and not horiz))

    def hidden_ids(self):
        return [i for i in TB_ITEMS if i not in self.order and self.available(i)]

    def visible_items(self):
        out = []
        for i, iid in enumerate(self.order):
            w = self.widgets.get(iid)
            if w is not None and w.isVisibleTo(self.win.toolbar):
                out.append((i, iid, w))
        return out

    def rect_of(self, w):
        """A toolbar item's rectangle in toolbar coordinates (in the macOS style the buttons sit inside glass groups,
        so their own geometry() is relative to the group, not to the toolbar the overlay is drawn on)."""
        return QRect(w.mapTo(self.win.toolbar, QPoint(0, 0)), w.size())

    def slot_at(self, x):
        """Where would an item dropped at toolbar x land? -> (index into self.order, x of the drop marker)."""
        vis = self.visible_items()
        if not vis:
            return 0, 6
        k = sum(1 for _i, _id, w in vis if self.rect_of(w).center().x() < x)
        if k < len(vis):
            return vis[k][0], self.rect_of(vis[k][2]).left() - 3
        return vis[-1][0] + 1, self.rect_of(vis[-1][2]).right() + 4

    def set_order(self, order):
        self.order = clean_toolbar(order)
        self.win.settings["toolbar"] = list(self.order)
        jsave("settings.json", self.win.settings)
        self.apply()

    def place(self, iid, idx):
        if not (iid in TB_ITEMS or iid == "addr" or iid in ("sep", "space") or _TB_INST.match(iid)):
            return
        order = list(self.order)
        if iid in order:
            s = order.index(iid)
            order.pop(s)
            if s < idx:
                idx -= 1
        elif iid in ("sep", "space"):
            iid = "%s#%d" % (iid, self.seq)
            self.seq += 1
        order.insert(max(0, min(idx, len(order))), iid)
        self.set_order(order)

    def remove(self, iid):
        if iid not in self.order:
            return
        if tb_base(iid) in TB_FIXED:
            self.win.toast("That one has to stay on the toolbar", 2500)
            return
        self.set_order([i for i in self.order if i != iid])

    def reset(self):
        self.set_order(list(TB_DEFAULT))

    def drag_item(self, iid, src):
        drag = QDrag(self.overlay)
        mime = QMimeData()
        mime.setData(TB_MIME, iid.encode())
        drag.setMimeData(mime)
        pm = src.grab()
        ghost = QPixmap(pm.size())
        ghost.fill(Qt.GlobalColor.transparent)
        gp = QPainter(ghost)
        gp.setOpacity(0.85)
        gp.drawPixmap(0, 0, pm)
        gp.end()
        drag.setPixmap(ghost)
        drag.setHotSpot(QPoint(pm.width() // 2, pm.height() // 2))
        self.overlay.src = iid if iid in self.order else None
        self.overlay.update()
        self.pending = None
        drag.exec(Qt.DropAction.MoveAction)
        self.overlay.src = self.overlay.marker = None
        self.overlay.update()
        fn, self.pending = self.pending, None
        if fn:
            QTimer.singleShot(0, fn)

    def _sync(self):
        self.overlay.setGeometry(0, 0, max(0, self.win.drag_zone.x()), self.win.toolbar.height())
        self.overlay.raise_()
        self.overlay.update()

    def start(self):
        if self.editing:
            return
        if self.win.side_tb_active():
            self.win.toast("Turn off Compact mode to customize the toolbar", 3000)
            return
        if self.win.isFullScreen() or not self.win.toolbar.isVisible():
            self.win.toast("Leave full screen to customize the toolbar", 3000)
            return
        self.editing = True
        self.win.addr.clearFocus()
        for w in self.widgets.values():
            if isinstance(w, TbSpacer):
                w.set_editing(True)
        self.panel.refresh()
        self.panel.show()
        self.overlay.show()
        self._sync()
        self._tick.start()

    def stop(self):
        if not self.editing:
            return
        self.editing = False
        self._tick.stop()
        self.overlay.hide()
        self.panel.hide()
        for w in self.widgets.values():
            if isinstance(w, TbSpacer):
                w.set_editing(False)


