# ====================================================================================================
# 49  DOWNLOAD SHELF
# ====================================================================================================

DL_FILE = "downloads.json"
DL_SHOW = 40
DL_TYPES = {
    "image": ("Image", "Images", ".png .jpg .jpeg .gif .webp .bmp .svg .heic .heif .avif .tif .tiff .ico .psd", "#b38cf0", "image"),
    "video": ("Video", "Videos", ".mp4 .mkv .mov .avi .webm .m4v .wmv .flv .mpg .mpeg", "#f08c9a", "play"),
    "audio": ("Audio", "Audio", ".mp3 .flac .wav .ogg .m4a .aac .opus .wma .aiff", "#f0b86e", "music"),
    "doc": ("Document", "Documents", ".pdf .doc .docx .odt .rtf .txt .md .epub .mobi .ppt .pptx .key .odp .xls .xlsx "
            ".csv .ods .pages .numbers", "#6ec1f0", "text"),
    "archive": ("Archive", "Archives", ".zip .rar .7z .tar .gz .tgz .bz2 .xz .zst .iso .img", "#e6c66a", "archive"),
    "program": ("Program", "Programs", ".exe .msi .msix .dmg .pkg .deb .rpm .appimage .apk .bat .cmd .sh .ps1 .jar .run "
                ".com .scr", "#f0907a", "speed_turbo"),
    "code": ("Code", "Code", ".py .js .ts .json .html .htm .css .c .cpp .h .java .go .rs .rb .php .sql .xml .yml .yaml "
             ".ipynb .toml", "#7ef0b0", "code"),
    "ext": ("Extension", "", ".xpi .crx", "#7ef0d0", "puzzle"),
    "other": ("File", "", "", "#8ea3b4", "file"),
}
DL_EXT = {e: k for k, v in DL_TYPES.items() for e in v[2].split()}
DL_LAUNCH = set(".exe .bat .cmd .com .scr .pif .vbs .vbe .jse .wsf .wsh .hta .cpl .lnk .reg .ps1 .msi .jar".split())
DL_SCRIPTY = set(".scr .pif .vbs .vbe .jse .wsf .wsh .hta .cpl .lnk .reg .bat .cmd .com".split())
DL_AMBER, DL_RED = "#f0b86e", "#f08a8a"


def dl_kind(name):
    return DL_EXT.get(os.path.splitext(str(name).lower())[1], "other")


def dl_assess(name, head=b""):
    """(level, note) for a finished download. 0 = fine, 1 = worth a second look, 2 = looks dangerous.
    Judged from the file name and its first few bytes only; nothing is uploaded anywhere."""
    low = name.lower()
    stem, ext = os.path.splitext(low)
    kind = DL_EXT.get(ext, "other")
    inner = DL_EXT.get(os.path.splitext(stem)[1], "other")
    if ext in DL_LAUNCH and inner in ("image", "video", "audio", "doc", "archive"):
        lab = DL_TYPES[inner][0].lower()
        return 2, "Disguised: named like %s %s, but it's a program" % ("an" if lab[0] in "aeiou" else "a", lab)
    plain = kind in ("image", "video", "audio", "archive", "doc") and ext not in (".txt", ".md", ".csv", ".rtf")
    if plain and (head[:2] == b"MZ" or head[:4] in (b"\x7fELF", b"\xcf\xfa\xed\xfe", b"\xca\xfe\xba\xbe")):
        return 2, "Contents look like a program, not a %s file" % ext.lstrip(".").upper()
    if (kind in ("image", "video", "audio", "archive") or ext in (".pdf", ".docx", ".xlsx", ".pptx")) \
            and head.lstrip()[:15].lower().startswith((b"<!doctype html", b"<html")):
        return 1, "Probably an error page, not a %s file. The link may have expired" % ext.lstrip(".").upper()
    if ext in DL_SCRIPTY:
        return 2, "Script or launcher: it can run code on your computer"
    return 0, ""


def dl_span(s):
    s = max(0, int(s))
    if s < 60:
        return "%ds" % s
    if s < 3600:
        return "%dm %02ds" % (s // 60, s % 60)
    return "%dh %02dm" % (s // 3600, s % 3600 // 60)


class DlItem:
    """One download (live or finished). Plain data, so it survives the Qt request object being deleted."""
    def __init__(self, **kw):
        self.id = secrets.token_hex(4)
        self.req = None
        self.name, self.path, self.url, self.err, self.note = "", "", "", "", ""
        self.ts = time.time()
        self.size = self.total = self.got = 0
        self.state = "active"
        self.kind = "other"
        self.risk = 0
        self.speed = 0.0
        self.last = (0, 0.0)
        self.job = None
        self.yt = None
        self.stage = ""
        self.__dict__.update(kw)

    def live(self):
        return self.state in ("active", "paused")

    def exists(self):
        return bool(self.path) and os.path.exists(self.path)


class HScroll(QScrollArea):
    """Scrolls sideways; the mouse wheel moves it left and right."""
    def wheelEvent(self, e):
        d = e.angleDelta()
        step = d.x() if abs(d.x()) > abs(d.y()) else d.y()
        sb = self.horizontalScrollBar()
        sb.setValue(sb.value() - step)
        e.accept()


class DlBadge(QWidget):
    """A file-type tile: an image thumbnail once a picture has arrived, otherwise a coloured glyph."""
    def __init__(self, it):
        super().__init__()
        self.it, self.pm, self.tried = it, None, False
        self.setFixedSize(40, 40)

    def load_thumb(self):
        it = self.it
        if self.tried or it.kind != "image" or it.state != "done" or it.size > 12 * 1024 * 1024 \
                or it.name.lower().endswith((".svg", ".psd", ".ico")):
            return
        self.tried = True
        try:
            rd = QImageReader(it.path)
            rd.setAutoTransform(True)
            sz = rd.size()
            if not sz.isValid():
                return
            rd.setScaledSize(sz.scaled(80, 80, Qt.AspectRatioMode.KeepAspectRatioByExpanding))
            img = rd.read()
            if not img.isNull():
                self.pm = QPixmap.fromImage(img)
                self.update()
        except Exception:
            self.pm = None

    def paintEvent(self, e):
        it = self.it
        _label, _folder, _exts, col, glyph = DL_TYPES.get(it.kind, DL_TYPES["other"])
        c = QColor(col)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        r = QRectF(self.rect())
        if self.pm is not None:
            clip = QPainterPath()
            clip.addRoundedRect(r, rr(11), rr(11))
            p.setClipPath(clip)
            side = min(self.pm.width(), self.pm.height())
            p.drawPixmap(r, self.pm, QRectF((self.pm.width() - side) / 2, (self.pm.height() - side) / 2, side, side))
            p.setClipping(False)
        else:
            bg = QColor(c)
            bg.setAlpha(40)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(bg)
            p.drawRoundedRect(r, rr(11), rr(11))
            draw_glyph(p, "save" if it.live() else glyph, QRectF(r.center().x() - 10, r.center().y() - 10, 20, 20), c, 1.7)
        if it.state == "done" and it.risk >= 2:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(DL_AMBER))
            p.drawEllipse(QRectF(r.right() - 15, r.bottom() - 15, 15, 15))
            draw_glyph(p, "warn", QRectF(r.right() - 13.5, r.bottom() - 13.5, 12, 12), QColor("#101b26"), 1.7)
        p.end()


class DlChip(QFrame):
    """One download on the shelf: badge, name, live status line, a progress bar along the bottom and two buttons.
    Click = open (or retry); drag it out to hand the file to another app; right-click for everything else."""
    W, H = 300, 58

    def __init__(self, shelf, it):
        super().__init__()
        self.s, self.it = shelf, it
        self._press = None
        self._css = ""
        self.setObjectName("dlchip")
        self.setFixedSize(self.W, self.H)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(8, 8, 6, 11)
        lay.setSpacing(9)
        self.badge = DlBadge(it)
        tw = QWidget()
        tl = QVBoxLayout(tw)
        tl.setContentsMargins(0, 0, 0, 0)
        tl.setSpacing(2)
        self.title, self.sub = ElidedLabel(), ElidedLabel()
        self.title.setObjectName("mediatitle")
        self.sub.setObjectName("mediasub")
        tl.addStretch(1)
        tl.addWidget(self.title)
        tl.addWidget(self.sub)
        tl.addStretch(1)
        self.b1, self.b2 = GlyphButton("pause", ""), GlyphButton("stop", "")
        self.b1.clicked.connect(self._first)
        self.b2.clicked.connect(self._second)
        lay.addWidget(self.badge, 0, Qt.AlignmentFlag.AlignVCenter)
        lay.addWidget(tw, 1)
        lay.addWidget(self.b1)
        lay.addWidget(self.b2)
        self.sync()

    def sync(self):
        it = self.it
        tone = ""
        if it.live():
            got, tot = it.got, it.total
            span = human_size(got) + (" of " + human_size(tot) if tot > 0 else "")
            if it.state == "paused":
                sub = "Paused · " + span
            else:
                sub = span
                if it.speed > 1:
                    sub += " · %s/s" % human_size(it.speed)
                    if tot > got > 0:
                        sub += " · %s left" % dl_span((tot - got) / it.speed)
            first = ("play", "Resume") if it.state == "paused" else ("pause", "Pause")
            second = ("stop", "Cancel download")
            if it.job is not None:
                sub = it.stage or ("Starting\u2026" if it.got <= 0 else sub)
        elif it.state == "failed":
            sub, tone = "Failed · " + (it.err or "interrupted"), "bad"
            first, second = ("reload", "Try again"), ("stop", "Remove from list")
        else:
            ok = it.exists()
            if not ok:
                sub, first = "Moved or deleted", ("reload", "Download again")
            else:
                self.badge.load_thumb()
                first = ("folder", "Show in folder")
                if it.risk >= 1 and it.note:
                    sub, tone = it.note, "warn"
                else:
                    sub = "%s · %s · %s" % (DL_TYPES.get(it.kind, DL_TYPES["other"])[0], human_size(it.size), ago(it.ts))
            second = ("stop", "Remove from list")
        css = {"bad": "color:%s;" % DL_RED, "warn": "color:%s;" % DL_AMBER}.get(tone, "")
        if css != self._css:
            self._css = css
            self.sub.setStyleSheet(css)
        self.title.setText(it.name)
        self.sub.setText(sub)
        self.b1.setVisible(not (it.live() and it.job is not None))
        for b, (kind, tip) in ((self.b1, first), (self.b2, second)):
            if b.kind != kind:
                b.kind = kind
            b.setToolTip(tip)
            b.update()
        self.setToolTip("%s\n%s" % (it.path or it.name, it.note) if it.note else (it.path or it.name))
        self.badge.update()
        self.update()

    def paintEvent(self, e):
        super().paintEvent(e)
        it = self.it
        if it.live():
            col = accent_color() if it.state == "active" else QColor(142, 163, 180)
        elif it.state == "failed":
            col = QColor(DL_RED)
        elif it.risk >= 2:
            col = QColor(DL_AMBER)
        else:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        track = QRectF(12, self.height() - 8, self.width() - 24, 3)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 26))
        p.drawRoundedRect(track, 1.5, 1.5)
        fill = QRectF(track)
        if it.live():
            if it.total > 0:
                fill.setWidth(track.width() * max(0.0, min(1.0, it.got / it.total)))
            else:
                seg = track.width() * 0.3
                fill = QRectF(track.x() + (track.width() - seg) * (0.5 + 0.5 * math.sin(time.time() * 2.2)), track.y(), seg, 3)
        p.setBrush(col)
        p.drawRoundedRect(fill, 1.5, 1.5)
        p.end()

    def _first(self):
        it, s = self.it, self.s
        if it.live():
            s.toggle_pause(it)
        elif it.state == "failed" or not it.exists():
            s.retry(it)
        else:
            s.reveal_item(it)

    def _second(self):
        if self.it.live():
            self.s.cancel(self.it)
        else:
            self.s.remove(self.it)

    def mousePressEvent(self, e):
        self.s.pin()
        self._press = e.position().toPoint() if e.button() == Qt.MouseButton.LeftButton else None
        super().mousePressEvent(e)

    def mouseMoveEvent(self, e):
        if (self._press is not None and (e.buttons() & Qt.MouseButton.LeftButton)
                and (e.position().toPoint() - self._press).manhattanLength() > QApplication.startDragDistance() * 2):
            self._press = None
            self.drag_out()
            return
        super().mouseMoveEvent(e)

    def mouseReleaseEvent(self, e):
        if (self._press is not None and e.button() == Qt.MouseButton.LeftButton
                and self.rect().contains(e.position().toPoint())):
            self._press = None
            it = self.it
            if it.state == "done" and it.exists():
                self.s.open_item(it)
            elif it.state == "failed" or (it.state == "done" and not it.exists()):
                self.s.retry(it)
            return
        self._press = None
        super().mouseReleaseEvent(e)

    def drag_out(self):
        it = self.it
        if not (it.state == "done" and it.exists()):
            return
        md = QMimeData()
        md.setUrls([QUrl.fromLocalFile(it.path)])
        d = QDrag(self)
        d.setMimeData(md)
        d.setPixmap(self.grab())
        d.setHotSpot(QPoint(30, 28))
        d.exec(Qt.DropAction.CopyAction)

    def contextMenuEvent(self, e):
        it, s = self.it, self.s
        here = it.state == "done" and it.exists()
        m = QMenu(self)
        if here:
            m.addAction("Open", lambda: s.open_item(it))
            m.addAction("Show in folder", lambda: s.reveal_item(it))
            m.addAction("Copy path", lambda: QApplication.clipboard().setText(it.path))
            m.addAction("Copy SHA-256", lambda: s.copy_hash(it))
        if it.live():
            if it.job is None:
                m.addAction("Resume" if it.state == "paused" else "Pause", lambda: s.toggle_pause(it))
            m.addAction("Cancel download", lambda: s.cancel(it))
        elif not here:
            m.addAction("Download again", lambda: s.retry(it))
        if it.url:
            m.addAction("Copy download link", lambda: QApplication.clipboard().setText(it.url))
        m.addSeparator()
        m.addAction("Remove from list", lambda: s.remove(it))
        if here:
            m.addAction("Delete file…", lambda: s.delete_file(it))
        m.exec(e.globalPos())


class DownloadShelf(QFrame):
    """A shelf that slides up over the bottom of the page whenever a download starts. Shows live progress, speed and
    time left, spots disguised or broken files, can sort downloads into folders by type, and remembers what you got."""
    H = 90
    hashed = pyqtSignal(str, str)

    def __init__(self, browser, parent):
        super().__init__(parent)
        self.b = browser
        self.setObjectName("dlshelf")
        self.items = []
        self.chips = {}
        self.reserved = set()
        self.want = False
        self.pinned = False
        self.hovered = False
        self.suppressed = False
        self.reveal = 0.0

        lay = QHBoxLayout(self)
        lay.setContentsMargins(14, 10, 10, 10)
        lay.setSpacing(10)
        lay.addWidget(GlyphTile("save", 22, tile=False))
        info = QVBoxLayout()
        info.setContentsMargins(0, 0, 0, 0)
        info.setSpacing(1)
        title = QLabel("Downloads")
        title.setObjectName("scratchtitle")
        self.sum = QLabel()
        self.sum.setObjectName("mediasub")
        info.addStretch(1)
        info.addWidget(title)
        info.addWidget(self.sum)
        info.addStretch(1)
        iw = QWidget()
        iw.setLayout(info)
        iw.setFixedWidth(118)
        lay.addWidget(iw)

        self.scroll = HScroll()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.scroll.setFixedHeight(DlChip.H + 10)
        inner = QWidget()
        self.row = QHBoxLayout(inner)
        self.row.setContentsMargins(0, 0, 0, 0)
        self.row.setSpacing(8)
        self.empty = QLabel("Files you download show up here")
        self.empty.setObjectName("mediasub")
        self.row.addWidget(self.empty)
        self.row.addStretch(1)
        self.scroll.setWidget(inner)
        lay.addWidget(self.scroll, 1)

        self.more = GlyphButton("dots", "Download settings")
        self.more.clicked.connect(self.show_menu)
        close = FadeButton(8)
        close.setObjectName("close")
        close.setText("✕")
        close.setToolTip("Close")
        close.setCursor(Qt.CursorShape.PointingHandCursor)
        close.clicked.connect(lambda: self.set_open(False))
        lay.addWidget(self.more, 0, Qt.AlignmentFlag.AlignVCenter)
        lay.addWidget(close, 0, Qt.AlignmentFlag.AlignVCenter)

        self.tick = QTimer(self)
        self.tick.setInterval(250)
        self.tick.timeout.connect(self._tick)
        self.hide_timer = QTimer(self)
        self.hide_timer.setSingleShot(True)
        self.hide_timer.timeout.connect(self._autohide)
        self._anim = QVariantAnimation(self)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._anim.valueChanged.connect(self._set_reveal)
        self._anim.finished.connect(self._anim_done)
        self.hashed.connect(self._hashed)
        if getattr(browser, "stack", None) is not None:
            browser.stack.installEventFilter(self)

        self._load()
        self._summary()
        self.hide()

    def _load(self):
        data = jload(DL_FILE, [])
        for e in (data if isinstance(data, list) else [])[:DL_SHOW]:
            try:
                if not (isinstance(e, dict) and e.get("path") and e.get("name")):
                    continue
                kind = e.get("kind") if e.get("kind") in DL_TYPES else dl_kind(e["name"])
                self.items.append(DlItem(id=str(e.get("id") or secrets.token_hex(4)), name=str(e["name"]),
                                         path=str(e["path"]), url=str(e.get("url", "")), ts=float(e.get("ts", 0)),
                                         size=int(e.get("size", 0)), kind=kind, risk=int(e.get("risk", 0)),
                                         note=str(e.get("note", "")), state="done",
                                         yt=e.get("yt") if isinstance(e.get("yt"), dict) else None))
            except (TypeError, ValueError):
                continue
        for it in reversed(self.items):
            self._chip(it)

    def save(self):
        jsave(DL_FILE, [{"id": i.id, "name": i.name, "path": i.path, "url": i.url, "ts": i.ts, "size": i.size,
                         "kind": i.kind, "risk": i.risk, "note": i.note, "yt": i.yt}
                        for i in self.items if i.state == "done"][:DL_SHOW])

    def _chip(self, it):
        chip = DlChip(self, it)
        self.chips[it.id] = chip
        self.row.insertWidget(0, chip)
        return chip

    @staticmethod
    def _unique(folder, name, taken):
        m = re.match(r"^(.*?)((?:\.tar)?\.[^.]+)$", name)
        stem, ext = (m.group(1), m.group(2)) if m else (name, "")
        n, cand = 1, name
        while (folder / cand).exists() or str(folder / cand) in taken or (folder / (cand + ".crdownload")).exists():
            n += 1
            cand = "%s (%d)%s" % (stem, n, ext)
        return cand

    def add(self, req):
        """Take over a download: pick its folder and a name that won't overwrite anything, accept it and show it."""
        st = self.b.settings
        raw = safe_name(req.downloadFileName() or "download", "download")
        if not os.path.splitext(raw)[1]:
            guess = mimetypes.guess_extension((req.mimeType() or "").split(";")[0].strip())
            if guess and guess != ".bin":
                raw += guess
        kind = dl_kind(raw)
        base = Path.home() / "Downloads"
        folder = base / DL_TYPES[kind][1] if (st.get("dl_sort", False) and DL_TYPES[kind][1]) else base
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError:
            folder = base
            folder.mkdir(exist_ok=True)
        name = self._unique(folder, raw, self.reserved)
        self.reserved.add(str(folder / name))
        req.setDownloadDirectory(str(folder))
        req.setDownloadFileName(name)
        req.accept()
        it = DlItem(req=req, name=name, path=str(folder / name), url=req.url().toString(), kind=kind,
                    total=max(0, req.totalBytes()))
        self.items.insert(0, it)
        self._chip(it)
        while len(self.items) > DL_SHOW:
            old = next((i for i in reversed(self.items) if not i.live()), None)
            if old is None:
                break
            self._drop(old)

        def hook(*_a, i=it):
            self._state(i)
        req.stateChanged.connect(hook)
        req.isPausedChanged.connect(hook)
        self.tick.start()
        if not self.suppressed:
            self.set_open(True)
        self._summary()
        self._arm()
        return it

    def add_job(self, job, title, url, opt):
        """Show a yt-dlp video download on the shelf, with the same progress bar, cancel and open buttons as any other download."""
        audio = bool(opt.get("audio"))
        ext = opt.get("ext") or ("m4a" if audio else "mp4")
        name = safe_name(title or "video", "video") + "." + ext
        slim = {k: opt[k] for k in ("key", "label", "sel", "audio", "mp3", "ext", "size") if k in opt}
        it = DlItem(job=job, name=name, url=url, kind="audio" if audio else "video", total=int(opt.get("size") or 0),
                    yt={"url": url, "title": title or "", "opt": slim})
        self.items.insert(0, it)
        self._chip(it)
        while len(self.items) > DL_SHOW:
            old = next((i for i in reversed(self.items) if not i.live()), None)
            if old is None:
                break
            self._drop(old)
        job.progress.connect(lambda got, tot, sp, stage, i=it: self._job_progress(i, got, tot, sp, stage))
        job.ended.connect(lambda ok, path, err, i=it: self._job_done(i, ok, path, err))
        self.tick.start()
        if not self.suppressed:
            self.set_open(True)
        self._summary()
        self._arm()
        return it

    def _job_progress(self, it, got, total, speed, stage):
        if it not in self.items:
            return
        it.got, it.speed, it.stage = int(got), float(speed), stage
        if total > 0:
            it.total = int(total)
        chip = self.chips.get(it.id)
        if chip is not None:
            chip.sync()
        self._summary()

    def _job_done(self, it, ok, path, err):
        it.job, it.speed, it.stage = None, 0.0, ""
        if it not in self.items:
            return
        if ok:
            it.state, it.path, it.name = "done", path, os.path.basename(path)
            if dl_kind(it.name) != "other":
                it.kind = dl_kind(it.name)
            try:
                it.size = os.path.getsize(path)
            except OSError:
                it.size = 0
            it.risk, it.note, it.ts = 0, "", time.time()
            self.save()
            self.b.toast("Saved %s" % it.name, 4000)
        else:
            it.state, it.err = "failed", err
        self._refresh(it)

    def _state(self, it):
        req = it.req
        if req is None:
            return
        S = QWebEngineDownloadRequest.DownloadState
        try:
            st = req.state()
            it.got = req.receivedBytes()
            if req.totalBytes() > 0:
                it.total = req.totalBytes()
            if st == S.DownloadCompleted:
                it.name = req.downloadFileName()
                it.path = str(Path(req.downloadDirectory()) / it.name)
                self._finish(it)
                return
            if st == S.DownloadCancelled:
                self.remove(it)
                return
            if st == S.DownloadInterrupted:
                it.state, it.err = "failed", req.interruptReasonString() or ""
                it.req = None
                self.reserved.discard(it.path)
            else:
                it.state = "paused" if req.isPaused() else "active"
        except RuntimeError:
            if it.live():
                it.state, it.req = "failed", None
        self._refresh(it)

    def _finish(self, it):
        it.state, it.req, it.speed = "done", None, 0.0
        self.reserved.discard(it.path)
        try:
            it.size = os.path.getsize(it.path)
            with open(it.path, "rb") as f:
                head = f.read(64)
        except OSError:
            head = b""
        it.risk, it.note = dl_assess(it.name, head) if self.b.settings.get("dl_scan", True) else (0, "")
        it.ts = time.time()
        self.save()
        self._refresh(it)
        if it.risk >= 2 and self.want is False and not self.suppressed:
            self.set_open(True)

    def _refresh(self, it):
        chip = self.chips.get(it.id)
        if chip is not None:
            chip.sync()
        self._summary()
        self._arm()

    def _tick(self):
        now = time.time()
        live = [i for i in self.items if i.live() and i.req is not None]
        for it in live:
            try:
                got, tot = it.req.receivedBytes(), it.req.totalBytes()
            except RuntimeError:
                continue
            if tot > 0:
                it.total = tot
            last_b, last_t = it.last
            if it.state == "paused":
                it.speed = 0.0
            elif last_t and now > last_t:
                inst = max(0.0, (got - last_b) / (now - last_t))
                it.speed = inst if it.speed == 0 else 0.7 * it.speed + 0.3 * inst
            it.last, it.got = (got, now), got
            chip = self.chips.get(it.id)
            if chip is not None:
                chip.sync()
        self._summary()
        if not any(i.live() for i in self.items):
            self.tick.stop()

    def _summary(self):
        live = [i for i in self.items if i.live()]
        if live:
            sp = sum(i.speed for i in live)
            txt = "%d downloading" % len(live) + (" · %s/s" % human_size(sp) if sp >= 1 else "")
        elif self.items:
            txt = "%d file%s" % (len(self.items), "" if len(self.items) == 1 else "s")
        else:
            txt = "Nothing yet"
        self.sum.setText(txt)
        self.empty.setVisible(not self.items)

    def toggle_pause(self, it):
        if it.job is not None:
            self.pin()
            return
        try:
            if it.req is not None:
                it.req.resume() if it.state == "paused" else it.req.pause()
        except RuntimeError:
            pass
        self.pin()

    def cancel(self, it):
        if it.job is not None:
            it.job.cancel()
            it.job = None
        try:
            if it.req is not None:
                it.req.cancel()
        except RuntimeError:
            pass
        self.remove(it)

    def _drop(self, it):
        if it in self.items:
            self.items.remove(it)
        chip = self.chips.pop(it.id, None)
        if chip is not None:
            self.row.removeWidget(chip)
            chip.hide()
            chip.deleteLater()
        self.reserved.discard(it.path)

    def remove(self, it):
        self._drop(it)
        self.save()
        self._summary()
        self._arm()

    def retry(self, it):
        url, yt = it.url, it.yt
        self.remove(it)
        if yt and yt.get("url") and isinstance(yt.get("opt"), dict):
            self.b.ytdl.start(yt["url"], yt.get("title", ""), yt["opt"])
            return
        t = self.b.cur()
        if url and t is not None:
            t.page().download(QUrl(url))
        else:
            self.b.toast("That download can't be retried", 3000)

    def open_item(self, it):
        if not it.exists():
            self._refresh(it)
            self.b.toast("That file has been moved or deleted", 3000)
            return
        if it.risk >= 2 and self.b.settings.get("dl_scan", True):
            r = QMessageBox.warning(self.b, "Open this file?", "%s\n\n%s.\nOnly open it if you trust where it came from."
                                    % (it.name, it.note), QMessageBox.StandardButton.Open | QMessageBox.StandardButton.Cancel,
                                    QMessageBox.StandardButton.Cancel)
            if r != QMessageBox.StandardButton.Open:
                return
        QDesktopServices.openUrl(QUrl.fromLocalFile(it.path))

    def reveal_item(self, it):
        if not it.exists():
            self._refresh(it)
            return
        import subprocess
        try:
            if sys.platform == "win32":
                subprocess.Popen(["explorer", "/select,", os.path.normpath(it.path)])
            elif sys.platform == "darwin":
                subprocess.Popen(["open", "-R", it.path])
            else:
                QDesktopServices.openUrl(QUrl.fromLocalFile(str(Path(it.path).parent)))
        except OSError:
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(Path(it.path).parent)))

    def delete_file(self, it):
        r = QMessageBox.question(self.b, "Delete file", "Permanently delete %s from your computer?" % it.name,
                                 QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.Cancel,
                                 QMessageBox.StandardButton.Cancel)
        if r != QMessageBox.StandardButton.Yes:
            return
        try:
            os.remove(it.path)
        except OSError as ex:
            self.b.toast("Couldn't delete it: %s" % (ex.strerror or ex), 4000)
            return
        self.remove(it)

    def copy_hash(self, it):
        self.b.toast("Working out the SHA-256 of %s…" % it.name, 3000)
        path, name = it.path, it.name

        def work():
            try:
                h = hashlib.sha256()
                with open(path, "rb") as f:
                    for blk in iter(lambda: f.read(1 << 20), b""):
                        h.update(blk)
                self.hashed.emit(name, h.hexdigest())
            except OSError:
                self.hashed.emit(name, "")
        threading.Thread(target=work, daemon=True).start()

    def _hashed(self, name, digest):
        if digest:
            QApplication.clipboard().setText(digest)
            self.b.toast("SHA-256 of %s copied · %s…" % (name, digest[:16]), 5000)
        else:
            self.b.toast("Couldn't read %s" % name, 3000)

    def clear_finished(self):
        for it in [i for i in self.items if not i.live()]:
            self._drop(it)
        self.save()
        self._summary()
        self._arm()

    def _set(self, key, val):
        self.b.settings[key] = val
        jsave("settings.json", self.b.settings)

    def show_menu(self):
        self.pin()
        st = self.b.settings
        m = QMenu(self)
        for key, label, dflt in (("dl_sort", "Sort into folders by type", False),
                                 ("dl_autohide", "Hide the shelf when downloads finish", True),
                                 ("dl_scan", "Warn about disguised or broken files", True)):
            a = m.addAction(label)
            a.setCheckable(True)
            a.setChecked(bool(st.get(key, dflt)))
            a.triggered.connect(lambda c, k=key: self._set(k, bool(c)))
        m.addSeparator()
        m.addAction("Open downloads folder", lambda: QDesktopServices.openUrl(
            QUrl.fromLocalFile(str(Path.home() / "Downloads"))))
        m.addAction("Clear finished", self.clear_finished)
        m.exec(self.more.mapToGlobal(QPoint(0, 0)) - QPoint(0, m.sizeHint().height() + 6))

    def toggle(self):
        if self.want:
            self.set_open(False)
        else:
            self.pinned = True
            self.set_open(True)

    def pin(self):
        """The person is using the shelf, so it stays put until they close it."""
        self.pinned = True
        self.hide_timer.stop()

    def set_open(self, on):
        self.want = on
        if on:
            self.place()
            if not self.suppressed:
                self.show()
                self.raise_()
        else:
            self.pinned = False
        self._anim.stop()
        self._anim.setStartValue(self.reveal)
        self._anim.setEndValue(1.0 if on else 0.0)
        self._anim.setDuration(260 if on else 190)
        self._anim.start()
        self._arm()

    def _set_reveal(self, v):
        self.reveal = float(v)
        self.place()

    def _anim_done(self):
        if not self.want:
            self.hide()

    def place(self):
        b, root = self.b, self.parentWidget()
        stack = getattr(b, "stack", None)
        if root is None or stack is None:
            return
        tl = stack.mapTo(root, QPoint(0, 0))
        w = max(300, stack.width() - 24)
        base_y = tl.y() + stack.height() - self.H - 12
        self.setGeometry(tl.x() + 12, base_y + int((1.0 - self.reveal) * (self.H + 16)), w, self.H)
        if self.isVisible():
            self.raise_()

    def set_suppressed(self, on):
        """Page fullscreen: tuck the shelf away, and bring it back afterwards if it was open."""
        self.suppressed = on
        if on:
            self.hide()
        elif self.want:
            self.place()
            self.show()
            self.raise_()

    def eventFilter(self, obj, ev):
        if obj is getattr(self.b, "stack", None) and ev.type() in (QEvent.Type.Resize, QEvent.Type.Move) and self.isVisible():
            self.place()
        return False

    def _arm(self):
        busy = any(i.live() for i in self.items)
        if self.want and not self.pinned and not busy and not self.hovered and self.b.settings.get("dl_autohide", True):
            self.hide_timer.start(9000)
        else:
            self.hide_timer.stop()

    def _autohide(self):
        if self.want and not self.pinned and not self.hovered and not any(i.live() for i in self.items):
            self.set_open(False)

    def enterEvent(self, e):
        self.hovered = True
        self.hide_timer.stop()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self.hovered = False
        self._arm()
        super().leaveEvent(e)


# ====================================================================================================
# 49B  YOUTUBE VIDEO DOWNLOADER
# ====================================================================================================

YT_HOSTS = ("youtube.com", "youtu.be", "youtube-nocookie.com")
YT_ID = re.compile(r"^[\w-]{11}$")
YT_INFO_TTL = 600
YT_INFO_CACHE = {}
YT_FORMAT_KEYS = ("vcodec", "acodec", "height", "width", "fps", "filesize", "filesize_approx", "abr", "tbr", "ext")


def yt_video_url(url):
    """The clean watch link for a YouTube video page (no playlist or tracking bits), or '' if this isn't a video page."""
    try:
        u = urlparse(url.toString() if isinstance(url, QUrl) else str(url))
    except ValueError:
        return ""
    if u.scheme not in ("http", "https"):
        return ""
    host = (u.hostname or "").lower()
    if not any(host == h or host.endswith("." + h) for h in YT_HOSTS):
        return ""
    parts = [p for p in u.path.split("/") if p]
    vid = ""
    if host == "youtu.be" or host.endswith(".youtu.be"):
        vid = parts[0] if parts else ""
    elif parts and parts[0] == "watch":
        vid = (parse_qs(u.query).get("v") or [""])[0]
    elif len(parts) >= 2 and parts[0] in ("shorts", "live", "embed", "v"):
        vid = parts[1]
    return "https://www.youtube.com/watch?v=" + vid if YT_ID.match(vid) else ""


def yt_install_hint(what):
    """The one-line command that installs ffmpeg or Deno on this computer."""
    win, mac = sys.platform == "win32", sys.platform == "darwin"
    if what == "ffmpeg":
        return "winget install ffmpeg" if win else "brew install ffmpeg" if mac else "sudo apt install ffmpeg"
    return "winget install DenoLand.Deno" if win else "brew install deno" if mac else "curl -fsSL https://deno.land/install.sh | sh"


def yt_tool():
    """How to run yt-dlp, as a command list: the Python package in this interpreter first (Fjord can update that one itself),
    then a yt-dlp program on PATH or in Fjord's own folder. None if it isn't installed."""
    if not getattr(sys, "frozen", False) and sys.executable:
        try:
            import importlib.util
            if importlib.util.find_spec("yt_dlp") is not None:
                return [sys.executable, "-m", "yt_dlp"]
        except (ImportError, ValueError):
            pass
    exe = shutil.which("yt-dlp") or shutil.which("yt-dlp.exe")
    if not exe:
        for n in ("yt-dlp.exe", "yt-dlp"):
            f = REAL_DATA_DIR / "bin" / n
            if f.is_file():
                exe = str(f)
                break
    return [exe] if exe else None


def yt_has_js():
    """YouTube now needs a JavaScript runtime on the computer for yt-dlp to unscramble its video links."""
    return bool(shutil.which("deno") or shutil.which("node"))


def yt_js_args():
    """yt-dlp finds Deno by itself; if only Node is installed it has to be pointed there."""
    if shutil.which("deno"):
        return []
    return ["--js-runtimes", "node"] if shutil.which("node") else []


def yt_proc(parent):
    """A QProcess set up for yt-dlp: UTF-8 output, and no black console window flashing up on Windows."""
    p = QProcess(parent)
    env = QProcessEnvironment.systemEnvironment()
    env.insert("PYTHONIOENCODING", "utf-8")
    env.insert("PYTHONUTF8", "1")
    p.setProcessEnvironment(env)
    if sys.platform == "win32":
        try:
            p.setCreateProcessArgumentsModifier(lambda a: setattr(a, "flags", a.flags | 0x08000000))
        except Exception:
            pass
    return p


def yt_num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0


def yt_options(info, have_ffmpeg):
    """The choices to offer for a video, built from yt-dlp's format list: one row per picture quality, then audio-only rows.
    Without ffmpeg only ready-made files that already hold picture and sound can be offered, because YouTube keeps HD
    video and audio apart and ffmpeg is what joins them (and what makes MP3s)."""
    fmts = [f for f in (info.get("formats") or []) if isinstance(f, dict)]

    def has(f, k):
        return (f.get(k) or "none") != "none"

    def size(f):
        return int(yt_num(f.get("filesize")) or yt_num(f.get("filesize_approx")))

    video = [f for f in fmts if has(f, "vcodec") and yt_num(f.get("height")) >= 144]
    audio = [f for f in fmts if has(f, "acodec") and not has(f, "vcodec")]
    best_audio = max(audio, key=lambda f: (yt_num(f.get("abr")), size(f)), default=None)
    pool = video if have_ffmpeg else [f for f in video if has(f, "acodec")]
    out = []
    for h in sorted({int(yt_num(f["height"])) for f in pool}, reverse=True)[:6]:
        group = [f for f in pool if int(yt_num(f["height"])) == h]
        best = max(group, key=lambda f: (str(f.get("vcodec") or "").startswith("avc1"), yt_num(f.get("tbr"))))
        sz = size(best) + (size(best_audio) if best_audio is not None and not has(best, "acodec") else 0)
        bits = ["MP4" if have_ffmpeg else str(best.get("ext") or "mp4").upper()]
        w = int(yt_num(best.get("width")))
        if w:
            bits.append("%d\u00d7%d" % (w, h))
        fps = yt_num(best.get("fps"))
        if fps > 30:
            bits.append("%d fps" % round(fps))
        if sz:
            bits.append("~" + human_size(sz))
        if have_ffmpeg:
            sel = "bv*[height=%d][vcodec^=avc1]+ba[ext=m4a]/bv*[height=%d]+ba/b[height<=%d]" % (h, h, h)
        else:
            sel = "b[height=%d]/b[height<=%d]" % (h, h)
        out.append({"key": "v%d" % h, "label": "%dp" % h + (" \u00b7 4K" if h >= 2160 else " \u00b7 HD" if h >= 720 else ""),
                    "desc": " \u00b7 ".join(bits), "sel": sel, "audio": False, "mp3": False, "size": sz,
                    "ext": "mp4" if have_ffmpeg else str(best.get("ext") or "mp4")})
    asz = size(best_audio) if best_audio is not None else 0
    tail = (" \u00b7 ~" + human_size(asz)) if asz else ""
    if have_ffmpeg and (audio or video):
        out.append({"key": "amp3", "label": "Audio \u00b7 MP3", "desc": "Converted, best quality" + tail,
                    "sel": "ba/b", "audio": True, "mp3": True, "size": asz, "ext": "mp3"})
    if audio:
        m4a = any(f.get("ext") == "m4a" for f in audio)
        out.append({"key": "aorig", "label": "Audio \u00b7 M4A" if m4a else "Audio only",
                    "desc": "Original quality, no conversion" + tail,
                    "sel": "ba[ext=m4a]/ba" if m4a else "ba", "audio": True, "mp3": False, "size": asz,
                    "ext": "m4a" if m4a else str(best_audio.get("ext") or "webm")})
    return out


class YtLookup(QObject):
    """Asks yt-dlp what a video is called and which qualities it comes in. Nothing is downloaded."""
    done = pyqtSignal(dict, str)

    def __init__(self, mgr, url):
        super().__init__(mgr)
        self._out, self._err, self._sent, self._dead = b"", b"", False, False
        self.proc = yt_proc(self)
        self.proc.readyReadStandardOutput.connect(self._read_out)
        self.proc.readyReadStandardError.connect(self._read_err)
        self.proc.finished.connect(self._finished)
        self.proc.errorOccurred.connect(self._failed)
        self.timer = QTimer(self)
        self.timer.setSingleShot(True)
        self.timer.timeout.connect(self._timeout)
        cmd = mgr.tool() + yt_js_args() + ["-J", "--no-playlist", "--no-warnings", url]
        self.timer.start(75000)
        self.proc.start(cmd[0], cmd[1:])

    def _read_out(self):
        self._out += bytes(self.proc.readAllStandardOutput())

    def _read_err(self):
        self._err += bytes(self.proc.readAllStandardError())

    def _emit(self, info, err):
        if self._sent or self._dead:
            return
        self._sent = True
        self.timer.stop()
        self.done.emit(info, err)

    def _finished(self, code, _status):
        self._read_out()
        self._read_err()
        info = {}
        try:
            info = json.loads(self._out.decode("utf-8", "replace"))
        except ValueError:
            pass
        if code == 0 and isinstance(info, dict) and info.get("formats"):
            self._emit(info, "")
            return
        lines = [l.strip() for l in self._err.decode("utf-8", "replace").splitlines() if l.strip()]
        errs = [l for l in lines if l.startswith("ERROR")]
        msg = (errs or lines or ["yt-dlp stopped without an answer (code %s)" % code])[-1]
        self._emit({}, re.sub(r"^ERROR:\s*(\[[^\]]+\]\s*[\w-]*:\s*)?", "", msg))

    def _failed(self, err):
        if err == QProcess.ProcessError.FailedToStart:
            self._emit({}, "Couldn't start yt-dlp")

    def _timeout(self):
        self.cancel()
        self._dead = False
        self._emit({}, "yt-dlp took too long to answer. Check your connection and try again.")

    def cancel(self):
        self._dead = True
        self.timer.stop()
        try:
            if self.proc.state() != QProcess.ProcessState.NotRunning:
                self.proc.kill()
        except RuntimeError:
            pass


class YtJob(QObject):
    """One yt-dlp download. Works in a private temp folder (so a cancelled download leaves nothing behind), reports progress
    across the video and audio streams as one bar, and hands back the finished file's path."""
    progress = pyqtSignal(float, float, float, str)    # got, total, speed, stage
    ended = pyqtSignal(bool, str, str)                 # ok, path, error

    def __init__(self, mgr, url, opt, folder):
        super().__init__(mgr)
        self.cancelled = False
        self.folder, self.t0 = folder, time.time()
        self.tmp = tempfile.mkdtemp(prefix="fjord_yt_")
        self._buf, self._path, self._err = "", "", ""
        self._done_bytes, self._expect, self._emit_t = 0.0, float(opt.get("size") or 0), 0.0
        self.proc = yt_proc(self)
        self.proc.setProcessChannelMode(QProcess.ProcessChannelMode.MergedChannels)
        self.proc.readyReadStandardOutput.connect(self._read)
        self.proc.finished.connect(self._finished)
        self.proc.errorOccurred.connect(self._failed)
        ff = mgr.ffmpeg()
        cmd = mgr.tool() + yt_js_args() + [
            "-f", opt["sel"], "--no-playlist", "--newline", "--progress", "-N", "4",
            "-P", folder, "-P", "temp:" + self.tmp, "-o", "%(title).80s.%(ext)s",
            "--progress-template", "download:FJP|%(progress.status)s|%(progress.downloaded_bytes)s|"
                                   "%(progress.total_bytes)s|%(progress.total_bytes_estimate)s|%(progress.speed)s",
            "--print", "after_move:FJDONE|%(filepath)s"]
        if opt.get("audio"):
            if opt.get("mp3"):
                cmd += ["-x", "--audio-format", "mp3", "--audio-quality", "0"]
        elif ff:
            cmd += ["--merge-output-format", "mp4"]
        if ff:
            cmd.append("--embed-metadata")
        self.cmd = cmd + [url]

    def start(self):
        self.proc.start(self.cmd[0], self.cmd[1:])

    def _read(self):
        self._buf += bytes(self.proc.readAllStandardOutput()).decode("utf-8", "replace")
        parts = re.split(r"[\r\n]+", self._buf)
        self._buf = parts.pop()
        for ln in parts:
            self._line(ln.strip())

    def _line(self, ln):
        if ln.startswith("FJP|"):
            f = ln.split("|")
            status = f[1] if len(f) > 1 else ""
            num = lambda i: yt_num(f[i]) if len(f) > i else 0.0
            got, tot, est, sp = num(2), num(3), num(4), num(5)
            tot = tot or est
            now = time.time()
            if status == "finished":
                self._done_bytes += max(got, tot)
                self.progress.emit(self._done_bytes, max(self._expect, self._done_bytes), 0.0, "")
                return
            if now - self._emit_t < 0.2:
                return
            self._emit_t = now
            have = self._done_bytes + got
            total = max(self._expect, self._done_bytes + tot, have)
            self.progress.emit(have, total, sp, "")
        elif ln.startswith("FJDONE|"):
            self._path = ln[7:].strip()
        elif ln.startswith("[Merger]"):
            self._stage("Merging video and audio\u2026")
        elif ln.startswith("[ExtractAudio]"):
            self._stage("Converting audio\u2026")
        elif ln.startswith(("[VideoRemuxer]", "[VideoConvertor]", "[Metadata]", "[EmbedThumbnail]", "[Fixup")):
            self._stage("Finishing up\u2026")
        elif ln.startswith("ERROR"):
            self._err = ln

    def _stage(self, text):
        total = max(self._expect, self._done_bytes)
        self.progress.emit(total, total, 0.0, text)

    def _short_err(self, code):
        msg = re.sub(r"^ERROR:\s*(\[[^\]]+\]\s*[\w-]*:\s*)?", "", self._err).strip()
        if "ffmpeg" in msg.lower() or "ffprobe" in msg.lower():
            return "ffmpeg is needed for this format (%s)" % yt_install_hint("ffmpeg")
        return msg[:140] or "yt-dlp stopped (code %s)" % code

    def _newest_file(self):
        """Fallback when the printed path got mangled by the console's text encoding: the newest finished file in the folder."""
        try:
            files = [p for p in Path(self.folder).iterdir() if p.is_file() and not p.name.endswith((".part", ".ytdl", ".temp"))
                     and p.stat().st_mtime >= self.t0 - 2]
            return str(max(files, key=lambda p: p.stat().st_mtime)) if files else ""
        except OSError:
            return ""

    def _finished(self, code, _status):
        self._read()
        if self._buf.strip():
            self._line(self._buf.strip())
            self._buf = ""
        shutil.rmtree(self.tmp, ignore_errors=True)
        if self.cancelled:
            return
        path = self._path if self._path and os.path.exists(self._path) else (self._newest_file() if code == 0 else "")
        if code == 0 and path:
            self.ended.emit(True, path, "")
        else:
            self.ended.emit(False, "", self._short_err(code))

    def _failed(self, err):
        if err == QProcess.ProcessError.FailedToStart and not self.cancelled:
            shutil.rmtree(self.tmp, ignore_errors=True)
            self.ended.emit(False, "", "Couldn't start yt-dlp")

    def cancel(self):
        self.cancelled = True
        try:
            if self.proc.state() != QProcess.ProcessState.NotRunning:
                self.proc.kill()
            else:
                shutil.rmtree(self.tmp, ignore_errors=True)
        except RuntimeError:
            pass


class YtDownloads(QObject):
    """Owns everything video-download related for a window: finds yt-dlp and ffmpeg, runs lookups and downloads, and installs or
    updates yt-dlp when the person asks."""
    def __init__(self, win):
        super().__init__(win)
        self.win = win
        self.jobs = []
        self.installer = None
        self._inst_out = b""
        app = QApplication.instance()
        if app is not None:
            app.aboutToQuit.connect(self.kill_all)

    def tool(self):
        return yt_tool()

    @staticmethod
    def ffmpeg():
        return bool(shutil.which("ffmpeg"))

    def lookup(self, url):
        return YtLookup(self, url)

    def folder_for(self, kind):
        base = Path.home() / "Downloads"
        sub = DL_TYPES[kind][1]
        folder = base / sub if (self.win.settings.get("dl_sort", False) and sub) else base
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError:
            folder = base
            base.mkdir(exist_ok=True)
        return folder

    def start(self, url, title, opt):
        if not self.tool():
            self.win.toast("yt-dlp isn't installed yet. Click the download button and choose Install.", 5000)
            return None
        folder = self.folder_for("audio" if opt.get("audio") else "video")
        job = YtJob(self, url, opt, str(folder))
        self.jobs.append(job)
        job.ended.connect(lambda *_a, j=job: self._forget(j))
        self.win.dlshelf.add_job(job, title, url, opt)
        job.start()
        return job

    def _forget(self, job):
        if job in self.jobs:
            self.jobs.remove(job)
        job.deleteLater()

    def kill_all(self):
        for j in list(self.jobs):
            j.cancel()

    def installing(self):
        return self.installer is not None

    def install(self, update=False):
        """Install (or update) yt-dlp. Runs in the background; the result shows as a message at the bottom of the window."""
        if self.installer is not None:
            return
        tool = self.tool()
        standalone = bool(tool) and tool[0] != sys.executable
        if standalone:
            cmd = tool + ["-U"]
        elif getattr(sys, "frozen", False) or not sys.executable:
            self.win.toast("Please install yt-dlp yourself:  pip install -U \"yt-dlp[default]\"", 9000)
            return
        else:
            cmd = [sys.executable, "-m", "pip", "install", "-U", "yt-dlp[default]"]
        p = yt_proc(self)
        p.setProcessChannelMode(QProcess.ProcessChannelMode.MergedChannels)
        self._inst_out = b""
        p.readyReadStandardOutput.connect(lambda: setattr(self, "_inst_out", (self._inst_out + bytes(p.readAllStandardOutput()))[-4000:]))
        p.finished.connect(lambda code, _s: self._installed(code, update))
        p.errorOccurred.connect(lambda err: self._installed(-1, update) if err == QProcess.ProcessError.FailedToStart else None)
        self.installer = p
        self.win.toast(("Updating" if update else "Installing") + " yt-dlp\u2026 this takes a few seconds", 120000)
        p.start(cmd[0], cmd[1:])

    def _installed(self, code, update):
        p, self.installer = self.installer, None
        if p is None:
            return
        p.deleteLater()
        if code == 0:
            try:
                import importlib
                importlib.invalidate_caches()
            except Exception:
                pass
            YT_INFO_CACHE.clear()
            self.win.toast("yt-dlp is ready. Click the download button again.", 6000)
        else:
            tail = self._inst_out.decode("utf-8", "replace").strip().splitlines()
            if any("externally-managed" in l for l in tail):
                why = "your Python is managed by the system. Try:  pipx install yt-dlp"
            else:
                why = "run  pip install -U \"yt-dlp[default]\"  in a terminal, then try again"
            self.win.toast("Couldn't %s yt-dlp automatically: %s" % ("update" if update else "install", why), 12000)


class YtRow(SpeedRow):
    """One quality choice in the video download popup. Same look as the speed popup's rows."""
    class _Kinds:
        @staticmethod
        def get(key, default=None):
            return "music" if str(key).startswith("a") else "play"
    KIND = _Kinds()
    TINT = {}

    def __init__(self, opt):
        super().__init__(opt["key"], {"label": opt["label"], "desc": opt["desc"]}, False)
        self.opt = opt
        self.setFixedHeight(48)


class VideoDownloadPopup(GlassPopup):
    """Popup under the toolbar's download button: it looks up the video, lists the qualities and audio formats it comes in,
    and the one you click starts downloading onto the download shelf."""
    GUARD = "_ytpop_closed"

    def __init__(self, win, url, page_title=""):
        super().__init__(win)
        self.url, self.anchor, self.title = url, None, page_title
        self._picked, self.rows, self.job = False, [], None
        self.setObjectName("privdash")
        self.setFixedWidth(360)
        self.setStyleSheet(themed(PrivacyDashboard._qss()))
        lay = QVBoxLayout(self)
        lay.setContentsMargins(14, 14, 14, 14)
        lay.setSpacing(8)
        t = QLabel("~/download" if term_on() else "Download video")
        t.setObjectName("hd")
        self.sub = QLabel()
        self.sub.setObjectName("sub")
        self.sub.setWordWrap(True)
        lay.addWidget(t)
        lay.addWidget(self.sub)
        self.box = QVBoxLayout()
        self.box.setSpacing(6)
        lay.addLayout(self.box)
        self.foot = QLabel()
        self.foot.setObjectName("sub")
        self.foot.setWordWrap(True)
        self.foot.hide()
        lay.addWidget(self.foot)
        self.btns = QHBoxLayout()
        self.btns.setSpacing(8)
        lay.addLayout(self.btns)
        self._begin()

    # -- layout helpers -------------------------------------------------------------------------

    def show_under(self, button):
        self.anchor = button
        self._place()
        self.show()

    def _place(self):
        self.adjustSize()
        b = self.anchor
        if b is None:
            return
        pos = b.mapToGlobal(b.rect().bottomLeft()) + QPoint(0, 6)
        scr = b.screen().availableGeometry()
        pos.setX(max(scr.left() + 8, min(pos.x(), scr.right() - self.width() - 8)))
        pos.setY(max(scr.top() + 8, min(pos.y(), scr.bottom() - self.height() - 8)))
        self.move(pos)

    def _note(self, text):
        self.foot.setText(text)
        self.foot.setVisible(bool(text))

    def _actions(self, *pairs):
        while self.btns.count():
            w = self.btns.takeAt(0).widget()
            if w is not None:
                w.deleteLater()
        for label, fn in pairs:
            b = QPushButton(label)
            b.setObjectName("pbtn")
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _c=False, f=fn: f())
            self.btns.addWidget(b)
        if pairs:
            self.btns.addStretch(1)

    def _clear_rows(self):
        for r in self.rows:
            self.box.removeWidget(r)
            r.hide()
            r.deleteLater()
        self.rows = []

    def _set_title(self, text):
        self.sub.setText(QFontMetrics(self.sub.font()).elidedText(text, Qt.TextElideMode.ElideRight, 320) if text else "")

    # -- the three states: needs yt-dlp, looking up, ready / failed -----------------------------------

    def _begin(self):
        mgr = self.win.ytdl
        self._clear_rows()
        self._actions()
        self._note("")
        if mgr.installing():
            self.sub.setText("yt-dlp is being installed. Try again in a moment.")
            return
        if not mgr.tool():
            self.sub.setText("Fjord saves videos with yt-dlp, a free open-source tool. It isn't installed yet.")
            self._actions(("Install yt-dlp", lambda: self._install(False)))
            return
        hit = YT_INFO_CACHE.get(self.url)
        if hit and time.time() - hit[0] < YT_INFO_TTL:
            self._ready(hit[1])
            return
        self.sub.setText("Looking up formats\u2026")
        self.job = mgr.lookup(self.url)
        self.job.done.connect(self._looked)

    def _looked(self, info, err):
        self.job = None
        if err or not info:
            self._fail(err or "Couldn't read this video.")
            return
        slim = {"title": info.get("title") or "",
                "formats": [{k: f.get(k) for k in YT_FORMAT_KEYS} for f in (info.get("formats") or []) if isinstance(f, dict)]}
        if len(YT_INFO_CACHE) > 12:
            YT_INFO_CACHE.pop(next(iter(YT_INFO_CACHE)))
        YT_INFO_CACHE[self.url] = (time.time(), slim)
        self._ready(slim)

    def _ready(self, info):
        mgr = self.win.ytdl
        opts = yt_options(info, mgr.ffmpeg())
        self.title = info.get("title") or self.title
        self._set_title(self.title)
        if not opts:
            self._fail("No downloadable formats were found for this video.")
            return
        for o in opts:
            row = YtRow(o)
            row.clicked.connect(lambda _c=False, op=o: self._pick(op))
            self.box.addWidget(row)
            self.rows.append(row)
        notes = []
        if not mgr.ffmpeg():
            notes.append("Install ffmpeg (%s) and restart Fjord to unlock HD and MP3." % yt_install_hint("ffmpeg"))
        if not yt_has_js():
            notes.append("No JavaScript runtime found, so some qualities may be missing. Install Deno (%s)." % yt_install_hint("deno"))
        self._note("\n".join(notes))
        self._place()

    def _fail(self, msg):
        low = msg.lower()
        self.sub.setText(msg[:220])
        youtube_side = any(k in low for k in ("not available", "sign in", "javascript", "nsig", "signature", "403",
                                              "requested format", "unable to extract", "no supported"))
        if youtube_side and not yt_has_js():
            self._note("YouTube now needs a JavaScript runtime for this. Install Deno (%s), restart Fjord and try again." % yt_install_hint("deno"))
        elif youtube_side:
            self._note("YouTube changes often, so updating yt-dlp usually fixes this.")
        self._actions(("Update yt-dlp", lambda: self._install(True)), ("Try again", self._retry))
        self._place()

    def _retry(self):
        self._begin()
        self._place()

    def _install(self, update):
        self.win.ytdl.install(update)
        self.close()

    def _pick(self, opt):
        if self._picked:
            return
        self._picked = True
        for r in self.rows:
            r.set_selected(r.opt["key"] == opt["key"])
        self.win.ytdl.start(self.url, self.title, opt)

        def done():
            try:
                self.close()
            except RuntimeError:
                pass
        QTimer.singleShot(260, done)

    def _before_close(self):
        if self.job is not None:
            self.job.cancel()
            self.job = None


