def style_icon(key, color="#b5c6d4"):
    """Monochrome menu icon for an interface style (Fjord waves / Apple / Windows)."""
    pm = QPixmap(36, 36)
    pm.fill(Qt.GlobalColor.transparent)
    pp = QPainter(pm)
    draw_glyph(pp, STYLE_GLYPHS.get(key, "ui_default"), QRectF(4, 4, 28, 28), QColor(color), 2.4)
    pp.end()
    pm.setDevicePixelRatio(2.0)
    return QIcon(pm)


def resource_path(name):
    """Find a bundled file both when run as a script and when packaged by PyInstaller."""
    base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base, name)


class MacMotion(QObject):
    """macOS style only: menus and dialogs ease in (a quick fade with a small slide) instead of snapping onto the screen."""
    def eventFilter(self, obj, ev):
        if ev.type() != QEvent.Type.Show or UI["mode"] != "mac":
            return False
        try:
            if isinstance(obj, _QMenu) and not isinstance(obj, QMenu) and obj.isWindow():
                self._ease(obj, 7, 200)
            elif isinstance(obj, QDialog) and obj.isWindow():
                self._ease(obj, 0, 240)
        except RuntimeError:
            pass
        return False

    def _ease(self, w, dy, ms):
        if getattr(w, "_mm_run", False):
            return
        w._mm_run = True
        w.setWindowOpacity(0.0)

        def fin():
            w._mm_run = False

        def go():
            try:
                if not w.isVisible():
                    w.setWindowOpacity(1.0)
                    w._mm_run = False
                    return
                end = w.pos()
                if dy:
                    start = QPoint(end.x(), end.y() - dy)
                    w.move(start)
                    animate(w, b"pos", start, end, ms)
                animate(w, b"windowOpacity", 0.0, 1.0, ms, done=fin)
            except RuntimeError:
                pass
        QTimer.singleShot(0, go)


def main():
    if "--adblock-selftest" in sys.argv[1:]:
        sys.exit(adblock_selftest())
    if sys.platform == "win32":
        import ctypes
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("fjord.browser.1")
    restarted = bool(os.environ.pop("FJORD_RESTARTED", None))
    no_forward = bool(os.environ.pop("FJORD_NO_FORWARD", None))
    if restarted:
        time.sleep(2.5)
    sweep_private_dirs()
    if not PRIVATE:
        cleanup_old_update()
    app = QApplication(sys.argv)
    app.setApplicationName("Fjord")
    if not PRIVATE and not restarted and not no_forward and forward_to_running(sys.argv[1:]):
        sys.exit(0)
    app._mac_motion = MacMotion(app)
    app.installEventFilter(app._mac_motion)
    app.setWindowIcon(QIcon(resource_path("fjord.ico")))
    DATA_DIR.mkdir(exist_ok=True)
    try:
        os.chmod(str(DATA_DIR), 0o700)
    except OSError:
        pass

    def _hook(et, ev, tb):
        try:
            import traceback
            text = "".join(traceback.format_exception(et, ev, tb))
            if text not in _LOGGED_ERRORS:
                _LOGGED_ERRORS.add(text)
                with open(str(DATA_DIR / "crash.log"), "a", encoding="utf-8") as f:
                    f.write("--- uncaught [%s]\n%s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), text))
        except Exception:
            pass
    sys.excepthook = _hook
    try:
        import faulthandler
        app._crash_log = open(str(DATA_DIR / "crash.log"), "a")
        faulthandler.enable(app._crash_log)
    except Exception:
        pass
    load_custom_fonts()
    UI["mode"] = valid_ui_mode(jload("settings.json", {}).get("ui_style"))
    load_ui_tuning(jload("settings.json", {}))
    TERM["on"] = bool(jload("settings.json", {}).get("private_terminal", True))
    TERM["normal"] = bool(jload("settings.json", {}).get("terminal_normal", False))
    UI["radius"] = 12 if term_on() else 100
    apply_font(app, pick_font(jload("settings.json", {}).get("font")))
    win = Browser()
    win.setWindowOpacity(0.0)
    if sys.platform == "win32":
        win.show()
        win._set_filled(True)
    else:
        win.showMaximized()
    animate(win, b"windowOpacity", 0.0, 1.0, 380)
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
